/* ⚠ 自动生成，勿手改 —— 源：client/prototype/grove.html
   重新生成：python client/tools/extract_grove_runtime.py

   这是推球玩法的**引擎无关运行时**（物理 / 关卡 / 波次 / BOSS / 冰壳 / 球）。
   绘制同样原样保留：一套 Canvas 2D 代码（960x600），由 GroveBattle 组件
   喂一块离屏画布，再把画布贴成 Cocos 纹理。

   导出：
     groveAttachCanvas(canvas)  绑定画布
     groveBoot(hero?, stage?)   开一局（不传就按存档推）
     groveTick(dt) / groveRender()
     groveSetExitHook(fn)       "收工 / ESC 退出"交给 Cocos 处理
     groveSetArt(key, img)      注入美术图（pet-cat / head-cat / ui-coin …）
     GROVE                      调试导出（和浏览器里的 window.GROVE 同一份）
   ========================================================================= */

"use strict";

/* ============================================================================
   PAWPACK · 林地  V1
   ----------------------------------------------------------------------------
   单角色出战的雪人式关卡。跟 Snow Bros 的差别集中在三条规则上，
   它们合起来构成这一版想验证的"微创新"：

   ① 敌人**没有血量**，只有 3 格包裹槽。
      攻击不扣血，只是往身上糊一层苔。糊满 3 层 -> 变成一颗滚球。
      于是"输出"和"控制"变成同一件事，屏幕上不需要血条。

   ② 球会**造球**。
      滚球撞到敌人，给那个敌人 +1 层包裹（泥坑里 +2）。
      已经裹了两层的，被球一撞就当场变成新球，以 70% 速度朝原方向继续滚。
      所以一颗球可以滚出一场风暴 —— 前提是你**提前把整层敌人各喷了两下**。
      这就是"先铺场，再引爆"，是原版没有的一层规划。

   ③ 落地位置决定这颗球的价值（地形分岔）。
      火坑：直接烧掉，收成 ×2，但**断连锁**（球没了，后面的人撞不到）
      泥坑：球裹上泥，变重，之后每次撞人 +2 层 —— 强化通道
      营地：落袋，收成 ×1 且额外 +1 —— 稳妥
      所以"往哪推"不是清场方向问题，是"我这一球想要什么"的问题。

   ④ 推关制（这一版加的）。
      选一只 → 第 1 关 → 结算停 3 秒自动进下一关。不回关卡列表，
      因为一回到列表，人就会开始挑着打，推关的手感就断了。
      进度存 localStorage，关掉再打开从上次那关继续。

   ⑤ 六把武器，作用方式全不一样（这一版重做）。
      溜溜球（去回）/ 音波喇叭（原地扇形）/ 滚坚果（贴地滚）/
      萝卜炮（抛物线）/ 飞刀（丢出去，自旋穿透）/ 影分身（召唤两个分身替你打）。
      命中效果完全相同，差异化只在怎么打到 —— 这是推球游戏，不是弹幕游戏。
      上一版六把全是"飞出去一颗东西"，只有形状差别；现在至少四把连"东西"都不是：
      音波是范围、坚果是地面滚动物、飞刀是一次性投掷、分身是召唤物。

   ⑥ Q 版战斗场景（这一版改的）。
      原来画的是暗色森林剪影，读起来像横版探险。现在每关一套主题色，
      天空要亮、云山树全用圆弧、所有东西都有深色粗描边 —— 像贴纸，不像写实。

   ⑦ 球是"一次性"的（这一版改的）。
      被玩家推出去的球有 3.2 秒寿命，撞两次墙就散。以前地面无摩擦 + 撞墙只衰减，
      底层会永远有几颗球在溜达，玩家分不清"哪颗还能用、哪颗是上一波的残骸"。

   ⑧ 宝箱只从"球送走的人"身上掉（这一版加的）。
      火坑/营地结算时按这一球**连带送走几只**判概率：单杀 14%、两只 38%、三只 62%。
      武器糊不死人（只糊层），所以"只有雪人式击杀才有宝箱"是机制自带的，不用额外判。
   ========================================================================== */

/* ---------- 画布 ---------- */
let cv: any = null;
let ctx: any = null;
const W = 960, H = 600;


/* ---------- 工具 ---------- */
const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
const lerp = (a, b, t) => a + (b - a) * t;
// 随机数统一走 S.rng，别直接 Math.random。
// 不然一局里敌人的巡逻方向、粒子的散射角度都不可复现，
// 同一个 bug 跑两次能不能复现全看运气 —— 测试就没意义了。
function rand(a, b) { return a + S.rng() * (b - a); }
const sign = (v) => (v < 0 ? -1 : 1);

/** 圆角矩形路径（不 fill，交给调用方决定画法） */
function rr(g, x, y, w, h, r) {
  const k = Math.min(r, w / 2, h / 2);
  g.beginPath();
  g.moveTo(x + k, y);
  g.lineTo(x + w - k, y);
  g.quadraticCurveTo(x + w, y, x + w, y + k);
  g.lineTo(x + w, y + h - k);
  g.quadraticCurveTo(x + w, y + h, x + w - k, y + h);
  g.lineTo(x + k, y + h);
  g.quadraticCurveTo(x, y + h, x, y + h - k);
  g.lineTo(x, y + k);
  g.quadraticCurveTo(x, y, x + k, y);
  g.closePath();
}

/** 确定性伪随机：同一个 seed 每帧同一条曲线，否则背景会抖成雪花屏 */
function hash(i) {
  const v = Math.sin(i * 127.1 + 311.7) * 43758.5453;
  return v - Math.floor(v);
}

/* ============================================================================
   1. 角色
   ----------------------------------------------------------------------------
   六只宠物都能出战，但**一局只能带一只**。它们不是换皮：
   `fire()` 里的弹道形状是真的不一样，玩家按一下就知道自己换了人。
   ========================================================================== */

/* ----------------------------------------------------------------------------
   我方单位
   ----------------------------------------------------------------------------
   一局带一只，所以六只必须**按一下就知道换了人**。判据不是数值不同，
   是弹道形状不同 —— 玩家不看 UI 也能从手感上认出来。

     尖耳猫  溜溜球    甩出去、拉回来，来回都能打。站位对了能打两遍
     短尾犬  音波喇叭  原地吼一圈。射程最短、覆盖最宽，专治贴身围殴
     胖仓鼠  滚坚果    贴地滚，穿透，撞墙弹一次。地上有人的时候最好用
     长耳兔  萝卜炮    抛物线，落点炸一片。唯一能打"高台背面"的
     老实牛  飞刀      丢出去，高速自转，穿两个人。丢完就没了，不回收
     影狐    影分身    召两个分身站你左右，替你吐影弹。分身不走，得自己找角度

   后两把是用户点名要改的：飞刀"是丢出去的，不是环绕的"；
   分身上一版是三道平推的残影，读起来只是"三个白药丸"，现在改成真正的召唤物。

   注意：这些弹丸打中的效果**都一样**（+1 层包裹）。不做元素克制、
   不做伤害数字 —— 这是推球游戏，不是弹幕游戏。差异化只在"怎么打到"。
   ========================================================================== */

/* ----------------------------------------------------------------------------
   美术图（可选注入）
   ----------------------------------------------------------------------------
   grove.html 要能双击打开、零外部依赖，所以这里**不引用任何图片文件**。
   图片只在 Cocos 里由 GroveBattle 通过 resources.load 加载后注进来：
   有图就贴图，没图回退到下面的代码图形 —— 两套并存，谁也不会坏。

   键名约定：pet-<heroId> / head-<heroId> / ui-<name>
   （heroId 见 HEROES[].id：cat / dog / ham / rab / ox / fox）
   -------------------------------------------------------------------------- */
const ART = Object.create(null);

/**
 * 注入一张美术图。
 * img 可以是 HTMLImageElement / ImageBitmap / HTMLCanvasElement —— 只要能被
 * drawImage 直接吃掉。传 null 就是撤掉（回退代码图形）。
 */
function groveSetArt(key, img) {
  if (img) ART[key] = img; else delete ART[key];
}

/** 取图；没注入或图还没解码完（宽高为 0）都返回 null，让调用方走回退分支。 */
function artOf(key) {
  if (!key) return null;
  const a = ART[key];
  if (!a) return null;
  const w = a.width || a.naturalWidth || 0;
  return w > 0 ? a : null;
}

/* ----------------------------------------------------------------------------
   手感常量。**放在 HEROES 之前**，因为绘制、物理、预瞄线三处都要读同一份 ——
   上一版推球初速在 updatePlayer 里写 620、在 predictBall 里也写 620，
   两处各写一遍，改一处忘一处的时候，预测线就会开始骗人。
   -------------------------------------------------------------------------- */
/** 施法动作时长（秒）。0.16 太快，肉眼只看到闪白；0.26 够走完"后坐 → 前冲 → 回落" */
const CAST_T = 0.30;
/** 站着不动推球的初速。
 *  **这个数不能随手加大。** 试过 800：泥沼/阶梯塔直接从"能进营地"变成
 *  "全图一次都推不进去" —— 球从平台上被推出去是抛物线，初速一变落点就整体前移，
 *  正好落进营门前那道火坑。八关的落点都是按 620 摆的，动它就是动关卡。 */
const PUSH_BASE = 620;
/** 助跑满格再加多少（620 → 1209）。跑满约 380px */
const PUSH_RUN = 0.95;
/** 推出去的球多久散掉。3.2 秒只够滚 1984px，很多关推出去滚一半就没了 ——
 *  读作"球推不动"。4.6 秒足够滚穿一整屏再回来。 */
const PUSH_LIFE = 4.6;

