/* ============================================================================
   3.5 目标
   ----------------------------------------------------------------------------
   七种目标，四种是"多做一点"，三种是"不许做某事"。后三种才真的会改写最优解：

     clear    清场   人都送走，怎么推都行                        —— 考手
     limit    限球   只给 N 颗球，剩下的靠卷                       —— 考铺场
     chain    连锁   一颗球装够 N 只                               —— 考顺序
     bank     落袋   N 只必须走营地                               —— 考地形
     collect  收成   收成攒够 N（火坑 ×2，营地只有 +1）            —— 唯一逼你贪的
     intact   零崩   一颗球都不许崩                               —— 不许磨蹭
     nohit    无伤   一次都不能被打                               —— 不许贴脸

   目标数字全部拿机器人跑 `tools/grove-diag.js` 量过，不是拍脑袋。
   ========================================================================== */

const GOALS = {
  clear: {
    id: "clear", name: "清场", verb: "送走全部",
    brief: (st, n) => "把 " + n + " 只全送走，怎么推都行",
  },
  limit: {
    id: "limit", name: "限球", verb: "只用 ",
    brief: (st) => "最多造 " + st.ballLimit + " 颗球，多出来的都靠「卷」",
  },
  chain: {
    id: "chain", name: "连锁", verb: "一球 ",
    brief: (st) => "有一颗球里要装够 " + st.chain + " 只",
  },
  bank: {
    id: "bank", name: "落袋", verb: "走营地 ",
    brief: (st) => "至少 " + st.bank + " 只要从营地送走（火坑不算）",
  },
  collect: {
    id: "collect", name: "收成", verb: "攒够 ",
    brief: (st) => "收成攒到 " + st.collect + " —— 火坑 ×2，是唯一够快的路子",
  },
  intact: {
    id: "intact", name: "零崩", verb: "不许崩",
    brief: () => "一颗球都不许漏气崩开 —— 推得慢就是输",
  },
  nohit: {
    id: "nohit", name: "无伤", verb: "不许挨打",
    brief: () => "一次都不能被碰到 —— 预瞄线要用来躲，不只是用来推",
  },
};

/** 当前场景的四件套 + 三种特殊件。loadLevel() 换掉它们，其余代码照旧引用。 */
let PLATS = LEVELS[0].plats;
let PITS = LEVELS[0].pits;
let STUMPS = LEVELS[0].stumps || [];
let CAMP = LEVELS[0].camp;
let WAVES = LEVELS[0].waves;
let PLAYER_SPAWN = LEVELS[0].spawn;
let RAMPS = [];
let BOUNCERS = [];
let PORTALS = [];

/** 当前关的主题配色。背景/平台/空气中的浮尘都从这里取色 */
let TH = THEMES[LEVELS[0].theme];

/** 把一关装进全局绑定。没写的特殊件一律给空数组，代码不用到处判 null */
function loadLevel(i) {
  const L = LEVELS[i] || LEVELS[0];
  TH = THEMES[L.theme] || THEMES.tundra;
  PLATS = L.plats;
  PITS = L.pits;
  STUMPS = L.stumps || [];
  CAMP = L.camp;
  RAMPS = L.ramps || [];
  BOUNCERS = L.bouncers || [];
  PORTALS = L.portals || [];
  WAVES = L.waves;
  PLAYER_SPAWN = L.spawn;
}

/* ---- 坡面剖面 --------------------------------------------------------------
   坡不是"一根斜着的方木"，是**一段弯下去的路面**。

   上一版画的是"旋转过的圆角矩形、厚度垂直于坡面"。这带来三个问题，
   单看每一个都小，叠起来就变成用户嘴里那句"像是个木头接上去的"：
     ① 厚度垂直于坡面 → 接平台那一端，台面下方鼓出一个楔形；
     ② 两端是斜切面（旋转过的圆角）→ 和水平的台面顶面之间有一道折角；
     ③ 砖缝垂直于坡面 → 像梯子横档，不像一条路。

   现在换成"路面剖面"：一条顶面曲线，**沿竖直方向**量厚度，
   两端切线缓入缓出贴近水平，砖缝照旧竖直。这样它读起来是
   "台面在尽头弯了下去"，而不是"有人把木头架在台子边上"。

   物理和绘制共用这一个函数，所以永远不会有"人和画面对不上"的问题。
   -------------------------------------------------------------------------- */

// 缓入缓出的强度。0 = 纯直线（端头有折角）；1 = 纯 smoothstep（端点导数严格为 0）。
//
// **必须等于 1。** 这不是手感调参，是几何约束：
// 接缝处平台顶面是水平线（导数 0），坡顶的切线也必须是 0，两条轮廓才连成一条光滑曲线。
// 上一版 0.82 留下 10° 的残余夹角 —— 10° 在 2D 侧视图里就是一道看得见的折角，
// 无论把木纹画得多细，它都会被读成"两根木头对接"。这就是"接上去"的数学来源。
//
// 代价是中段更陡（峰值导数 1.5 倍），所以坡度必须同步加长：
// 峰值斜率 = 1.5·H/W，要压在 32° 以内，需要 W ≥ 2.4H。数据侧已经按这个重排。
// 物理和绘制共用这一个函数，所以画面和手感永远同步，不会出现"人画对不上"。
const RAMP_EASE = 1.0;

/** s ∈ [0,1] → 缓动后的进度。端点导数是 1-RAMP_EASE，中段略大于 1。 */
function rampProfile(s) {
  const e = 3 * s * s - 2 * s * s * s;
  return s + (e - s) * RAMP_EASE;
}
/** 上式的导数。用来算某一点的坡度。 */
function rampProfileD(s) {
  return 1 + (6 * s - 6 * s * s - 1) * RAMP_EASE;
}
/** 坡在某个 x 处的顶面高度（超出范围按两端水平夹住）。 */
function rampSurfY(r, x) {
  const s = clamp((x - r.x) / r.w, 0, 1);
  return r.yL + (r.yR - r.yL) * rampProfile(s);
}

/** 球/人是否"贴"在这条坡面上。
 *
 *  只看两件事：离坡面够近，或者这一帧从坡面上方穿了进来。
 *
 *  上一版只看 `y >= rp.y - 6` —— 那读作"在坡面下方不超过 6px"，
 *  但**地面上的东西永远满足它**：第 3 关那条悬空滑梯挂在 350→462，
 *  从底下路过的球会被一把抓到 350，瞬移 200px。人也是一样。
 *  这条判据是本轮加缓动剖面时暴露出来的，但 bug 一直都在。 */
function onRampSurface(y, rp, prevY, tol) {
  const T = tol === undefined ? 20 : tol;
  if (Math.abs(y - rp.y) <= T) return true;
  return prevY <= rp.y && y >= rp.y;     // 高速下落：这一帧跨过了坡面
}

/** 斜坡在某个 x 处的表面高度；不在任何斜坡上返回 null */
function rampAt(x) {
  for (const r of RAMPS) {
    if (x < r.x || x > r.x + r.w) continue;
    const s = (x - r.x) / r.w;
    // slope 沿用原口径：向右下降为正（= -dy/dx）。
    // 球的 `vx -= GRAV * slope * 0.45 * dt` 靠这个符号决定"下坡加速"。
    const slope = (r.yL - r.yR) * rampProfileD(s) / r.w;
    return { y: rampSurfY(r, x), slope, x0: r.x, w: r.w, r };
  }
  return null;
}

/* ============================================================================
   4. 状态
   ========================================================================== */

const S = {
  phase: "select",      // select(选人) | play | clear | fail —— 没有选关这一站，是推关
  stage: 0,             // 当前关卡索引
  progress: 0,          // 推到第几关（存档用，通关 +1）
  playT: 0,             // 这一关的战斗用时。和 S.t 分开：S.t 是动画钟，结算后还要走
  clearT: 0,            // 结算面板已经停了多久（到点自动进下一关）
  best: new Array(LEVELS.length).fill(null),   // 每关最佳评价（"S"/"A"/"B"/null）
  t: 0,                 // 全局动画钟（云、火苗、闪烁都靠它）
  heroIdx: 0,

  p: null,              // 玩家
  foes: [],
  shots: [],
  balls: [],
  frags: [],            // 碎片 / 粒子
  texts: [],            // 飘字

  food: 0,              // 收成
  killed: 0,            // 已消灭
  total: 0,
  // 球的归宿统计。用来回答"为什么打不完"：是造不出来，还是推不到位
  stat: { made: 0, burned: 0, banked: 0, burst: 0, drowned: 0, hits: 0, bankHolds: 0, maxHolds: 0 },

  // 关卡可破坏件（每局重建，不能直接改 PLATS 常量）
  stumps: [],
  // 木桩被打碎后留下的"果"，捡了加收成
  drops: [],

  shake: 0,
  flash: 0,
  hitStop: 0,
  // 波次：一关分 2~3 波，最后一波是 BOSS。波次不是"清完再刷"，
  // 是"剩 1 只就刷"—— 见 tick 里那段理由。
  wave: 0,              // 当前第几波（0 起）
  waveT: 0,             // 这一波已经打了多久
  waveGap: 0,           // >0 = 下一波正在预告（倒计时）
  shocks: [],           // BOSS 砸地产生的贴地冲击波
  foeShots: [],         // BOSS 扇形喷出来的粘液弹
  failWhy: "",          // 失败原因，结算面板要说清楚是哪一条没做到
  aim: false,           // 按住 Shift：强制显示所有球的预测线

  // 家门口的动画状态。leaveT 只在"已经选了一只、正在跑出门"时往前走。
  // pick = -1 表示还在等选择。**选人和出门是两个阶段**，
  // 因为"其余五只的反应"只在这 1.6 秒里存在 —— 一按就进关，这段就白做了。
  door: { t: 0, pick: -1, leaveT: 0 },

  /* ---------- 一趟 ----------
   * "一趟" = 从家门口出发，一直往里推，推到收工或倒下。
   * 它存在的唯一理由：让"再贪一关"有代价、也有收益。
   *
   *   loot  这一趟已经攒下的收成（每过一关累加）
   *   multi 连锁倍率 = 1 + 0.15 × 已过关数（上限 2.0）。**收工才结算**，
   *         所以每关都收工的人永远拿 ×1.0，贪到底的人拿 ×2.0。
   *         这是"贪"的收益，而代价是 belly —— 不用给失败惩罚（设计禁区）。
   *   stages 这一趟推过了几关（重打同一关不算）
   */
  trip: { loot: 0, multi: 1, stages: 0 },
  // 饱食度 0..100。出门满，**每过一关掉 16**：第 3 关开始半饿，第 6 关全饿。
  // 全饿不扣火力（那是 P2 的事），只收走一件事：冲刺。跑不动是能被看见的饿。
  belly: 100,
  // 家里攒的（还没有家园，先堆在屋前当视觉证据）
  home: { loot: 0, runs: 0, lastLoot: 0 },
  // 关卡内台词：只有一句，新的直接盖掉旧的 —— 排队会在玩家已经跑远时冒出来
  say: { txt: "", t: 0, life: 0, fired: {} },

  rng: Math.random,     // 测试里可换成一个确定性序列

  keys: {},
  press: {},            // 本帧新按下的键（边沿），tick 末尾清空
  hover: -1,
  hoverStage: -1,
  hoverBtn: -1,         // 结算面板：0 继续 / 1 收工 / -1 没指
  vignette: true,
  log: [],
};

/* ---------- 输入 ---------- */
const KEYMAP = {
  ArrowLeft: "left", KeyA: "left",
  ArrowRight: "right", KeyD: "right",
  ArrowUp: "jump", KeyW: "jump", Space: "jump",
  ArrowDown: "down", KeyS: "down",
  KeyJ: "atk",
  KeyK: "dash",
  ShiftLeft: "aim", ShiftRight: "aim",
};

/* 键盘监听走**捕获阶段**（第三个参数 true），不走冒泡阶段。

   麻烦在这里：Cocos 预览把 game canvas 铺在最上层，它自己的输入系统、
   以及宿主页面任何一层监听，只要调了 stopPropagation，冒泡阶段挂在
   window 上的监听就收不到。而症状恰好是"能走能跳、就是按 J 喷不出来" ——
   走和跳是别的东西转发的，喷只认这一张表。

   捕获阶段 window 是事件链上的第一个节点，谁拦都拦不住它。 */
window.addEventListener("keydown", (ev) => {
  // 非战斗阶段，方向键归界面用，不往角色身上送
  const inPlay = S.phase === "play";
  const k = KEYMAP[ev.code];
  if (k && inPlay) {
    // 只在"第一次按下"记一次边沿。浏览器按住键会不停重发 keydown，
    // 拿重发当新按键的话，按住空格就会一路连跳。
    if (!S.keys[k]) S.press[k] = true;
    S.keys[k] = true;
    ev.preventDefault();
  }
  if (k === "aim") S.aim = true;

  if (ev.code === "KeyR" && (inPlay || S.phase === "clear" || S.phase === "fail")) {
    beginRun(S.stage);
    return;
  }
  if (ev.code === "Escape" && S.phase !== "select") {
    // 从家园进来的，ESC 就是"收工回家" —— 主界面已经取代了门口选人这一站
    if (groveExit("esc")) return;
    S.phase = "select";
    S.p = null;
    // 门口状态必须复位：不复位的话，下次回来六只还保持着上次"已经出门"的姿势
    S.door.pick = -1;
    S.door.leaveT = 0;
    return;
  }

  // 选人：先走 1.6 秒的出门演出，再开打。（演出内容 = 其余五只的反应）
  if (S.phase === "select") {
    const n = ["Digit1", "Digit2", "Digit3", "Digit4", "Digit5", "Digit6"].indexOf(ev.code);
    if (n >= 0 && n < HEROES.length) { pickHero(n); return; }
    // Enter / Space = 带"上一次用的那只"出门，不再按默认来。
    if (ev.code === "Enter" || ev.code === "Space") {
      pickHero(S.heroIdx);
      ev.preventDefault();
    }
    return;
  }

  // 结算：回车 / 空格 继续。通关就下一关，失败就重打本关 —— 不回列表。
  // E = 收工回家，把这一趟攒的收成 × 倍率落袋。
  if (S.phase === "clear" || S.phase === "fail") {
    if (ev.code === "KeyE") { goHome(false); return; }
    if (ev.code === "Enter" || ev.code === "Space") {
      nextLevel();
      ev.preventDefault();
    }
  }
}, true);

window.addEventListener("keyup", (ev) => {
  const k = KEYMAP[ev.code];
  if (k === "aim") S.aim = false;
  /* 松键**无条件**清，不看 phase。
     原来要求 phase === "play" 才清：在 clear / select 里松开 J，
     keys.atk 就一直挂着 true，回到 play 的第一帧立刻"自己喷了一发"，
     而且按着不放的效果会永远粘住。清键是收尾动作，收尾不该有前置条件。 */
  if (k) {
    S.keys[k] = false;
    if (S.phase === "play") ev.preventDefault();
  }
}, true);

/* 窗口失焦：把按键表整个清空。
   不挡的话，按住 → 切标签页 → 松开（keyup 打给了别的窗口）→ 回来，
   角色会自己一直往那个方向跑。这是浏览器里最经典的粘键。 */
window.addEventListener("blur", () => {
  for (const k of Object.keys(S.keys)) S.keys[k] = false;
  S.aim = false;
});

/* ============================================================================
   5. 物理：所有实体统一用「y = 脚底」的坐标
   ----------------------------------------------------------------------------
   球的圆心 = y - r，顶 = y - 2r。统一成"底部对齐"省掉了一堆
   "这个用中心那个用底部"的转换错误 —— 那类 bug 只在撞墙时才现形。
   ========================================================================== */

const GRAV = 2100;
const MAXFALL = 1250;

/**
 * 走一步：水平位移 → 挡墙 → 挡木桩 → 重力 → 落地。
 * 返回落地的平台（null 表示还在空中）。
 */
function stepBody(b, dt) {
  const prevY = b.y;
  b.hitWall = 0;

  b.x += b.vx * dt;
  if (b.x - b.w / 2 < WALL_L) { b.x = WALL_L + b.w / 2; b.vx = 0; b.hitWall = -1; }
  if (b.x + b.w / 2 > WALL_R) { b.x = WALL_R - b.w / 2; b.vx = 0; b.hitWall = 1; }

  // 木桩是实心墙，横向挡人。已经被球撞碎的（hp<=0）自动让路。
  for (const s of S.stumps) {
    if (s.hp <= 0) continue;
    const top = s.y - s.h;
    if (b.y <= top + 4) continue;           // 站在木桩顶上，不挡
    const l = s.x - s.w / 2, r = s.x + s.w / 2;
    if (b.x + b.w / 2 > l && b.x - b.w / 2 < r) {
      if (b.vx > 0) { b.x = l - b.w / 2; b.hitWall = 1; }
      else if (b.vx < 0) { b.x = r + b.w / 2; b.hitWall = -1; }
      b.vx = 0;
    }
  }

  b.vy = Math.min(b.vy + GRAV * dt, MAXFALL);
  b.y += b.vy * dt;

  b.onGround = false;
  b.ground = null;
  if (b.vy >= 0) {
    let best = null;
    // 下穿：只放过"脚下那一块"，落到下一层就停。
    // 上一版是"窗口内所有台面都不算落脚点"，于是按住 ↓ 会一路穿到地面 ——
    // 玩家要的是"下一层"，不是"跳楼"。窗口只用来兜住"刚起跳那几帧"，
    // 真正的范围由 dropPlat（脚下这一块）限死，层距再小也不会多穿一层。
    // skyDrop 是给 BOSS 天降用的：它要从天上直接落到地面，中途所有台面都不接。
    const dropping = b.dropT > 0 && (b.dropPlat || b.skyDrop);
    for (const p of PLATS) {
      if (dropping) {
        if (b.skyDrop) { if (p.kind !== "ground") continue; }
        else if (p === b.dropPlat) continue;
      }
      if (b.x + b.w / 2 < p.x || b.x - b.w / 2 > p.x + p.w) continue;
      // 单向平台：只有"上一帧还在顶面之上"的那一块算数，
      // 这样从下面跳上去能穿过去，不会一头撞死在板底
      if (prevY <= p.y + 2 && b.y >= p.y) {
        if (!best || p.y < best.y) best = p;
      }
    }
    // 木桩顶面也算落脚点 —— 不给的话，玩家跳到木桩正上方会被侧面
    // 判定一路推出去，看起来像"空气墙把人弹开了"
    for (const s of S.stumps) {
      if (s.hp <= 0) continue;
      const top = s.y - s.h;
      if (b.x + b.w / 2 < s.x - s.w / 2 || b.x - b.w / 2 > s.x + s.w / 2) continue;
      if (prevY <= top + 2 && b.y >= top) {
        if (!best || top < best.y) {
          best = { x: s.x - s.w / 2, y: top, w: s.w, kind: "stump" };
        }
      }
    }
    // 斜坡：坡面也是落脚面。上一版只有球认坡、人不认，
    // 结果玩家走上去直接穿到地面 —— 看得见坡、踩不上去，地图就成了假的。
    if (!dropping) {
      const rp = rampAt(b.x);
      if (rp && b.vy >= -40 && onRampSurface(b.y, rp, prevY, 16)) {
        // 坡面是斜的，"离得最近"不能按 y 比 —— 按 |y - 坡面| 比，
        // 否则站在地面上、头顶有一条悬空滑梯时，平台会被那条滑梯顶掉。
        const dy = Math.abs(rp.y - b.y);
        if (!best || dy < Math.abs(best.y - b.y)) {
          best = { x: rp.x0, y: rp.y, w: rp.w, kind: "ramp" };
        }
      }
    }
    if (best) {
      b.y = best.y; b.vy = 0;
      b.onGround = true; b.ground = best;
    }
  }
  return b.ground;
}

/* ============================================================================
   6. 建局
   ========================================================================== */

function curStage() { return LEVELS[S.stage] || LEVELS[0]; }
function curGoal() { return GOALS[curStage().goal]; }

/** 限球关还剩几颗额度；不限球返回 Infinity */
function ballBudget() {
  const st = curStage();
  if (st.goal !== "limit") return Infinity;
  return Math.max(0, st.ballLimit - S.stat.made);
}

/**
 * 造一只敌人。BOSS 也走这一条 —— 它只是"cm 更大的敌人"，
 * 不是第二套规则。玩家因此不用学新东西：糊满 → 变球 → 推进坑。
 *
 * `fromSky` 只对 BOSS 用：从高处砸下来，给自己一个登场。
 */
function foeFromSpec(sp, fromSky) {
  const def = FOES[sp.foe] || FOES.bug;
  const isBoss = sp.foe === "boss";
  const lv = sp.lv || 1;
  const w = isBoss ? 78 + lv * 6 : def.w;
  const h = isBoss ? 84 + lv * 6 : def.h;
  return {
    def, kind: isBoss ? "charge" : def.kind,
    isBoss: !!isBoss, lv,
    x: sp.x, y: fromSky ? -140 : sp.y,
    w, h,
    vx: 0, vy: fromSky ? 300 : 0, face: -1,
    coat: 0,
    // cm = 包裹上限。普通怪 3 层（也就是一次"糊满"），
    // BOSS 4 + lv：第 1 关 5 层，第 8 关 10 层（封顶）。
    // 原来写 3+lv，实测第 2 关 BOSS **2 秒就被糊成球**（玩家站在 100px 外
    // 一直喷，抗性 0.28s 根本拦不住），比小怪还短命 —— BOSS 至少得让玩家
    // 躲过一次砸地才算数。
    cm: isBoss ? Math.min(4 + lv, 10) : 3,
    dead: false,
    onGround: !sp.fly && !fromSky, ground: null,
    fly: !!sp.fly, homeY: sp.y,
    stun: 0, hitT: 0, bob: rand(0, 6.28),
    dir: S.rng() < 0.5 ? -1 : 1,
    chargeT: rand(1.2, 3.2), charging: 0,
    // 落地 1.2 秒就砸第一次（不是 2.6）：2.6 秒的空窗里玩家已经把它糊成球了，
    // "举起来"这一下全程没机会播。
    slamT: isBoss ? 1.2 : 2.6, slamming: 0,
    // 繁殖 / 散射两条计时。三条动作（砸地 6.5s、散射 5.5s、产卵 7.5s）
    // 特意错开，玩家的"跳 / 走位 / 攻击"三个动作才能轮流用上，
    // 挤在同一秒就成了"同时干三件事"，那是难度不是设计。
    scatterT: isBoss ? 3.4 : 0, spitting: 0,
    spawnT: isBoss ? 4.4 : 0, breeding: 0,
    spawned: 0, fed: 0,
    larva: sp.foe === "larva",
    // 空中登场：一路穿平台直落地面。不设这个的话，BOSS 会被 156 层的塔尖
    // 接住 —— 每关的塔尖位置都不一样，它就会"卡在半空"，玩家够不着。
    dropT: fromSky ? 99 : 0,
    skyDrop: !!fromSky,
  };
}

/** 铺第 i 波。i=0 是开场，不打标题 —— 开场就弹字会盖住选人界面的余韵 */
function spawnWave(i) {
  const wv = WAVES[i] || [];
  const bossWave = wv.some(sp => sp.foe === "boss");
  for (const sp of wv) S.foes.push(foeFromSpec(sp, bossWave && sp.foe === "boss"));
  S.wave = i;
  S.waveT = 0;
  S.waveGap = 0;

  if (i > 0) {
    addText(W / 2, 176, bossWave ? "BOSS 来了" : "第 " + (i + 1) + " 波",
            bossWave ? "#FF8A6B" : "#FFE066", bossWave ? 38 : 28, bossWave ? 1.9 : 1.5);
    S.shake = Math.max(S.shake, bossWave ? 9 : 3);
    if (bossWave) S.flash = 0.14;
  }
}

function setupLevel() {
  S.foes = [];
  S.wave = 0;
  S.waveT = 0;
  S.waveGap = 0;
  S.shocks = [];
  S.foeShots = [];
  S.total = 0;
  for (const wv of WAVES) S.total += wv.length;
  spawnWave(0);
  S.stumps = STUMPS.map(s => ({ x: s.x, y: s.y, w: s.w, h: s.h, hp: s.hp, shake: 0 }));
  S.drops = [];
  S.shots = [];
  S.balls = [];
  S.frags = [];
  S.texts = [];
  S.food = 0;
  S.killed = 0;
  S.failWhy = "";
  // 台词每关重置：first / big 是"这一关的第一次"，跨关累计就永远不说了
  S.say.txt = ""; S.say.t = 0; S.say.life = 0; S.say.fired = {};
  S.stat = { made: 0, burned: 0, banked: 0, burst: 0, drowned: 0, hits: 0, bankHolds: 0, maxHolds: 0, chests: 0 };
  S.t = 0;
  S.shake = 0;
  S.flash = 0;
  S.hitStop = 0;
}

/** 回选人界面 */
function resetRun() {
  S.phase = "select";
  S.p = null;
  S.hoverStage = -1;
  loadLevel(0);
  setupLevel();
}

/** 开一关：装几何 -> 铺敌人 -> 放玩家 */
function beginRun(i) {
  if (typeof i === "number") S.stage = clamp(i, 0, LEVELS.length - 1);
  S.playT = 0;
  S.clearT = 0;
  S.progress = Math.max(S.progress, S.stage);
  const SI = curStage();
  loadLevel(S.stage);
  setupLevel();

  const H = HEROES[S.heroIdx];
  S.p = {
    hero: S.heroIdx,
    x: PLAYER_SPAWN.x, y: PLAYER_SPAWN.y,
    w: H.w, h: H.h,
    vx: 0, vy: 0,
    face: 1,
    onGround: true, ground: PLATS[0],
    hp: 4, maxHp: 4,
    invT: 0, atkT: 0, dashT: 0, dashCd: 0,
    coyote: 0, jumpBuf: 0,
    castAnim: 0, dashAnim: 0, walkPhase: 0,
    dead: false,
  };
  S.phase = "play";
  addText(W / 2, 150, "第 " + (S.stage + 1) + " 关  " + SI.name + "  ·  " + curGoal().name,
          "#FFFFFF", 26, 1.6);
  // 全饿的第一关必须说明白。不说的话，玩家按 K 没反应只会觉得游戏坏了
  if (bellyTier() === 0) {
    addText(W / 2, 194, "它饿得跑不动了 —— 推不动就收工回家", "#FFC9A8", 17, 4.2);
  }
}

/**
 * 推关：通关就往下走，失败就重打本关。
 * 不回关卡列表 —— 一回到列表，"推关"的感觉就断了，人会开始挑着打。
 * 想换关只有一条路：ESC 回选人，再从存档进度继续。
 */
function nextLevel() {
  if (S.phase === "fail") { beginRun(S.stage); return; }
  if (S.stage + 1 < LEVELS.length) { beginRun(S.stage + 1); return; }
  // 通关了。最后一关没有再下一关，直接算收工
  goHome(true);
}

/* ---------- 饱食 ----------
 * 三档只影响**看得见的东西**（肚子、眼睛、跑不跑得动），不碰火力。
 * 火力是 P2 的事：那时"半饿最强"才会接进来，现在提前做会把数值和
 * 表现搅在一起，改一个得同时验另一个。
 */
function bellyTier(v) {
  const b = v === undefined ? S.belly : v;
  return b < 30 ? 0 : b < 70 ? 1 : 2;      // 0 全饿 / 1 半饿 / 2 满饱
}

/** 关卡里冒一句话。新的直接盖掉旧的 —— 排队会在玩家已经跑远的时候冒出来 */
function sayLine(kind) {
  const H = HEROES[S.p ? S.p.hero : S.heroIdx];
  const V = VOICE[H.id] || VOICE.cat;
  let txt = V[kind] || "";
  if (!txt) return;
  // 饿到全饿的时候，挨打那句要换语气 —— 同一只饿和饱，说话不是一个调
  if (kind === "hurt" && bellyTier() === 0) txt = "……真的跑不动了。";
  S.say.txt = txt;
  S.say.t = 0;
  S.say.life = 2.1;
}

/** 结算面板上那句话。它跟"饿不饿"绑：饱着是邀功，饿着是求饶 */
function finishSay(ok) {
  const id = HEROES[S.heroIdx].id;
  if (!ok) {
    return {
      cat: "……丢脸。", dog: "我还能再试一次吗？", ham: "先吃点东西。",
      rab: "……对不起。", ox: "歇一下就好。", fox: "没人看见。",
    }[id] || "再给我一次。";
  }
  const tier = bellyTier();
  if (tier === 0) return "先……先回家吧。";
  if (tier === 1) return "还走得动。";
  return {
    cat: "这一片我先看过了。", dog: "回去吧回去吧！", ham: "我能带走一点吗？",
    rab: "抱我一下。", ox: "不着急。", fox: "天还没亮。",
  }[id] || "走吧。";
}

/**
 * 收工回家：这一趟到此为止。
 *
 * 结算 = 这一趟攒的收成 × 连锁倍率，**只有收工才拿得到倍率**。
 * 于是"每关都回家"是安全打法（永远 ×1.0），"贪到底"是赚的打法（×2.0）——
 * 两种都算在玩，但贪的那个得扛着饿。这是全篇唯一不做失败惩罚的张力来源。
 */
function goHome(allClear) {
  const gain = Math.round(S.trip.loot * S.trip.multi) + (allClear ? 12 : 0);
  S.home.loot += gain;
  S.home.lastLoot = gain;
  S.home.runs++;
  S.belly = 100;                         // 回家吃饭
  S.trip = { loot: 0, multi: 1, stages: 0 };
  S.phase = "select";
  S.p = null;
  S.door.pick = -1;
  S.door.leaveT = 0;
  S.say.txt = ""; S.say.t = 0; S.say.life = 0; S.say.fired = {};
  // 进度不退回 —— "收工"不是惩罚，只是这一趟结束了
  if (allClear) S.progress = 0;
  // 从家园进来的，收工就回主界面（解锁过场在那里播）
  groveExit("done");
}

function saveProgress() {
  try { localStorage.setItem("pawpack.progress", String(Math.min(S.progress, LEVELS.length - 1))); } catch (e) {}
}
function loadProgress() {
  try {
    const v = parseInt(localStorage.getItem("pawpack.progress"), 10);
    if (v >= 0 && v < LEVELS.length) S.progress = v;
  } catch (e) {}
}

/* ============================================================================
   7. 玩家
   ========================================================================== */

function updatePlayer(dt) {
  const p = S.p;
  if (!p || p.dead || S.phase !== "play") return;
  const H = HEROES[p.hero];

  p.atkT = Math.max(0, p.atkT - dt);
  p.dashCd = Math.max(0, p.dashCd - dt);
  p.invT = Math.max(0, p.invT - dt);
  p.castAnim = Math.max(0, p.castAnim - dt);
  p.dashAnim = Math.max(0, p.dashAnim - dt);
  // 推球后的后坐。人往后退一点点再弹回来 —— 只靠"手停住"读不出力道。
  p.pushBack = Math.max(0, (p.pushBack || 0) - dt);
  p.jumpBuf = Math.max(0, p.jumpBuf - dt);
  p.coyote = p.onGround ? 0.10 : Math.max(0, p.coyote - dt);

  // ---- 冲刺（撞飞）
  if (p.dashT > 0) {
    p.dashT -= dt;
    p.vx = p.face * H.dashPow;
    p.vy = Math.min(p.vy, 40);   // 冲刺时轻微"悬空"，读起来更有冲力
  } else {
    // ---- 左右移动
    let ax = 0;
    if (S.keys.left) ax -= 1;
    if (S.keys.right) ax += 1;
    if (ax !== 0) {
      p.face = ax;
      p.vx = ax * H.spd;
    } else {
      // 地面摩擦大、空中近乎无阻力 —— 空中能改方向才跟手
      const fr = p.onGround ? 2600 : 420;
      if (Math.abs(p.vx) <= fr * dt) p.vx = 0;
      else p.vx -= sign(p.vx) * fr * dt;
    }
  }

  // ---- 助跑距离：推球的力度按"这一趟朝这个方向跑了多远"算
  // 只算**当前方向**上的连续位移 —— 来回横跳不会攒出大力气，
  // 否则玩家会在原地左右左右刷满再推，那就成了"摇杆搓招"，不是"助跑"。
  const rdir = sign(p.vx) || p.face;
  // 只在"第一次有方向"之后才开始比较，否则开局那一帧会把 runD 清成 0
  if (p.runDir !== undefined && rdir !== p.runDir) p.runD = 0;
  p.runDir = rdir;
  if (p.onGround && Math.abs(p.vx) > 80) {
    p.runD = Math.min(420, (p.runD || 0) + Math.abs(p.vx) * dt);
  } else if (Math.abs(p.vx) < 80) {
    p.runD = Math.max(0, (p.runD || 0) - 420 * dt);
  }

  // ---- 从台上下来（↓）
  // 平台是单向的：能跳上去、能站在上面，但**走不到边就下不来**。
  // 有些台面一直顶到墙，等于连边都没有 —— 玩家会被困在上层。
  // 按住 ↓ 直接穿下去，是平台跳跃里最省事的一条解法（不用教）。
  p.dropT = Math.max(0, (p.dropT || 0) - dt);
  // 松开 ↓ 才允许下一次下穿。没有这把锁，按住 ↓ 会一层接一层地穿下去 ——
  // 玩家按的是"下去一层"，看到的是"直接掉到底"，中间那几层他根本没做选择。
  if (!S.keys.down) p.dropLock = false;
  // `Math.abs(p.y - p.ground.y) < 6` 这一条是"脚下那块的顶面就是我现在站的高度"。
  // 少了它，只要 p.ground 是上一帧留下的旧值（比如刚从 462 掉到地面），
  // 按住 ↓ 就会把 y 往下推 8px —— 而地面恰好就在 0px 处，
  // 8px 一推就落到地面以下，落地判定（prevY <= p.y + 2）再也接不住。
  if (S.keys.down && !p.dropLock && p.onGround && p.ground &&
      p.ground.kind !== "ground" && p.dropT <= 0 &&
      Math.abs(p.y - p.ground.y) < 6) {
    p.dropLock = true;
    p.dropT = 0.26;
    p.dropPlat = p.ground;
    p.y += 8;
    p.vy = 120;
    p.onGround = false;
    p.ground = null;
    for (let i = 0; i < 5; i++) addFrag(p.x + rand(-10, 10), p.y - 6, 4, "#DCEFC8");
  }

  stepBody(p, dt);

  // 落地且在往前走才迈步。相位只给绘制用：悬空、冲刺时停住，
  // 免得脚在空中还蹬、或者冲刺变成原地踏步。
  if (p.onGround && p.dashT <= 0 && Math.abs(p.vx) > 40) {
    p.walkPhase += dt * 11;
  }

  // ---- 跳（带土狼时间 + 输入缓冲，手感全靠这两个）
  if (S.press.jump) p.jumpBuf = 0.12;
  if (p.jumpBuf > 0 && p.coyote > 0 && p.dashT <= 0) {
    p.vy = -H.jump;
    p.onGround = false;
    p.coyote = 0;
    p.jumpBuf = 0;
    addFrag(p.x, p.y, 6, "#E8F6D8");
  }

  // ---- 喷（J）
  // **按住连发**。原来读的是 S.press（边沿）—— 按住 J 只打第一下，
  // 玩家会以为"按键没反应"。节流交给 atkCd，本来就是干这个的。
  // castDir 单独记一份：施法动作要朝"这一下打出去的方向"倾，
  // 而不是施法过程中玩家又转身跟着转（那会变成原地抽搐）。
  /* **按住 (keys) 和点一下 (press) 都要能喷。**
     原来只读 keys —— 按住连发是对的，但它把"边沿"这条路整个掐了。
     代价是任何一次 keys 没送达（焦点丢、桥接层被拦、模拟输入只置 press）
     就等于施法彻底失效，而且症状是"能走能跳就是喷不出来"，
     玩家会以为是键位坏了，不是代码坏了。两条都收，成本为零。 */
  if ((S.keys.atk || S.press.atk) && p.atkT <= 0) {
    p.atkT = H.atkCd;
    p.castAnim = CAST_T;
    p.castDir = p.face;
    H.fire(p);
  }

  // ---- 撞（K）
  if (S.press.dash && p.dashCd <= 0) {
    if (bellyTier() === 0) {
      // 全饿跑不动。**"饿"必须有后果**，否则饱食度只是贴在图标上的一个字，
      // 玩家永远不回家，"再贪一关"就不成立。
      // 只收走冲刺而不碰火力：火力是 P2 的数值，现在不能提前动。
      p.dashCd = 0.55;
      addText(p.x, p.y - p.h - 20, "跑不动…", "#FFC9A8", 15, 0.85);
    } else {
      p.dashCd = H.dashCd;
      p.dashT = 0.16;
      p.dashAnim = 0.20;
      S.shake = Math.max(S.shake, 3);
      for (let i = 0; i < 6; i++) {
        addFrag(p.x - p.face * 12, p.y - p.h * 0.5 + rand(-8, 8), 4, "#DCF0C0");
      }
    }
  }

  // ---- 冲刺撞敌人：两段式造球的关键
  if (p.dashT > 0) {
    for (const f of S.foes) {
      if (f.dead || f.coat >= (f.cm || 3)) continue;
      if (!overlap(p, f)) continue;
      if (f.coat >= (f.cm || 3) - 1) {
        // 已经裹了两层 —— 一撞直接成球，朝面朝方向飞出去
        makeBallFrom(f, p.face * 660, -120);
        S.shake = Math.max(S.shake, 8);
        hitStop(0.055);
        addText(f.x, f.y - f.h - 26, "撞飞!", "#FFE58A", 20);
      } else {
        coatFoe(f, 1);
        f.stun = Math.max(f.stun, 0.35);
        f.x += p.face * 16;
        S.shake = Math.max(S.shake, 4);
      }
      p.dashT = 0;
      p.vx = -p.face * 140;
    }
  }

  // ---- 走位推球：贴近球就推走（和原版一样，不需要新按键）
  // **推多远，看你跑了多远。**
  // 用户原话："站的越远推球，球的推力越大"。站着不动推是 PUSH_BASE，
  // 退后跑满 380px 再推能再多 75% —— 于是"先退开、再冲过去"变成
  // 一个有代价的好习惯：退开的那两秒，敌人也在往你身上走。
  //
  // 上一版"感觉推不动"，问题不在数值而在**反馈**：推的那一帧什么也没发生。
  // 现在推球这一刻同时给四样东西 —— 顿帧、球压扁、人后坐、球拖影。
  const runUp = Math.min(1, (p.runD || 0) / 380);
  const pushPow = PUSH_BASE * (1 + PUSH_RUN * runUp);
  for (const b of S.balls) {
    if (b.dead) continue;
    // 判定窗口 = 两个圆刚好相切再加 2px。上一版是 -4 ——
    // 人得先"陷进球里 4px"才算推，而人和球之间没有碰撞体，
    // 于是高速冲过去的那一帧常常整个跳过窗口：看起来就是"从球里穿过去了"。
    if (Math.abs(b.x - p.x) < b.r + p.w / 2 + 2 &&
        b.y > p.y - p.h - b.r * 2 && b.y < p.y + 20) {
      const pushDir = (b.x - p.x) !== 0 ? sign(b.x - p.x) : p.face;
      if (Math.abs(b.vx) < 140) {
        b.vx = pushDir * pushPow;
        b.vy = Math.min(b.vy, -40);
        // 推出去 = 一次性。见 updateBalls 里 "推出后必消失" 那条。
        b.pushed = true;
        b.relT = 0;
        b.wallHits = 0;
        // 球被顶瘪一下：沿运动方向压短、垂直方向鼓起来 ——
        // 这是"它真的被撞了"唯一不靠文字的表达。
        b.pushSquash = 0.30 + runUp * 0.14;
        b.pushDir = pushDir;
        p.runD = 0;
        // 人被顶住：继续全速往前跑的话，读起来像"人从球里穿过去了"。
        p.vx *= 0.2;
        p.pushBack = 0.16;
        p.face = pushDir;
        hitStop(0.04 + runUp * 0.03);
        S.shake = Math.max(S.shake, 6 + runUp * 7);
        addText(b.x, b.y - b.r * 2 - 12,
                runUp > 0.75 ? "蓄力推!" : "推!",
                runUp > 0.75 ? "#FFD86B" : "#CFE9FF",
                runUp > 0.75 ? 22 : 18);
        for (let i = 0; i < 4 + Math.round(runUp * 6); i++) {
          addFrag(b.x - pushDir * b.r * 0.6, b.y - b.r * 0.5 + rand(-10, 10), 5,
                  runUp > 0.4 ? "#EAF7C0" : "#DCE9F7");
        }
      }
    }
  }

  // ---- 碰敌人受伤
  if (p.invT <= 0 && p.dashT <= 0) {
    for (const f of S.foes) {
      if (f.dead || f.coat >= (f.cm || 3)) continue;
      if (!overlap(p, f)) continue;
      p.hp -= 1;
      S.stat.hits++;   // 无伤关就靠这一个数
      p.invT = 1.2;
      p.vx = -sign(f.x - p.x) * 320;
      p.vy = -260;
      S.shake = Math.max(S.shake, 12);
      S.flash = 0.25;
      addText(p.x, p.y - p.h - 20, "唔!", "#FF9E8E", 20);
      if (p.hp <= 0) { p.hp = 0; p.dead = true; S.phase = "fail"; }
      break;
    }
  }

  // ---- 火坑烫脚：地形对玩家同样有效，所以火坑是"必须跳过去"的东西，
  // 不是一个只对球生效的装饰
  if (p.onGround && p.invT <= 0 && p.dashT <= 0) {
    for (const pit of PITS) {
      if (pit.kind !== "fire") continue;
      // 必须连竖向一起判。只判横向的话，站在火坑**正上方那块平台上**
      // 也会被烫 —— 而那三块平台就在火坑上方，等于整片高地都是禁区。
      if (p.x > pit.x + 8 && p.x < pit.x + pit.w - 8 && p.y >= pit.y - 6) {
        p.hp -= 1;
        S.stat.hits++;
        p.invT = 1.2;
        p.vy = -430;
        p.vx = sign(p.x - (pit.x + pit.w / 2)) * 210;
        S.shake = Math.max(S.shake, 10);
        S.flash = 0.22;
        addText(p.x, p.y - p.h - 22, "烫!", "#FF9E8E", 20);
        for (let i = 0; i < 12; i++) addFrag(p.x, p.y - 10, 6, "#FFB05C");
        if (p.hp <= 0) { p.hp = 0; p.dead = true; S.phase = "fail"; }
        break;
      }
    }
  }

  // ---- 捡地上的掉落物。五种东西走同一条碰撞，效果分开算
  for (const d of S.drops) {
    if (d.taken) continue;
    if (Math.abs(d.x - p.x) > 28 || Math.abs(d.y - (p.y - 14)) > 44) continue;
    d.taken = true;
    const K = DROP_KINDS[d.kind] || DROP_KINDS.fruit;

    // 宝箱：开出来的是"这一趟最缺的那一样"，不是随机装饰
    if (K.chest) {
      const hold = d.holds || 1;
      const roll = S.rng();
      if (roll < 0.52) {
        const f = 4 + hold * 2;
        S.food += f;
        addText(d.x, d.y - 36, "宝箱 +" + f + " 收成", "#FFD65C", 22, 1.2);
      } else if (roll < 0.80) {
        for (const bb of S.balls) bb.air = Math.min(1, bb.air + 0.5);
        addText(d.x, d.y - 36, "宝箱 · 全队回气", "#8FE4FF", 21, 1.2);
      } else if (p.hp < p.maxHp) {
        p.hp = Math.min(p.maxHp, p.hp + 2);
        addText(d.x, d.y - 36, "宝箱 +2 心", "#FF8FA6", 22, 1.2);
      } else {
        S.food += 6;
        addText(d.x, d.y - 36, "宝箱 +6 收成", "#FFD65C", 22, 1.2);
      }
      S.stat.chests++;
      for (let i = 0; i < 18; i++) addFrag(d.x, d.y, 7, i % 2 ? "#FFD65C" : "#FFF3C0");
      S.shake = Math.max(S.shake, 7);
      S.flash = Math.max(S.flash, 0.10);
      continue;
    }

    if (K.food) {
      S.food += K.food;
      addText(d.x, d.y - 22, "+" + K.food, K.color, 17);
    }
    if (K.air) {
      for (const bb of S.balls) bb.air = Math.min(1, bb.air + K.air);
      addText(d.x, d.y - 22, "回气", K.color, 17);
    }
    if (K.heal) {
      if (p.hp < p.maxHp) { p.hp++; addText(d.x, d.y - 22, "+1 心", K.color, 17); }
      else { S.food += 2; addText(d.x, d.y - 22, "+2", K.color, 17); }
    }
    for (let i = 0; i < 6; i++) addFrag(d.x, d.y, 4, K.color);
  }

  // ---- 掉出世界（不该发生，但兜一下）
  if (p.y > H + 60) { p.y = GROUND_Y; p.x = PLAYER_SPAWN.x; p.vy = 0; }
}

/* ============================================================================
   8. 敌人
   ========================================================================== */

function updateFoe(f, dt) {
  if (f.dead) return;
  if (f.isBoss) { updateBoss(f, dt); return; }
  f.hitT = Math.max(0, f.hitT - dt);
  f.stun = Math.max(0, f.stun - dt);
  f.bob += dt * 3.2;

  // 被裹到 3 层就该变球了，这里是保险（正常流程在 coatFoe 里处理）
  if (f.coat >= (f.cm || 3)) return;

  if (f.stun > 0) { f.vx = 0; }

  if (f.fly) {
    // 乌鸦：缓慢贴向玩家，纵向做正弦摆动 —— 它要看起来"不着急"
    const p = S.p;
    if (p && !p.dead) {
      const dx = p.x - f.x;
      f.vx = sign(dx) * f.def.spd * (Math.abs(dx) > 40 ? 1 : 0.15);
      f.face = sign(dx);
    }
    f.x += f.vx * dt;
    f.y = f.homeY + Math.sin(f.bob * 0.8) * 18;
    f.x = clamp(f.x, WALL_L + f.w / 2, WALL_R - f.w / 2);
    return;
  }

  // ---- 幼虫：目标不是玩家，是 BOSS。爬到了就被吃掉，BOSS 补一层壳
  if (f.larva) {
    const boss = S.foes.find(q => q.isBoss && !q.dead);
    f.bornT = (f.bornT || 0) + dt;
    if (!boss || f.bornT > 14) {
      // 没有 BOSS 了 / 爬了 14 秒还没到 —— 自己散掉，别在场上堆着
      if (f.bornT > 14) f.dead = true;
      f.vx = f.dir * f.def.spd * 0.5;
    } else if ((f.wanderT || 0) > 0) {
      // 刚孵出来：先朝外爬一小段。这一段是给玩家的反应时间，
      // 也是"虫群散开"的画面 —— 一出壳就直扑 BOSS 的话，玩家只看到一串加号。
      f.wanderT -= dt;
      f.face = f.dir;
      f.vx = f.face * f.def.spd * 0.72;
    } else {
      const dx = boss.x - f.x;
      f.dir = sign(dx);
      f.face = f.dir;
      f.vx = f.face * f.def.spd * 1.15;
      // 到嘴：横向贴住 + 同一层 + 出了孵化保护期
      // 差一层就够不着：幼虫在上层平台、BOSS 在地面时，它得先走到边缘掉下去。
      // 上一版给了它"跳"，结果它在平台上原地蹦，永远绕不到 BOSS 那一侧。
      if ((f.bornT || 0) > 0.8 &&
          Math.abs(dx) < boss.w * 0.5 + 12 && Math.abs(f.y - boss.y) < 70) {
        f.dead = true;
        feedBoss(boss, f);
        return;
      }
    }
    stepBody(f, dt);
    if (f.hitWall) f.dir = -f.hitWall;
    if (f.y > H + 100) f.dead = true;
    return;
  }

  if (f.kind === "charge") {
    const p = S.p;
    f.chargeT -= dt;
    if (p && !p.dead && Math.abs(p.y - f.y) < 60) {
      f.face = sign(p.x - f.x);
    }
    if (f.charging > 0) {
      f.charging -= dt;
      f.vx = f.face * f.def.spd * 3.1;
    } else {
      if (f.chargeT <= 0) { f.charging = 0.55; f.chargeT = rand(2.2, 3.6); }
      f.vx = f.face * f.def.spd * 0.5;
    }
  } else {
    f.vx = f.dir * f.def.spd;
    f.face = f.dir;
  }

  f.vx = f.vx * (f.stun > 0 ? 0 : 1);
  const g = stepBody(f, dt);

  // 走到平台边缘就掉头 —— 不然敌人会自己跳崖，玩家一个都不用打
  if (f.onGround && f.kind !== "charge") {
    const ahead = f.x + f.dir * (f.w / 2 + 10);
    if (!g || ahead < g.x + 4 || ahead > g.x + g.w - 4) f.dir = -f.dir;
  }
  if (f.hitWall) f.dir = -f.hitWall;

  if (f.y > H + 100) f.dead = true;
}

/* ----------------------------------------------------------------------------
   BOSS
   ----------------------------------------------------------------------------
   它走的是**同一套规则**：糊满 cm 层 → 变球 → 推进坑。
   没有第二套血量、没有免疫、没有阶段 —— 玩家不用学新东西。

   让它和普通怪不一样的只有两件事：
     1. 慢速追击。压迫感来自"它一直在过来"，不是来自速度。
     2. 每 6.5 秒砸一次地，放出两道贴地冲击波。这一条是**逼玩家离开地面** ——
        不然最舒服的打法就是站在它脚边一路糊，BOSS 战会变成木桩战。
   BOSS 被球撞不消失那一条在 updateBalls 里（球会弹回去，可以连撞）。
   -------------------------------------------------------------------------- */

function updateBoss(f, dt) {
  f.hitT = Math.max(0, f.hitT - dt);
  f.stun = Math.max(0, f.stun - dt);
  f.bob += dt * 1.7;

  // 从天上掉下来的登场：穿平台直落地面，落地之前什么都不做
  if (f.dropT > 0) {
    f.dropT -= dt;
    stepBody(f, dt);
    if (f.onGround) {
      f.dropT = 0;
      S.shake = Math.max(S.shake, 12);
      for (let i = 0; i < 22; i++) addFrag(f.x + rand(-50, 50), f.y - 4, 8, "#D8C8A8");
    }
    return;
  }

  if (f.coat >= (f.cm || 3)) return;
  const p = S.p;

  f.slamT -= dt;
  f.scatterT -= dt;
  f.spawnT -= dt;

  /* ---- 砸地（最高优先级：手已经举起来了就必须砸完） ---- */
  if (f.slamming > 0) {
    f.slamming -= dt;
    f.vx = 0;
    if (f.slamming <= 0.35 && !f._slammed) {
      f._slammed = true;
      S.shake = Math.max(S.shake, 15);
      S.flash = 0.18;
      for (let i = 0; i < 12; i++) {
        addFrag(f.x + rand(-62, 62), f.y - 4 - rand(0, 16), 9, i % 3 ? "#B99B6A" : "#E8C88A");
      }
      S.shocks.push({ x: f.x, y: f.y, t: 0, life: 0.62, dir: 1 });
      S.shocks.push({ x: f.x, y: f.y, t: 0, life: 0.62, dir: -1 });
      addText(f.x, f.y - f.h - 26, "轰!", "#FF9A6B", 26);
    }
    if (f.slamming <= 0) { f._slammed = false; f.slamT = 6.5; }
    stepBody(f, dt);
    return;
  }

  /* ---- 产卵：肚子鼓一下，两侧各钻出一只幼虫 ---- */
  if (f.breeding > 0) {
    f.breeding -= dt;
    f.vx = 0;
    if (f.breeding <= 0.36 && !f._born) {
      f._born = true;
      for (const sd of [-1, 1]) {
        // 出生点必须**离嘴够远**：BOSS 半宽 54，吃得着的范围是 66px。
        // 原来从 ±50 处钻出来，一出生就落在嘴里，两只幼虫当场被吃掉 ——
        // 玩家连看见的机会都没有，"繁殖"就成了"BOSS 免费回血"。
        const lx = clamp(f.x + sd * (f.w * 0.5 + 56), WALL_L + 20, WALL_R - 20);
        const l = foeFromSpec({ foe: "larva", x: lx, y: f.y - 4 }, false);
        l.y = f.y; l.vy = -220; l.onGround = false;
        // 孵化后先朝外爬 1.2 秒再回头归巢。这 1.2 秒是留给玩家的：
        // 没有它，幼虫从 88px 外爬回来只要 0.2 秒，你根本来不及拦。
        l.wanderT = 1.2;
        l.dir = sd;
        S.foes.push(l);
        for (let k = 0; k < 8; k++) addFrag(lx + rand(-9, 9), f.y - 10, 5, "#D8F09A");
      }
      addText(f.x, f.y - f.h - 26, "钻出两只幼虫", "#D8F09A", 19);
      S.shake = Math.max(S.shake, 6);
    }
    if (f.breeding <= 0) { f._born = false; f.spawnT = 7.5; }
    stepBody(f, dt);
    return;
  }

  /* ---- 散射：抬头吸气，然后朝玩家喷一个五发扇形 ---- */
  if (f.spitting > 0) {
    f.spitting -= dt;
    f.vx = 0;
    if (f.spitting <= 0.30 && !f._spat) { f._spat = true; spitFan(f); }
    if (f.spitting <= 0) { f._spat = false; f.scatterT = 5.5; }
    stepBody(f, dt);
    return;
  }

  /* ---- 触发：一帧只开一个。三个动作叠在同一秒，"跳 / 走位 / 攻击"
         就变成"同时干三件"，那是难度，不是设计。 ---- */
  const larvas = S.foes.filter(q => q.larva && !q.dead).length;
  if (f.spawnT <= 0 && larvas < 3 && (f.spawned || 0) < 5) {
    f.spawned = (f.spawned || 0) + 1;
    f.breeding = 0.9;
    addText(f.x, f.y - f.h - 30, "产卵…", "#FFD86B", 20);
    stepBody(f, dt);
    return;
  }
  if (f.scatterT <= 0) {
    f.spitting = 0.72;
    addText(f.x, f.y - f.h - 30, "吸气…", "#C7E86B", 20);
    stepBody(f, dt);
    return;
  }
  if (f.slamT <= 0) {
    f.slamming = 1.15;
    addText(f.x, f.y - f.h - 30, "举起来了", "#FFB08A", 20);
    S.shake = Math.max(S.shake, 4);
    stepBody(f, dt);
    return;
  }

  if (p && !p.dead) f.face = sign(p.x - f.x);
  f.vx = f.face * (f.stun > 0 ? 0 : 40 + (f.lv || 1) * 7);
  stepBody(f, dt);
  if (f.hitWall) f.face = -f.face;

  // 掉进坑里（不该发生，但兜一下）
  if (f.y > H + 120) f.dead = true;
}

/** 五发扇形。目的是逼玩家**走位**——砸地逼他跳，扇形逼他换位置，
 *  两件事合起来才叫"这个 BOSS 要看"。 */
function spitFan(f) {
  const p = S.p;
  const muzzleY = f.y - f.h * 0.64;
  let base = f.face > 0 ? 0 : Math.PI;
  if (p && !p.dead) {
    base = Math.atan2((p.y - p.h * 0.5) - muzzleY, p.x - f.x);
  }
  const N = 5, half = 0.50;
  for (let i = 0; i < N; i++) {
    const a = base + ((i / (N - 1)) - 0.5) * half * 2;
    S.foeShots.push({
      x: f.x + Math.cos(a) * (f.w * 0.40),
      y: muzzleY + Math.sin(a) * 12,
      // 弹道要"平"：上一版初速 330、重力 300，从 BOSS 胸口射出来 1 秒就砸进土里，
      // 玩家站在 400px 外根本等不到弹幕，这条机制等于不存在。
      vx: Math.cos(a) * 380,
      vy: Math.sin(a) * 380 - 70,
      r: 9.5, life: 2.4, t: 0, dead: false,
    });
  }
  S.shake = Math.max(S.shake, 8);
  addText(f.x, muzzleY - 30, "噗!", "#C7E86B", 24);
}

/** BOSS 吃掉自己的幼虫 → 补回一层壳。
 *  硬上限 3 层：不设上限的话，玩得越久它越硬，玩家会陷进"打洞-补洞"的死循环。
 *  场上最多 3 只幼虫、每 7.5 秒一对、总共只产 5 对 —— 这四条一起兜住时长。 */
function feedBoss(boss, larva) {
  boss.fed = (boss.fed || 0) + 1;
  for (let i = 0; i < 10; i++) addFrag(boss.x + rand(-22, 22), boss.y - boss.h * 0.55, 6, "#9BE06A");
  if (boss.coat >= 2 && boss.fed <= 3) {
    boss.coat -= 1;
    addText(boss.x, boss.y - boss.h - 18, "嚼掉幼虫 · 壳 +1", "#FFD86B", 20);
    S.shake = Math.max(S.shake, 6);
  } else if (boss.coat < 2) {
    addText(boss.x, boss.y - boss.h - 18, "壳快没了，吃不回来", "#C8C0A8", 17);
  } else {
    addText(boss.x, boss.y - boss.h - 18, "嚼了嚼", "#C8C0A8", 17);
  }
}

/** BOSS 的粘液弹：有重力、会被地形挡住。
 *  "躲到板子下面"是它唯一的解法 —— 这是范围散射给玩家的那个决策。 */
function updateFoeShots(dt) {
  const p = S.p;
  for (const s of S.foeShots) {
    s.life -= dt;
    s.t += dt;
    const prevY = s.y;
    s.vy += 150 * dt;
    s.x += s.vx * dt;
    s.y += s.vy * dt;
    if (s.life <= 0) { s.dead = true; continue; }
    if (s.x < WALL_L - 30 || s.x > WALL_R + 30 || s.y > GROUND_Y + 12) { s.dead = true; continue; }
    // 只判"从上方落到台面"，不判"球心进了平台的包围盒"。
    // 上一版用包围盒，BOSS 胸口正好和头顶那块板同高，五行弹一出口就被吃掉 ——
    // 一条"范围散射"变成了"BOSS 朝空气撒了一把"。
    if (s.vy > 0) {
      for (const q of PLATS) {
        if (s.x < q.x - s.r || s.x > q.x + q.w + s.r) continue;
        if (prevY + s.r <= q.y + 6 && s.y + s.r >= q.y) { s.dead = true; break; }
      }
    }
    if (s.dead) continue;
    if (p && !p.dead) {
      const dx = Math.abs(s.x - p.x), dy = Math.abs(s.y - (p.y - p.h * 0.5));
      if (dx < s.r + p.w * 0.38 && dy < s.r + p.h * 0.42) {
        hurtPlayer(s.x, "被喷到了");
        s.dead = true;
      }
    }
  }
  if (S.foeShots.length) S.foeShots = S.foeShots.filter(s => !s.dead);
}

/** 玩家受伤只有这一条路 —— 碰敌人、踩火、被冲击波打，都走这里 */
function hurtPlayer(srcX, txt) {
  const p = S.p;
  if (!p || p.dead || p.invT > 0) return;
  p.hp -= 1;
  S.stat.hits++;
  p.invT = 1.2;
  p.vx = -sign(srcX - p.x) * 300;
  p.vy = -300;
  S.shake = Math.max(S.shake, 12);
  S.flash = 0.25;
  addText(p.x, p.y - p.h - 20, txt || "唔!", "#FF9E8E", 20);
  // 只剩一滴血的时候才说 —— 每次挨打都说话会挤成一团，
  // 而"最后一次机会"是玩家注意力最集中的地方，那句才被记住。
  if (p.hp === 1) sayLine("hurt");
  if (p.hp <= 0) { p.hp = 0; p.dead = true; S.phase = "fail"; }
}

/** 冲击波：贴地跑，跳起来就能躲 */
function updateShocks(dt) {
  const p = S.p;
  for (const s of S.shocks) {
    s.t += dt;
    s.x += s.dir * 560 * dt;
    if (s.x < WALL_L || s.x > WALL_R) s.t = s.life;
    // 用"脚底离地高度"判，不用碰撞盒：玩家明明跳过去了还被判定，
    // 那种"我躲开了却没躲掉"是手感里最伤的一种。
    if (p && !p.dead && Math.abs(p.x - s.x) < 32 && p.y > s.y - 66) {
      hurtPlayer(s.x, "被震到了");
    }
  }
  if (S.shocks.length) S.shocks = S.shocks.filter(s => s.t < s.life);
}

/* ============================================================================
   9. 包裹 / 造球
   ========================================================================== */

/**
 * 往敌人身上糊一层苔。
 *
 * `intoBall` 是球传进来的：糊满之后**卷进球里**（球变大），而不是原地
 * 变成一颗新球。这一条必须和 burstBall 对称 ——
 * 卷进去几只，崩开就吐出几只，否则场上人数会自己增殖：
 * 实测漏了这一条，4 只敌人能滚成 12 只，而玩家一个都清不掉。
 *
 * 限球关的额度只在**新造一颗球**时扣。被球卷进去不扣 ——
 * 否则"限 4 颗球"和"4 只敌人各造一颗"没区别，目标就不成立了。
 */
function coatFoe(f, n, intoBall) {
  if (f.dead || f.coat >= (f.cm || 3)) return;
  // BOSS 有抗性：0.5 秒内最多吃一层。
  // 0.28 秒是照着"音波喇叭 0.30 秒一发"配的，但除了音波还有溜溜球、飞刀、
  // 影分身的连发 —— 0.28 秒等于没拦，一梭子就是三四层。
  if (f.isBoss) {
    if (S.t - (f._coatAt || -9) < 0.5) return;
    f._coatAt = S.t;
  }

  // 额度用完：允许糊到 2 层（还能被路过的球卷走），但糊不成第三层
  const max = f.cm || 3;
  if (!intoBall && f.coat + n >= max && ballBudget() <= 0) {
    f.coat = max - 1;
    f.hitT = 0.20;
    warnNoBall();
    return;
  }

  // 同屏最多 2 颗球。这不是性能限制，是**注意力限制**：
  // 场上有 4 颗球的时候，玩家不是在决策，是在救火（实测就是这么崩的）。
  // 这条同时是"攒球不免费"最直接的答案 —— 你根本攒不了 3 颗，
  // 只能往一颗球里攒 3 只，而那才是有意思的那件事。
  if (!intoBall && f.coat + n >= max && S.balls.length >= MAX_BALLS) {
    f.coat = max - 1;
    f.hitT = 0.20;
    warnBallFull();
    return;
  }

  f.coat = Math.min(max, f.coat + n);
  f.hitT = 0.20;
  addText(f.x, f.y - f.h - 12, "+" + n, "#E4FFA8", 16);
  for (let i = 0; i < 5; i++) addFrag(f.x, f.y - f.h * 0.5, 5, "#BFE86E");

  if (f.coat >= max) {
    if (intoBall) {
      absorbIntoBall(f, intoBall);
    } else {
      makeBallFrom(f, 0, 0);
      addText(f.x, f.y - f.h - 34, "裹成球了", "#9BE86E", 18);
    }
  }
}

/** "球用完了"提示。不节流的话每帧一条，屏幕直接白掉 */
function warnNoBall() {
  if (S.t - (S._noBallAt || -9) < 1.4) return;
  S._noBallAt = S.t;
  addText(W / 2, 210, "球用完了 · 只能靠卷", "#FF9E8E", 20, 1.2);
  S.shake = Math.max(S.shake, 4);
}

/** "手上有球了，先送走" —— 玩家必须知道为什么这次喷不出去 */
function warnBallFull() {
  if (S.t - (S._fullAt || -9) < 1.4) return;
  S._fullAt = S.t;
  addText(W / 2, 210, "手上已经两颗球 · 先推走一颗", "#FFD08A", 20, 1.2);
}

/** 被滚球卷进去：球变大变重，人从场上消失 */
function absorbIntoBall(f, b) {
  f.dead = true;
  b.packed.push(f.def);
  b.holds = b.packed.length;
  b.r = 20 + Math.min(16, b.holds * 2.8);
  b.w = b.h = b.r * 2;
  b.vx *= 0.97;
  // 卷人回一口气：连锁是有回报的，不然"卷"永远不如"另造一颗"
  b.air = Math.min(1, b.air + 0.10);
  if (b.holds > S.stat.maxHolds) S.stat.maxHolds = b.holds;
  // 撞击之后爆一件掉落 —— 这是短反馈循环里唯一的"意外"
  dropOnAbsorb(b);
  addText(b.x, b.y - b.r * 2 - 16, "卷进去 x" + b.holds, "#B9F06A", 17);
  S.shake = Math.max(S.shake, 5);
}

function makeBallFrom(f, vx, vy) {
  if (f.dead) return;
  f.dead = true;
  S.stat.made++;
  S.stat.maxHolds = Math.max(S.stat.maxHolds, 1);
  // BOSS 球更大更重：滚得慢，但推一次值 14 倍收成。
  const isBoss = !!f.isBoss;
  const r = isBoss ? 44 : 22;
  S.balls.push({
    x: f.x, y: f.y, w: r * 2, h: r * 2, r,
    vx: vx || 0, vy: vy || 0,
    holds: 1, mud: false,
    // 气：这一版的核心压力。球会一直漏，漏到 0 就崩开。
    // 卷人回气，所以"铺场再引爆"是有回报的，但回报有上限。
    air: 1,
    // 冰壳：自己的技能打到球上叠的层数。
    // 有了它，"手上的枪"和"场上的球"才第一次连起来 ——
    // 以前对着自己的球开枪，子弹直接穿过去，像是两套不相干的系统。
    frost: 0, frostCd: 0,
    onGround: false, ground: null,
    t: 0, spin: 0, dead: false,
    boss: isBoss, bossLv: f.lv || 1,
    packed: [f.def],
    hitWall: 0, bounceCd: 0, portalCd: 0,
  });
  S.shake = Math.max(S.shake, 6);
  for (let i = 0; i < 12; i++) addFrag(f.x, f.y - r, 7, "#9BE86E");
}

/* ============================================================================
   10. 球：滚、撞、连锁、地形
   ========================================================================== */

function updateBalls(dt) {
  // 快照遍历：滚球撞到敌人会当场造出新球（push 进 S.balls）。
  // 直接遍历原数组的话，新球会在同一个 dt 里被更新 —— 整条连锁
  // 会在一帧内结算完，玩家看到的是一团光，而不是"滚过去撞出一串"。
  const list = S.balls.slice();
  for (const b of list) {
    if (b.dead) continue;
    b.t += dt;
    // 推球形变回弹：0.3 秒内从压扁回到圆。不衰减的话，球会一直是个横椭圆。
    if (b.pushSquash > 0) b.pushSquash = Math.max(0, b.pushSquash - dt * 1.9);

    // 寿命上限已由"气"接管（air <= 0 就崩），这里只留一个兜底，
    // 防止极端情况下球卡在某个角上永远不死
    if (b.t > 45) { burstBall(b); continue; }

    // 掉出世界（不该发生，但一旦发生就永远不消失，把整局卡死）
    if (b.y > H + 200) { b.dead = true; continue; }

    // ---- 漏气：这一版的核心压力
    // 滚动时慢慢漏，停着漏得更快。于是"攒 3 只再推"不是免费的：
    // 你攒的时间直接从这个球的剩余里程里扣。卷人回一口气，
    // 所以铺场是有回报的，但回报封顶，攒不出永动机。
    // 上一版用的是"停住 4.2 秒崩开"的固定倒计时 —— 玩家只要一路推着
    // 球走，倒计时就永远不开始，等于没有压力。
    const idle = b.onGround && Math.abs(b.vx) < 60;
    b.air -= dt * (idle ? 0.11 : 0.055);
    if (b.air <= 0) { b.air = 0; burstBall(b); continue; }

    // ---- 「推出去 = 一次性」
    // 用户的原话：球在底层的时候，只要推出去之后都要消失。
    // 不这么做的话，地面无摩擦 + 撞墙只衰减一次，底层会永远有几颗球在溜达，
    // 玩家分不清"哪颗还能用、哪颗是上一波的残骸"。
    //
    // 给 1.6 秒：够它滚 990px（从场中间推到墙、弹回来再撞第二串），
    // 但彻底堵死"无限滚"。自造但没推过的球不受这条约束 —— 玩家还能走上去推它。
    if (b.pushed) {
      b.relT = (b.relT || 0) + dt;
      if (b.relT > PUSH_LIFE) { burstBall(b, "滚远了…"); continue; }
    }

    // ---- 不减速。
    // 上一版给球加了摩擦（170/s），推出去滚 1100px 就自己停，玩家得追着推。
    // 现在地面完全无摩擦：球一旦被推起来就一路滚，直到撞墙、掉坑、漏气崩开。
    // 唯一的衰减来自**撞墙 ×0.62** —— 所以"往哪个方向推"变成一次真赌注：
    // 推对了滚穿一整层，推错了撞两次墙才能停下来再补一脚。
    //
    // 副作用（故意留着的）：球的巡航速度比玩家快，追不上。
    // 玩家必须提前决定，而不是跟在球屁股后面慢慢修 —— 这正是想要的手感。
    b.x += b.vx * dt;
    b.spin += b.vx * dt * 0.05;
    // 撞墙反弹。推出去的球最多弹一次 —— 第二次撞墙就地散掉，
    // 这是"底层不出现来回溜达的球"的最后一道闸。
    if (b.x - b.r < WALL_L || b.x + b.r > WALL_R) {
      const left = b.x - b.r < WALL_L;
      b.x = left ? WALL_L + b.r : WALL_R - b.r;
      b.vx = -b.vx * 0.62;
      S.shake = Math.max(S.shake, 4);
      if (b.pushed) {
        b.wallHits = (b.wallHits || 0) + 1;
        if (b.wallHits >= 3) { burstBall(b, "撞散了…"); continue; }
      }
    }

    // 撞木桩：球是唯一能打碎木桩的东西 —— 所以"想开新路"必须先造球
    for (const s of S.stumps) {
      if (s.hp <= 0) continue;
      const top = s.y - s.h;
      // 这里的判据是**球底**而不是球顶：球底已经高过木桩顶面，
      // 说明它是在桩子上面滚过去的，不该被侧面挡住。
      // 写成 b.y - b.r（球顶）的话，条件刚好反过来 ——
      // 球永远撞不到木桩，而玩家看起来只是"木桩没有反应"。
      if (b.y <= top + 2) continue;
      const l = s.x - s.w / 2, r = s.x + s.w / 2;
      if (b.x + b.r > l && b.x - b.r < r) {
        if (b.vx > 0) { b.x = l - b.r; } else if (b.vx < 0) { b.x = r + b.r; }
        else { b.x = l - b.r; }
        b.vx = -b.vx * 0.62;
        s.hp -= 1;
        s.shake = 0.2;
        S.shake = Math.max(S.shake, 8);
        hitStop(0.04);
        addText(s.x, top - 20, s.hp > 0 ? "咔!" : "撞碎了!", "#FFD08A", 18);
        for (let i = 0; i < 10; i++) addFrag(s.x, top + 10, 6, "#A97E4E");
        if (s.hp <= 0) {
          // 碎木桩掉果子 —— 破坏要立刻给回报，否则玩家不会主动去撞
          dropFrom(s.x, top + 26, 0.6);
          dropFrom(s.x, top + 26, 0.3);
        }
      }
    }

    // 重力 + 落地
    const prevY = b.y;
    b._fallVy = b.vy;
    b.vy = Math.min(b.vy + GRAV * dt, MAXFALL);
    b.y += b.vy * dt;
    b.onGround = false;
    b.ground = null;
    if (b.vy >= 0) {
      let best = null;
      for (const p of PLATS) {
        if (b.x + b.r < p.x || b.x - b.r > p.x + p.w) continue;
        if (prevY <= p.y + 2 && b.y >= p.y) {
          if (!best || p.y < best.y) best = p;
        }
      }
      if (best) { b.y = best.y; b.vy = 0; b.onGround = true; b.ground = best; }
    }

    // ---- 斜坡（第 4 关）
    // 球被"贴"在坡面上走：每帧把球底压到坡面高度，位移由 vx 决定，
    // 所以坡度只是一个 y = f(x) 的约束，不需要额外的碰撞体。
    // 速度变化用重力沿坡面的分量：上坡掉速、下坡加速 —— 这是物理，不是摩擦。
    const rp = rampAt(b.x);
    if (rp && b.vy >= -40 && onRampSurface(b.y, rp, prevY, 20)) {
      b.y = rp.y;
      b.vy = 0;
      b.onGround = true;
      b.vx -= GRAV * rp.slope * 0.45 * dt;
    }

    // ---- 弹簧菇（第 5 关）
    // 弹起 228px（980²/2g）：556 → 328，刚够越过 350 那层。
    // 再高就会顶到 248 层的底面，球在两层之间来回弹，看起来像卡住了。
    b.bounceCd = Math.max(0, (b.bounceCd || 0) - dt);
    if (b.bounceCd <= 0) {
      for (const bo of BOUNCERS) {
        if (Math.abs(b.x - bo.x) > 30) continue;
        if (b.y < bo.y - 60 || b.y > bo.y + 10) continue;
        b.vy = -980;
        // 几乎停住的球会被弹成"原地上下跳"，一直跳到漏气崩开（实测 12 次）。
        // 给一点水平推力，保证它会飞出去。
        if (Math.abs(b.vx) < 180) b.vx = (b.vx < 0 ? -1 : 1) * 200;
        b.onGround = false;
        b.bounceCd = 0.35;
        addText(bo.x, bo.y - 74, "弹!", "#C9F27A", 18);
        for (let i = 0; i < 8; i++) addFrag(bo.x, bo.y - 6, 6, "#8ED36A");
        S.shake = Math.max(S.shake, 4);
      }
    }

    // ---- 传送洞（第 6 关）
    // 保持水平速度原样穿过去 —— 方向不变，只换位置。
    // 所以"从左进、从右出"之后球还是往右滚，一球能把两端的人串成一条链。
    b.portalCd = Math.max(0, (b.portalCd || 0) - dt);
    if (b.portalCd <= 0) {
      for (const pt of PORTALS) {
        if (Math.abs(b.x - pt.x) > 26) continue;
        if (b.y < pt.y - 70 || b.y > pt.y + 8) continue;
        const o = PORTALS.find(q => q.id === pt.link);
        if (!o) continue;
        b.x = o.x;
        b.y = o.y;
        b.vy = 0;
        b.portalCd = 0.45;
        addText(o.x, o.y - 86, "穿过来了", "#9FE4FF", 17);
        for (let i = 0; i < 10; i++) addFrag(pt.x, pt.y - 26, 6, "#7FD8F0");
        for (let i = 0; i < 10; i++) addFrag(o.x, o.y - 26, 6, "#7FD8F0");
        S.shake = Math.max(S.shake, 4);
        break;
      }
    }

    // 撞敌人：不满 3 层的糊一层（泥球糊两层），已经 2 层的被一撞就卷进球里
    if (Math.abs(b.vx) > 60 || Math.abs(b.vy) > 60) {
      for (const f of S.foes) {
        if (f.dead || f.coat >= (f.cm || 3)) continue;
        const dx = Math.abs(b.x - f.x), dy = Math.abs((b.y - b.r) - (f.y - f.h / 2));
        if (dx > b.r + f.w / 2 || dy > b.r + f.h / 2) continue;

        // BOSS：球撞上去糊一层，然后**弹回来**。
        // 这一条是 BOSS 战和普通战最大的区别：普通怪被撞就滚过去，
        // BOSS 把球弹回来 —— 玩家可以站在旁边连续推同一颗球砸它，
        // 不用每次重新糊一颗。限球关才打得动。
        if (f.isBoss) {
          coatFoe(f, (b.mud ? 2 : 1) + (b.frost || 0), null);
          if (b.frost > 0) { b.frost = 0; addText(b.x, b.y - b.r * 2 - 8, "冰壳碎了", "#BFE8FF", 15); }
          const dr = b.x < f.x ? -1 : 1;
          b.x = f.x + dr * (f.w / 2 + b.r + 2);
          b.vx = dr * Math.max(380, Math.abs(b.vx) * 0.85);
          b.vy = -140;
          b.relT = Math.max(0, (b.relT || 0) - 0.7);
          hitStop(0.05);
          S.shake = Math.max(S.shake, 9);
          S.flash = Math.max(S.flash, 0.06);
          continue;
        }

        // 冰壳是"一次性的弹药"：这一撞多吃几层，吃完全掉。
        // 不消耗的话，打三枪就能白嫖一整局，推球这件事就没有代价了。
        const frost = b.frost || 0;
        coatFoe(f, (b.mud ? 2 : 1) + frost, b);
        if (frost > 0) {
          b.frost = 0;
          addText(b.x, b.y - b.r * 2 - 8, "冰壳碎了", "#BFE8FF", 15);
          for (let i = 0; i < 7; i++) addFrag(b.x, b.y - b.r, 4, "#CFEFFF");
        }
        // 撞人不减速（阻尼那一节已经删了），只把球轻轻顶偏一点点，
        // 否则球会"穿过"一排敌人而不产生任何节奏变化。
        b.vx *= 0.995;
        S.shake = Math.max(S.shake, 5);
      }
    }

    // 地形判定。把"落下来时的竖直速度"一起传进去 ——
    // 水塘只认砸进水里的球（见 ballTerrain 里的理由）。
    ballTerrain(b, b._fallVy || 0);

    // 气到很低就开始抖 —— 视觉上给"快崩了"的信号，不用玩家盯血条
    b.x = clamp(b.x, WALL_L + b.r, WALL_R - b.r);

  }

  // ---- 球撞球：连带一起滚
  // 上一版两颗球互相穿透、各走各的 —— 场上两颗球像活在不同局里。
  // 现在撞上就把速度交给对方，两颗以同一个速度一起往前滚：
  // 一颗慢球可以被快球"带起来"，一路串成一条。
  for (let i = 0; i < S.balls.length; i++) {
    const a = S.balls[i];
    if (a.dead) continue;
    for (let j = i + 1; j < S.balls.length; j++) {
      const b = S.balls[j];
      if (b.dead) continue;
      const dx = b.x - a.x;
      const dy = (b.y - b.r) - (a.y - a.r);
      const sum = a.r + b.r;
      if (dx * dx + dy * dy > sum * sum) continue;
      // 只处理"正在靠近"的一对。两颗已经同速贴在一起的时候，
      // 每帧都结算一次会让它们像黏住一样抖。
      if (dx * (b.vx - a.vx) >= 0) continue;

      // 谁快听谁的：方向取快那颗的方向，速度取它的 96%（一撞掉 4%）
      const lead = Math.abs(a.vx) >= Math.abs(b.vx) ? a : b;
      const trail = lead === a ? b : a;
      const dir = sign(lead.vx) || 1;
      const sp = Math.abs(lead.vx) * 0.96;
      if (sp < 60) continue;

      // 分开，别让它们叠在一起
      const need = sum - Math.abs(dx) + 1;
      const sd = sign(dx) || dir;
      a.x -= sd * need * 0.5;
      b.x += sd * need * 0.5;

      lead.vx = dir * sp;
      trail.vx = dir * sp;
      // 被带起来的那颗也要算"推出去的"：不然它永远不消失，
      // 底层会留一颗不知道从哪来的球。
      for (const q of [a, b]) {
        q.pushed = true;
        q.relT = 0;
        q.wallHits = Math.min(q.wallHits || 0, 1);
      }
      addText((a.x + b.x) / 2, Math.min(a.y, b.y) - a.r * 2 - 12, "连滚!", "#FFE58A", 17);
      S.shake = Math.max(S.shake, 5);
    }
  }

  // 清掉死球
  let w = 0;
  for (let i = 0; i < S.balls.length; i++) if (!S.balls[i].dead) S.balls[w++] = S.balls[i];
  S.balls.length = w;
}

/* ----------------------------------------------------------------------------
   预瞄线
   ----------------------------------------------------------------------------
   这一版最重要的一件东西。没有它，玩家在"撞一下看看"；有了它，玩家在
   "算这一球能撞几个、会落在哪"。同一个物理，两种游戏。

   只模拟球自己会遇到的东西：墙、木桩、平台、地形。**不模拟敌人**，
   因为敌人会让球减速（每次 ×0.94）—— 忽略它只会让预测偏"远"，
   也就是"线画到哪，球至少能滚到哪"，宁可保守不要骗人。

   静态的球画左右两条。推球在雪人式玩法里就是个二选一，
   把两个后果并排摆出来，决策成本比读文字小一个数量级。
   -------------------------------------------------------------------------- */
const AIM_DT = 1 / 60;

function predictBall(b, dir) {
  const r = b.r;
  let x = b.x, y = b.y;
  let vx = dir * PUSH_BASE, vy = -40;
  let air = b.air;
  let mud = b.mud;
  let onGround = false;
  let bounce = 0, travel = 0, portalCd = 0, bouncerCd = 0, relT = 0;

  const pts = [{ x, y: y - r }];
  const marks = [];
  const hitFoes = [];
  let end = "air";

  for (let i = 0; i < 360; i++) {
    // 用滚动漏气速率（0.055），不用静止的 0.11：预测算的是"推出去之后
    // 能滚多远"，按滚动算才对得上。
    air -= AIM_DT * 0.055;
    if (air <= 0) { end = "air"; break; }

    // 推出后 1.6 秒必散 —— 和 updateBalls 的寿命同一条。
    // 不画这一段，玩家就会以为线尾那段还算数，等于骗人。
    relT += AIM_DT;
    if (relT > PUSH_LIFE) {
      marks.push({ x, y: y - r, kind: "expire" });
      end = "expire";
      break;
    }

    // 不减速 —— 和 updateBalls 严格一致。这里如果偷偷加一点阻尼，
    // 线就会画短，玩家按线推出去球多滚一截，"预瞄骗人"是这一版最不能犯的错。
    x += vx * AIM_DT;
    travel += Math.abs(vx) * AIM_DT;

    if (x - r < WALL_L) { x = WALL_L + r; vx = -vx * 0.62; bounce++; }
    if (x + r > WALL_R) { x = WALL_R - r; vx = -vx * 0.62; bounce++; }
    // 只能弹一次：第二次撞墙球就散了（和 updateBalls 同一条）。
    // 以前允许弹三次，是因为球还能无限滚；现在球是"一次性"的，
    // 线画过第二次撞墙就是在骗人。
    if (bounce >= 3 || travel > 4000) { end = "wall"; break; }
    if (onGround && Math.abs(vx) < 40) { end = "stop"; break; }

    // 木桩：球撞上去就停，这是"想开新路先造球"的那道门
    let stump = null;
    for (const s of S.stumps) {
      if (s.hp <= 0) continue;
      const top = s.y - s.h;
      if (y <= top + 2) continue;
      if (x + r > s.x - s.w / 2 && x - r < s.x + s.w / 2) { stump = s; break; }
    }
    if (stump) { marks.push({ x, y: y - r, kind: "stump" }); end = "stump"; break; }

    // 重力 + 落地
    const prevY = y;
    vy = Math.min(vy + GRAV * AIM_DT, MAXFALL);
    y += vy * AIM_DT;
    onGround = false;
    if (vy >= 0) {
      let best = null;
      for (const p of PLATS) {
        if (x + r < p.x || x - r > p.x + p.w) continue;
        if (prevY <= p.y + 2 && y >= p.y) { if (!best || p.y < best.y) best = p; }
      }
      if (best) { y = best.y; vy = 0; onGround = true; }
    }

    // 斜坡：和 updateBalls 同一套公式
    const rp = rampAt(x);
    if (rp && vy >= -40 && onRampSurface(y, rp, prevY, 20)) {
      y = rp.y; vy = 0; onGround = true;
      vx -= GRAV * rp.slope * 0.45 * AIM_DT;
    }

    // 弹簧菇
    bouncerCd = Math.max(0, bouncerCd - AIM_DT);
    if (bouncerCd <= 0) {
      for (const bo of BOUNCERS) {
        if (Math.abs(x - bo.x) > 30) continue;
        if (y < bo.y - 60 || y > bo.y + 10) continue;
        vy = -980; onGround = false; bouncerCd = 0.35;
        if (Math.abs(vx) < 180) vx = (vx < 0 ? -1 : 1) * 200;
        marks.push({ x: bo.x, y: bo.y - 46, kind: "bounce" });
      }
    }

    // 传送洞
    portalCd = Math.max(0, portalCd - AIM_DT);
    if (portalCd <= 0) {
      for (const pt of PORTALS) {
        if (Math.abs(x - pt.x) > 26) continue;
        if (y < pt.y - 70 || y > pt.y + 8) continue;
        const o = PORTALS.find(q => q.id === pt.link);
        if (!o) continue;
        marks.push({ x: pt.x, y: pt.y - 46, kind: "portal" });
        x = o.x; y = o.y; vy = 0; portalCd = 0.45;
        marks.push({ x: o.x, y: o.y - 46, kind: "portal" });
        break;
      }
    }

    // 会撞到几只（不扣速，只数数）
    for (const f of S.foes) {
      if (f.dead || f.coat >= (f.cm || 3)) continue;
      if (hitFoes.indexOf(f) >= 0) continue;
      if (Math.abs(x - f.x) < r + f.w / 2 && Math.abs((y - r) - (f.y - f.h / 2)) < r + f.h / 2) {
        hitFoes.push(f);
        marks.push({ x: f.x, y: f.y - f.h - 10, kind: "foe", n: hitFoes.length });
      }
    }

    // 地形：火坑断连锁、泥坑变强、水塘沉底、营地收工
    let hitPit = false;
    for (const pit of PITS) {
      if (pit.kind === "fire") {
        if (x > pit.x + 8 && x < pit.x + pit.w - 8 && y >= pit.y - 8) {
          marks.push({ x, y: y - r, kind: "fire" }); end = "fire"; hitPit = true; break;
        }
      } else if (pit.kind === "water") {
        if (vy > 240 && x > pit.x + 6 && x < pit.x + pit.w - 6 && y >= pit.y - 10) {
          marks.push({ x, y: y - r, kind: "water" }); end = "water"; hitPit = true; break;
        }
      } else if (pit.kind === "mud" && !mud) {
        if (x > pit.x && x < pit.x + pit.w && y >= pit.y - 8) {
          mud = true;
          marks.push({ x, y: y - r, kind: "mud" });
        }
      }
    }
    if (hitPit) break;

    if (y >= GROUND_Y - 6 && x > CAMP.x && x < CAMP.x + CAMP.w) {
      marks.push({ x, y: GROUND_Y - 40, kind: "camp" }); end = "camp"; break;
    }

    if (i % 4 === 0) pts.push({ x, y: y - r, ph: bounce > 0 ? 1 : 0 });
  }

  pts.push({ x, y: y - r, ph: bounce > 0 ? 1 : 0 });
  return { pts, marks, end, hits: hitFoes.length };
}

/** 取缓存：球没动、气没变、敌人没死，就不用重算 */
function aimFor(b, dir) {
  b._aim = b._aim || {};
  const key = [Math.round(b.x / 6), Math.round(b.y / 6), Math.round(b.air * 24),
               S.foes.map(f => (f.dead || f.coat >= (f.cm || 3)) ? 0 : 1).join(""),
               S.stumps.map(s => s.hp).join("")].join("|");
  const slot = b._aim[dir];
  if (slot && slot.key === key) return slot.val;
  const val = predictBall(b, dir);
  b._aim[dir] = { key, val };
  return val;
}

function ballTerrain(b, fallVy) {  // 火坑：烧掉，收成翻倍，但球没了 -> 断连锁
  for (const pit of PITS) {
    if (pit.kind !== "fire") continue;
    if (b.x > pit.x + 8 && b.x < pit.x + pit.w - 8 && b.y >= pit.y - 8) {
      b.dead = true;
      S.stat.burned++;
      const gain = b.holds * (b.boss ? 14 : 2);
      S.food += gain;
      S.killed += b.holds;
      addText(b.x, pit.y - 70, "烧掉了 +" + gain, "#FFB05C", 22);
      dropChest(b.x + 26, pit.y - 52, b.holds);
      for (let i = 0; i < 26; i++) addFrag(b.x, pit.y - 12, 8, i % 2 ? "#FF9A3C" : "#FFD86B");
      S.shake = Math.max(S.shake, 10);
      S.flash = 0.18;
      return;
    }
  }

  // 水塘：球沉底，人被冲回岸上。
  // 这是三个落点里最差的一个：没有收成、球没了、人还得重新裹一遍。
  // 它存在的唯一意义就是让"推过头"有代价 —— 没有水塘的那几关，
  // 往左推和往右推一样安全，预瞄线就只剩"能撞几个"这一个信息。
  for (const pit of PITS) {
    if (pit.kind !== "water") continue;
    // 只有"砸进去"才沉（竖直速度 > 240）。
    // 不这么判的话，水塘放在场地两端就变成必死区：球撞墙反弹之后一定会
    // 从水面滚过去，泥沼那关机器人沉了 113 颗球，240 秒只清掉 3 只。
    if ((fallVy || 0) > 240 && b.x > pit.x + 6 && b.x < pit.x + pit.w - 6 && b.y >= pit.y - 10) {
      b.dead = true;
      S.stat.drowned++;
      const back = respawnPacked(b, 1, b.x);
      for (const f of back) S.foes.push(f);
      addText(b.x, pit.y - 74, "沉底了…", "#8FD8F0", 20);
      for (let i = 0; i < 18; i++) addFrag(b.x, pit.y - 14, 7, i % 2 ? "#7FC8E8" : "#CFEFFA");
      S.shake = Math.max(S.shake, 5);
      return;
    }
  }

  // 泥坑：球裹上泥，变重 —— 之后每次撞人 +2 层。这是"强化通道"，
  // 不是惩罚。三个地形各自对应一种"这一球我想要什么"。
  for (const pit of PITS) {
    if (pit.kind !== "mud" || b.mud) continue;
    if (b.x > pit.x && b.x < pit.x + pit.w && b.y >= pit.y - 8) {
      b.mud = true;
      b.vx *= 0.72;
      addText(b.x, pit.y - 60, "裹泥 · 更狠", "#B98A4E", 19);
      for (let i = 0; i < 10; i++) addFrag(b.x, pit.y - 10, 6, "#8A6238");
    }
  }

  // 营地：落袋为安，每个 +1 且额外 +1
  if (b.y >= GROUND_Y - 6 && b.x > CAMP.x && b.x < CAMP.x + CAMP.w) {
    b.dead = true;
    S.stat.banked++;
    // 落袋关考的是"只数"，不是"球数"：一球装三只走营地算三只
    S.stat.bankHolds += b.holds;
    const gain = b.holds + 1 + (b.boss ? 12 : 0);
    S.food += gain;
    S.killed += b.holds;
    addText(b.x, CAMP.y - 80, "落袋 +" + gain, "#FFD86B", 22);
    dropChest(b.x - 26, CAMP.y - 56, b.holds);
    for (let i = 0; i < 16; i++) addFrag(b.x, CAMP.y - 40, 7, "#FFD86B");
    S.shake = Math.max(S.shake, 6);
  }
}

/**
 * 把球里装着的人放回场上（崩开 / 沉底共用）。
 * coat 给 1：重新裹一层，玩家还得再糊两下，不能白赚。
 */
function respawnPacked(b, coat, atX) {
  // BOSS 崩开吐回来的还得是 BOSS。吐成普通怪的话，玩家会觉得"打错了"，
  // 而且下一轮再糊满会造出一颗普通球 —— 一个 BOSS 能漏成两条命。
  if (b.boss) {
    return [foeFromSpec({ foe: "boss", x: atX === undefined ? b.x : atX,
                          y: b.y - b.r * 2, lv: b.bossLv || 1 }, false)];
  }
  const n = b.packed.length;
  const out = [];
  const cx = atX === undefined ? b.x : atX;
  for (let i = 0; i < n; i++) {
    const def = b.packed[i];
    out.push({
      def, kind: def.kind,
      x: cx + (i - (n - 1) / 2) * 26, y: b.y - b.r * 2,
      w: def.w, h: def.h,
      vx: rand(-60, 60), vy: -260,
      face: -1, coat: coat, dead: false,
      onGround: false, ground: null,
      fly: def.kind === "fly", homeY: b.y - b.r * 2 - 20,
      stun: 0.5, hitT: 0, bob: rand(0, 6.28),
      dir: S.rng() < 0.5 ? -1 : 1,
      chargeT: 2, charging: 0,
    });
  }
  return out;
}

function burstBall(b, why) {
  b.dead = true;
  S.stat.burst++;
  // 装几只就吐几只 —— 和 absorbIntoBall 严格对称。
  // 少了就白赚，多了敌人会自己增殖，两种都会让局面失控。
  for (const f of respawnPacked(b, 1)) S.foes.push(f);
  addText(b.x, b.y - b.r * 2 - 20, why || "崩开了…", "#FF9E8E", 19);
  for (let i = 0; i < 18; i++) addFrag(b.x, b.y - b.r, 7, "#8FBF5E");
  S.shake = Math.max(S.shake, 7);
}

/* ----------------------------------------------------------------------------
   掉落
   ----------------------------------------------------------------------------
   球卷进一个人就爆一次。这不是"奖励"，是**让撞击有悬念**：

     · 大部分时候是一颗野果（+1 收成），维持基础经济
     · 偶尔是气罐（球回 28% 气）—— 连锁越长越容易出，直接强化"攒大球"
     · 更少见的晶核（+5）、心（回 1 点血）
     · 连锁越长，稀有池越宽 —— 这是"卷"除清场之外的第二层回报

   用 S.rng，所以固定种子下序列可复现，测试能断言概率结构。
   -------------------------------------------------------------------------- */
const DROP_KINDS = {
  fruit: { name: "野果", food: 1, color: "#FF6B5E", ring: "#FFD0C8" },
  berry: { name: "蜜莓", food: 2, color: "#C46BFF", ring: "#EBC8FF" },
  air:   { name: "气罐", air: 0.28, color: "#78D8FF", ring: "#D2F2FF" },
  gem:   { name: "晶核", food: 5,  color: "#7CF2C8", ring: "#D6FFF0" },
  heart: { name: "心",   heal: 1,   color: "#FF5A7A", ring: "#FFD6DE" },
  chest: { name: "宝箱", chest: true, color: "#FFC53D", ring: "#FFF3C0" },
};

/**
 * 宝箱 —— 只有「被球送走」才可能掉。
 *
 * 掉落点只有两个：火坑结算、营地结算。武器糊不死人（敌人只会被裹成球），
 * 所以「只有雪人式击杀才有宝箱」这条不用额外判断，是机制自带的。
 *
 * 概率随**这一球连带送走几只**上浮：
 *   单杀 14% / 两只 38% / 三只 62% / 四只以上封顶 85%
 * 这就是「卷」的第三层回报 —— 第一层省球，第二层稀有掉落，第三层宝箱。
 */
function dropChest(x, y, holds) {
  const p = Math.min(0.85, 0.14 + (holds - 1) * 0.24);
  if (S.rng() > p) return false;
  S.drops.push({
    kind: "chest", x, y,
    vx: rand(-110, 110), vy: rand(-430, -280),
    taken: false, t: 0, spin: rand(0, 6.28), holds: holds || 1,
  });
  addText(x, y - 30, "宝箱!", "#FFD65C", 21);
  S.shake = Math.max(S.shake, 5);
  return true;
}

/**
 * 在 (x, y) 爆一件掉落物。
 * boost 是"连锁长度加成"（0~1.5），越大越容易出稀有。
 */
function dropFrom(x, y, boost) {
  boost = clamp(boost || 0, 0, 1.5);
  const r = S.rng() * 100;
  let kind;
  if (r < 5 + boost * 9)        kind = "heart";
  else if (r < 16 + boost * 20) kind = "gem";
  else if (r < 32 + boost * 22) kind = "air";
  else if (r < 62)              kind = "berry";
  else                          kind = "fruit";

  S.drops.push({
    kind, x, y,
    vx: rand(-160, 160), vy: rand(-400, -230),
    taken: false, t: 0, spin: rand(0, 6.28),
  });
}

/** 卷进去一个人：爆一件掉落，连锁越长越容易出好东西 */
function dropOnAbsorb(b) {
  dropFrom(b.x, b.y - b.r * 1.6, (b.holds - 1) * 0.5);
}

/* ============================================================================
   11. 弹丸
   ========================================================================== */

function spawnShot(o) {
  const s = Object.assign({
    vx: 0, vy: 0, r: 9, life: 0.5,
    color: "#FFFFFF", kind: "ball",
    pierce: false, grav: 0, aoe: 0,
    dir: 1, t: 0, spin: 0, bounces: 0,
  }, o);
  s.maxLife = s.life;
  s.hit = [];
  S.shots.push(s);
}

/**
 * 弹丸。六种 role 各走一条分支，但**命中之后的效果完全一样**（+1 层）。
 * 差异化只在"怎么打到"：来回、绕圈、贴地滚、抛、平推。
 */
function updateShots(dt) {
  const p = S.p;
  // 分身吐出来的影弹先攒着，循环结束再并进 S.shots ——
  // 边遍历边 push 会让新弹丸在同一个 dt 里被更新两次，轨道会跳一格。
  const spawned = [];
  for (const s of S.shots) {
    if (s.dead) continue;
    s.life -= dt;
    s.t = (s.t || 0) + dt;

    /* ---- 溜溜球：伸出去、拉回来。绳子一直连着人，人动了球跟着动 ---- */
    if (s.kind === "yoyo") {
      const u = (s.u && !s.u.dead) ? s.u : p;
      const T = 0.30;
      const k = s.t < T ? s.t / T
                        : Math.max(0, 1 - (s.t - T) / Math.max(0.001, s.maxLife - T));
      s.x = u.x + s.dir * (18 + k * 230);
      s.y = u.y - 26;
      s.spin += dt * 30;
      if (s.life <= 0) s.dead = true;
    }
    /* ---- 音波：一颗会撑开来的弹。往前飞，波前一路变宽 ---- */
    else if (s.kind === "wave") {
      s.x += s.vx * dt;
      s.r = Math.min(s.maxR || 46, s.r + (s.grow || 130) * dt);
      if (s.x < WALL_L - 40 || s.x > WALL_R + 40) { s.dead = true; continue; }
    }
    /* ---- 飞刀：丢出去，直线带一点下坠，高速自旋，能穿两个人 ---- */
    else if (s.kind === "knife") {
      s.vy += (s.grav || 700) * dt;
      s.x += s.vx * dt;
      s.y += s.vy * dt;
      s.spin += dt * 26;
      if (s.x < WALL_L - 30 || s.x > WALL_R + 30 || s.y > GROUND_Y + 40) s.dead = true;
    }
    /* ---- 坚果：抛物线落地，之后贴地滚。撞墙弹一次 ---- */
    else if (s.kind === "nut") {
      const prevBottom = s.y + s.r;
      s.vy += 1600 * dt;
      s.x += s.vx * dt;
      s.y += s.vy * dt;
      s.spin += s.vx * dt * 0.055;

      // 落在平台顶上（只认"从上面穿下来"的那一层）
      if (s.vy >= 0) {
        let land = null;
        for (const q of PLATS) {
          if (s.x < q.x || s.x > q.x + q.w) continue;
          const bottom = s.y + s.r;
          if (prevBottom <= q.y + 6 && bottom >= q.y) {
            if (land === null || q.y < land) land = q.y;
          }
        }
        if (land !== null) { s.y = land - s.r; s.vy = 0; }
      }

      if (s.x - s.r < WALL_L) {
        s.x = WALL_L + s.r;
        s.vx = -s.vx * 0.86;
        s.dir = -s.dir;
        if (s.bounces-- <= 0) s.dead = true;
      } else if (s.x + s.r > WALL_R) {
        s.x = WALL_R - s.r;
        s.vx = -s.vx * 0.86;
        s.dir = -s.dir;
        if (s.bounces-- <= 0) s.dead = true;
      }
      if (s.life <= 0) s.dead = true;
    }
    /* ---- 其余：直线 / 抛物 ---- */
    else {
      if (s.grav) s.vy += s.grav * dt;
      s.x += s.vx * dt;
      s.y += s.vy * dt;
      s.spin = (s.spin || 0) + dt * 9;

      if (s.kind === "lob") {
        // 只认"这一帧从台面上方落下来"。
        // 上一版只判 `s.y + s.r >= q.y`，那对**头顶上的平台**永远成立 ——
        // 平射出去的萝卜出门第一帧就炸在自己头顶那块板下面。
        const prevBottom = s.y + s.r - s.vy * dt;
        for (const q of PLATS) {
          if (s.x < q.x || s.x > q.x + q.w) continue;
          if (prevBottom <= q.y + 4 && s.y + s.r >= q.y) { explodeShot(s); s.dead = true; break; }
        }
        if (s.dead) continue;
      }
      if (s.life <= 0) {
        if (s.kind === "lob" && s.aoe > 0) explodeShot(s);
        s.dead = true;
        continue;
      }
      if (s.x < WALL_L - 40 || s.x > WALL_R + 40 || s.y < -100) { s.dead = true; continue; }
    }

    /* ---- 命中判定 ---- */
    for (const f of S.foes) {
      if (f.dead || f.coat >= (f.cm || 3)) continue;
      if (s.hit.indexOf(f) >= 0) continue;

      // 判定只有一种：圆。以前音波走"扇形"特判（因为它没有位置，挂在人身上），
      // 现在它自己有位置了，扇形那套就成了唯一一条走不到的分支。
      const dx = Math.abs(s.x - f.x);
      const dy = Math.abs(s.y - (f.y - f.h / 2));
      if (dx >= s.r + f.w / 2 || dy >= s.r + f.h / 2) continue;

      // 萝卜炮：碰到人就炸，不再"穿过去等落地"。
      // 它是唯一一把 AOE，AOE 的判定点必须在**命中那一刻**，
      // 而不是在它落地那一刻 —— 否则平射出去的萝卜只会炸到地面。
      if (s.kind === "lob") {
        explodeShot(s);
        s.dead = true;
        break;
      }

      coatFoe(f, 1);
      s.hit.push(f);
      if (!s.pierce) { s.dead = true; break; }
      if (s.hitMax && s.hit.length >= s.hitMax) { s.dead = true; break; }
    }
    if (s.dead) continue;

    /* ---- 打自己的球 = 给它冻上一层 ----
       球是场上唯一"友方但可被击中"的东西。以前子弹从球身上直接穿过去，
       手上的枪和场上的球像是两套不相干的系统。
       现在打一枪，球多一层冰壳（上限 3）：
         · 撞人时一次多糊一层，用掉就掉 —— 冰壳 3 层 = 一撞就整只卷走
         · 回一点气，所以"先打再推"不是纯亏
       子弹**不消耗**：球是个大目标，判它把子弹吃掉只会让人不敢开枪。 */
    for (const b of S.balls) {
      if (b.dead) continue;
      if ((b.frostCd || 0) > S.t) continue;
      const bdx = Math.abs(s.x - b.x);
      const bdy = Math.abs(s.y - (b.y - b.r));
      if (bdx >= s.r + b.r || bdy >= s.r + b.r) continue;

      b.frostCd = S.t + 0.12;
      const was = b.frost || 0;
      b.frost = Math.min(3, was + 1);
      b.air = Math.min(1, b.air + 0.10);
      for (let i = 0; i < 5; i++) addFrag(b.x, b.y - b.r, 4, "#CFEFFF");
      if (b.frost > was && was < 3) {
        addText(b.x, b.y - b.r * 2 - 10,
                b.frost >= 3 ? "冻实了!" : "冰壳 +1", "#BFE8FF", b.frost >= 3 ? 18 : 15);
        S.shake = Math.max(S.shake, b.frost >= 3 ? 5 : 2);
      }
    }

    /* ---- 木桩挡弹丸（坚果和溜溜球不挡：一个是滚过去的，一个是飞过去的） ---- */
    if (s.kind !== "nut" && s.kind !== "yoyo" && s.kind !== "wave") {
      for (const st of S.stumps) {
        if (st.hp <= 0) continue;
        if (Math.abs(s.x - st.x) < st.w / 2 + s.r && s.y > st.y - st.h) {
          s.dead = true;
          addFrag(s.x, s.y, 4, "#C8A070");
          break;
        }
      }
    }
  }

  if (spawned.length) S.shots.push.apply(S.shots, spawned);

  let w = 0;
  for (let i = 0; i < S.shots.length; i++) if (!S.shots[i].dead) S.shots[w++] = S.shots[i];
  S.shots.length = w;
}

function explodeShot(s) {
  for (const f of S.foes) {
    if (f.dead || f.coat >= (f.cm || 3)) continue;
    const d = Math.hypot(f.x - s.x, (f.y - f.h / 2) - s.y);
    if (d < s.aoe) coatFoe(f, 1);
  }
  for (let i = 0; i < 14; i++) addFrag(s.x, s.y, 7, i % 2 ? "#FFB05C" : "#FFE08A");
  S.shake = Math.max(S.shake, 5);
}

/* ============================================================================
   12. 特效与工具
   ========================================================================== */

function addFrag(x, y, n, color) {
  for (let i = 0; i < n; i++) {
    const a = rand(0, 6.283), sp = rand(60, 240);
    S.frags.push({
      x, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 80,
      life: rand(0.3, 0.7), max: 0.7, color, r: rand(2, 4.5),
    });
  }
  if (S.frags.length > 320) S.frags.splice(0, S.frags.length - 320);
}

function addText(x, y, txt, color, size, life) {
  S.texts.push({ x, y, txt, color, size: size || 18, life: life || 0.9, max: life || 0.9 });
  if (S.texts.length > 24) S.texts.splice(0, S.texts.length - 24);
}

function hitStop(t) { S.hitStop = Math.max(S.hitStop, t); }

function overlap(a, b) {
  return Math.abs(a.x - b.x) < (a.w + b.w) / 2 &&
         Math.abs((a.y - a.h / 2) - (b.y - b.h / 2)) < (a.h + b.h) / 2;
}

function tickFx(dt) {
  for (const f of S.frags) {
    f.life -= dt;
    f.x += f.vx * dt; f.y += f.vy * dt;
    f.vy += 900 * dt;
    f.vx *= 0.99;
  }
  let w = 0;
  for (let i = 0; i < S.frags.length; i++) if (S.frags[i].life > 0) S.frags[w++] = S.frags[i];
  S.frags.length = w;

  for (const t of S.texts) { t.life -= dt; t.y -= dt * 42; }
  w = 0;
  for (let i = 0; i < S.texts.length; i++) if (S.texts[i].life > 0) S.texts[w++] = S.texts[i];
  S.texts.length = w;

  for (const s of S.stumps) if (s.shake > 0) s.shake = Math.max(0, s.shake - dt);

  S.shake = Math.max(0, S.shake - dt * 34);
  S.flash = Math.max(0, S.flash - dt * 2.2);

  // 掉落物：抛出去 → 落到最近的平台 → 被玩家捡 / 掉进坑里烧掉 / 15 秒后消失。
  // 落在平台上而不是一律落地面，是因为从高层炸出来的果应该留在高层 ——
  // 玩家在楼上打着架，不该跑下去捡一颗果子。
  for (const d of S.drops) {
    if (d.taken) continue;
    d.t = (d.t || 0) + dt;
    if (d.t > 15) { d.taken = true; continue; }

    const py = d.y;
    d.vy = Math.min(d.vy + 1500 * dt, 900);
    d.x += d.vx * dt;
    d.y += d.vy * dt;
    d.vx *= 0.994;

    // 掉进火坑 / 水塘：直接没了（不然捡一堆果子站在火里吃，很怪）
    // 宝箱例外 —— 它就是在火坑/营地边上刷出来的，被自己的火花烧掉太蠢了
    let gone = false;
    if (d.kind !== "chest") for (const pit of PITS) {
      if (pit.kind === "mud") continue;
      if (d.x > pit.x + 6 && d.x < pit.x + pit.w - 6 && d.y > pit.y - 8) {
        d.taken = true; gone = true;
        for (let i = 0; i < 5; i++) addFrag(d.x, d.y, 4, pit.kind === "fire" ? "#FFB05C" : "#8FD8F0");
        break;
      }
    }
    if (gone) continue;

    if (d.vy >= 0) {
      let best = null;
      for (const p2 of PLATS) {
        if (d.x < p2.x || d.x > p2.x + p2.w) continue;
        if (py <= p2.y + 2 && d.y >= p2.y) { if (!best || p2.y < best.y) best = p2; }
      }
      if (best) { d.y = best.y - 9; d.vy = 0; d.vx = 0; }
    }
    if (d.y > GROUND_Y - 9) { d.y = GROUND_Y - 9; d.vy = 0; d.vx = 0; }
  }
}

/* ============================================================================
   13. 绘制：背景
   ----------------------------------------------------------------------------
   背景只干一件事：把"这是一片林间空地"交代清楚，然后闭嘴。
   任何带形状的东西（树干、叶球）都推到画面两侧和顶部，绝不落进
   平台区 —— 上一版就是因为树画在单位背后，读起来像"战斗发生在树上"。
   ========================================================================== */

const COL = {
  outline: "#3A2B44",
  ink: "#20282A",
  grass1: "#4E8F55",
  grass2: "#6DB867",
  grass3: "#8ACB78",
  dirt: "#5C4432",
  dirt2: "#3E2E22",
  wood: "#7A5638",
  wood2: "#5C3E28",
  wood3: "#9A6E48",
  fireA: "#FF8A2E",
  fireB: "#FFD34E",
  mud: "#4A3826",
  camp: "#C99A4E",
};

/* ----------------------------------------------------------------------------
   Q 版背景
   ----------------------------------------------------------------------------
   原来画的是"暗色森林剪影"：树冠压在顶上、四边压黑、整体低饱和。
   问题是它像**横版探险**，不像**雪人兄弟那种一屏一关的卡通游乐场**。

   这里改成 Q 版战斗场景的四条硬规矩：
     1. 天空要亮、要彩，占画面上半，不能压黑 —— 单位才跳得出来
     2. 云、山、树全部用**圆弧**拼，不出现尖角（尖角 = 写实）
     3. 所有东西都有深色粗描边（3px 左右），像贴纸
     4. 背景对比度永远低于前景：远景只上 30% 不透明度，近景才实色
   -------------------------------------------------------------------------- */

function drawSky(g) {
  const sky = g.createLinearGradient(0, 0, 0, 330);
  sky.addColorStop(0, TH.sky1);
  sky.addColorStop(0.55, TH.sky2);
  sky.addColorStop(1, TH.sky2);
  g.fillStyle = sky;
  g.fillRect(0, 0, W, 340);

  /* 太阳：三层光。
     原来只有"一个圆 + 150 半径的小晕"—— 那读作"天上贴了个黄点"，
     画面整体还是平光，物体之间全靠描边分开。

     第一版把大晕写成 `rgba(255,244,196,.40)`（**接近白**），结果整片天空
     被提亮又掉饱和，出来是"沙漠灰"，不是概念图的金橙 —— 往白里混就是降饱和，
     这一层不能当"光"用，只能当"亮"用。
     大晕必须是**饱和橙**（#FFC96A）：色相推暖、明度只提一点点。 */
  /* 夜关画月亮，不画太阳。
     紫夜 + 一圈暖橙大光晕 = 一片粉紫，读作"日落的延迟摄影"挂在星空上 ——
     这是第 8 关最刺眼的一处违和：地面是夜、天上是黄昏。
     月亮只做三件事：一层弱冷晕、一个满月、几块环形山。
     光晕必须是**冷**的（190,206,255），换成暖白又变回日落。

     位置也不能用太阳那个 (700,74)：右上角被"清场"卡片占着，
     30px 的月亮会被整块盖住 —— 太阳没露馅是因为它的光晕有 520 半径，
     隔着一层卡片还能透出来；月亮小，盖住就真没了。挪到卡片下方。 */
  if (TH.night) {
    const mx = 858, my = 214;
    const night = g.createRadialGradient(mx, my, 16, mx, my, 300);
    night.addColorStop(0, "rgba(196,210,255,.22)");
    night.addColorStop(0.45, "rgba(164,182,242,.09)");
    night.addColorStop(1, "rgba(164,182,242,0)");
    g.fillStyle = night;
    g.fillRect(0, 0, W, 420);

    g.fillStyle = "rgba(242,246,255,.95)";
    g.beginPath();
    g.arc(mx, my, 28, 0, 6.283);
    g.fill();
    /* 环形山。没有它就是一个白色圆点，读作"UI 图标"；
       三块大小不一的暗斑压上去，才读作"月亮是个球"。 */
    g.fillStyle = "rgba(192,204,238,.50)";
    g.beginPath(); g.arc(mx - 8, my - 7, 7, 0, 6.283); g.fill();
    g.beginPath(); g.arc(mx + 8, my + 8, 5, 0, 6.283); g.fill();
    g.beginPath(); g.arc(mx + 11, my - 10, 3.6, 0, 6.283); g.fill();
    return;
  }

  const sunX = 700, sunY = 74;
  const wide = g.createRadialGradient(sunX, sunY, 20, sunX, sunY, 520);
  wide.addColorStop(0, "rgba(255,201,106,.34)");
  wide.addColorStop(0.45, "rgba(255,186,92,.13)");
  wide.addColorStop(1, "rgba(255,186,92,0)");
  g.fillStyle = wide;
  g.fillRect(0, 0, W, 420);

  const halo = g.createRadialGradient(sunX, sunY, 10, sunX, sunY, 140);
  halo.addColorStop(0, "rgba(255,253,226,.72)");
  halo.addColorStop(1, "rgba(255,250,214,0)");
  g.fillStyle = halo;
  g.fillRect(sunX - 150, sunY - 150, 300, 300);

  g.fillStyle = "rgba(255,252,226,.96)";
  g.beginPath();
  g.arc(sunX, sunY, 38, 0, 6.283);
  g.fill();
}

/* 一道从太阳斜打下来的光柱。
   只画一次、alpha 0.07，作用是把"光源在上方"这件事写进画面：
   没有它的时候，暖光只是"底色变黄了"，有了之后才读作"有光照进来"。
   角度固定 62°（不是 45°）—— 45° 会正好压在画面中轴上，
   变成一条把画面劈成两半的斜线；62° 靠右，只在右半屏扫过。 */
function drawSunShaft(g) {
  g.save();
  /* 夜关的"光柱"是月光，要更淡、更冷。暖白光柱压在紫夜色上，
     会在中段扫出一条**灰米色**的斜带 —— 紫里的暖光只会变脏，不会变亮。 */
  g.globalAlpha = TH.night ? 0.05 : 0.07;
  g.fillStyle = TH.night ? "#C8D6FF" : "#FFF6D2";
  g.beginPath();
  g.moveTo(700, 60);
  g.lineTo(760, 60);
  g.lineTo(300, H);
  g.lineTo(-40, H);
  g.closePath();
  g.fill();
  g.restore();
}

/** 一朵 Q 版云：三个圆叠一个平底，全部同一色，只有底部一条淡阴影 */
function drawCloud(g, x, y, sc, alpha) {
  g.save();
  g.globalAlpha = alpha;
  g.fillStyle = TH.cloud;
  g.beginPath();
  g.arc(x - 26 * sc, y + 4 * sc, 20 * sc, 0, 6.283);
  g.arc(x + 2 * sc, y - 8 * sc, 28 * sc, 0, 6.283);
  g.arc(x + 32 * sc, y + 4 * sc, 18 * sc, 0, 6.283);
  g.rect(x - 26 * sc, y + 4 * sc, 58 * sc, 17 * sc);
  g.fill();
  g.fillStyle = "rgba(180,214,240,.30)";
  g.beginPath();
  g.ellipse(x + 4 * sc, y + 19 * sc, 44 * sc, 6 * sc, 0, 0, 6.283);
  g.fill();
  g.restore();
}

/** 远山：二次曲线堆出来的圆顶，两层，越远越淡 */
function drawHills(g, baseY, amp, color, seed, step) {
  g.fillStyle = color;
  g.beginPath();
  g.moveTo(-40, baseY + 40);
  for (let i = 0, x = -40; x < W + 80; i++, x += step) {
    const h = amp * (0.55 + hash(i + seed) * 0.55);
    g.quadraticCurveTo(x + step * 0.5, baseY - h * 1.5, x + step, baseY - amp * 0.16);
  }
  g.lineTo(W + 80, baseY + 40);
  g.closePath();
  g.fill();
}

/** Q 版树：树干一个圆角方块，树冠三四个圆点，深色描边 */
/**
 * 一团树叶的**单条闭合轮廓**。
 *
 * 原来树冠是 3 个圆：`fill()` 三次（canvas 填的是并集，看起来没问题），
 * 然后 `stroke()` 三次 —— **描边描的是三个整圈**，包括落在并集内部的那几段。
 * 结果树冠上出现三条互相穿插的弧线，读作"线框气泡 / 维恩图"，不像树。
 * 这是全场最"画出来"的一处，比平台材质更扎眼。
 *
 * canvas 没有"只描并集外轮廓"的 API（`destination-over` 那条路会把描边压到
 * 整个 canvas 底下，连天空一起盖掉）。所以换思路：**用一条路径画出团块**。
 * 按 13 个角度采样半径（两个不同频率的正弦错开，避免读成规则花边），
 * 再用二次贝塞尔穿过相邻采样点的中点，得到一条平滑闭合曲线。
 * 一条路径 fill、一条路径 stroke，内外永远一致。
 */
function blobPath(g, cx, cy, r, seed) {
  /* **用密集采样 + 直线段，不用二次曲线穿中点。**
   *
   * 二次曲线穿中点的写法在采样点少的时候会把峰顶削成尖角：
   * 13 个点、幅度 0.30 出来一张海星；把幅度收到 0.07 是圆了，但圆成一团气球。
   * 两个极端都不对 —— 一片叶子既有起伏、又不该有尖角。
   *
   * 真因是采样密度：直线段只要够密，本身就看不出折角。
   * 48 个点、半径按两个频率的正弦起伏（0.16 / 0.08 → 3 个大瓣 + 5 个小瓣），
   * 得到的是"一团有起伏的叶子"，成本和二次曲线一样，只是循环次数多。
   * x 方向拉 1.10、y 方向压 0.94：树冠横着长，不是正圆。
   */
  const N = 48;
  g.beginPath();
  for (let i = 0; i <= N; i++) {
    const a = (i / N) * 6.283;
    const k = 1 + 0.16 * Math.sin(a * 3 + seed) + 0.08 * Math.sin(a * 5 - seed * 1.7);
    const px = cx + Math.cos(a) * r * k * 1.10;
    const py = cy + Math.sin(a) * r * k * 0.94;
    if (i === 0) g.moveTo(px, py); else g.lineTo(px, py);
  }
  g.closePath();
}

/**
 * 一棵 Q 版树。
 *
 * `back`   —— true = 无描边（远景/中景）；false = 有描边（贴脸的近景）
 * `dim`    —— 空气透视的浓度，0 = 完全融进雾里，1 = 实色。
 *
 * **为什么要有 dim 这个连续值，而不是"远/中/近"三档枚举：**
 * 上一版只有 back 一个布尔，于是全部中景树只能是同一档颜色、同一档浓度，
 * 九棵排在一起读作"一条墙纸"。参考概念图里远处的树是**一层一层化进雾里**
 * 的，浓度必须连续可调，眼睛才分得出第 1 排、第 2 排、第 3 排。
 *
 * 退后不靠"调低 globalAlpha"（透明会和后面的绿混成脏色，读作"没画清"），
 * 靠**换色**：往地平线雾色里混。混得越多越像在雾里，这正是空气透视。
 */
function drawTree(g, x, baseY, sc, back, dim) {
  const D = dim === undefined ? 1 : dim;
  g.save();
  g.globalAlpha = back ? 0.88 * (0.55 + D * 0.45) : 1;
  /* 树干 60×sc、树冠 27×sc。
   *
   * **这两个数是从"一排绿篱"改回来的。** 原来是 40 / 31 —— 树干 37 高、
   * 树冠 62 宽，比例 1.2，读作"棒棒糖"或"灌木"，不读作树。
   * 中景的一排棒棒糖连起来就成了一道绿篱，这是第一版重做时最刺眼的问题。
   * 真实的中景树在低角度看是**细高的**：树干 58~60、树冠 26~27，
   * 高度/宽度比 1.7 左右，才读成"远处的一棵树"。
   *
   * 树干宽度保持 16×sc 不动（sc=0.8 时 13px）—— 这是比例的另一半，
   * 只拉长不加宽，才有"细高"而不是"柱子变长了"。 */
  const tw = 16 * sc, th = 60 * sc;
  /* 颜色按 depth 在 treeFar ↔ treeNear 之间插值，再往雾里混一点。
   *
   * 上一版只做了一件事：往 horizon 混 (1-D)。D 从 0.28 到 0.82 的树，
   * 每一棵都是**从同一个 treeFar 出发**的，最近那棵也只比最远那棵实一点 ——
   * 拍出来十五棵树同一个淡橄榄色，深度只剩大小差别，整体读作"一层雾树"。
   * 正解是**两端都要动**：最近的那棵吃满 treeNear（深绿、有彩度），
   * 最远的那棵在 treeFar 之外再混 55% 的雾。两端拉开，中间才有梯度。 */
  const mixTo = (1 - D) * 0.55;
  const trunkBase = back ? hexMix(TH.trunkFar, TH.trunkNear, D) : TH.trunkNear;
  const leafBase = back ? hexMix(TH.treeFar, TH.treeNear, D) : TH.treeNear;
  // 树干
  g.fillStyle = back ? hexMix(trunkBase, TH.horizon, mixTo) : TH.trunkNear;
  rr(g, x - tw / 2, baseY - th, tw, th + 4, 5 * sc);
  g.fill();
  // 树冠：一团叶子，不是一个一个圆
  const cy = baseY - th - 13 * sc, r = 27 * sc;
  const seed = (x + (back ? 3.7 : 0)) * 0.031;
  g.fillStyle = back ? hexMix(leafBase, TH.horizon, mixTo) : TH.treeNear;
  blobPath(g, x, cy, r, seed);
  g.fill();

  if (!back) {
    // 统一描边语言：全场物件同一个墨色，只有粗细按"远近"分档。
    // 原来是树 rgba(30,64,44,.55) 偏绿的 2.4px、平台 COL.outline 偏紫的 2.6px ——
    // 同一张画面上两套描边系统，读作"拼的图"，正是用户说的"像贴上去的"。
    g.strokeStyle = COL.ink;
    g.lineWidth = sc > 1.4 ? 3.4 : 2.8;
    blobPath(g, x, cy, r, seed);
    g.stroke();

    /* 受光面：一块**不描边**的浅色团。只有填充没有边线，所以不会又把树冠
       切成两半 —— 有边线就退化成原来那三个圆的问题。

       **受光色必须是暖的。** 原来写 `rgba(226,255,222,.30)`（冷白绿），
       在蓝天版本里看着像"叶面反光"，换到暖金天空之后立刻露馅：
       树冠读作"天上挂了一个浅米绿的球"，和周围一个色温都没有。
       光是橙色天空来的，高光就得偏暖 —— 这一点跟"前景受光边不用纯白"是同一条。

       **受光面必须在朝太阳的那一侧。** 太阳固定在 (700, 74)，原来两棵近景树
       的高光都固定偏左（x - r*0.24）—— 左边那棵（x=6）等于把高光画在了背光面。
       两个物件的受光方向互相矛盾，眼睛就把它们读成"两张贴纸"，
       这是"背景像贴上去的"里最隐蔽的一条。
       现在按 x 和太阳的左右关系取符号：太阳在右边，高光就往右偏。 */
    const lit = (700 - x) >= 0 ? 1 : -1;
    g.fillStyle = "rgba(255,238,178,.24)";
    blobPath(g, x + lit * r * 0.24, cy - r * 0.30, r * 0.42, seed + 1.9);
    g.fill();
    g.fillStyle = "rgba(255,246,206,.34)";
    g.beginPath();
    g.arc(x + lit * r * 0.30, cy - r * 0.42, r * 0.16, 0, 6.283);
    g.fill();
  } else {
    /* 中景树冠也必须有一块受光面 —— **纯剪影排成一行就是一道绿篱**，
       这是重做第一版翻车的地方：15 棵树冠颜色一样、形状一样、没有明暗，
       叠起来读作"一条绿色的墙"，而不是"远处有几棵树"。
       但这里**不能描边**：描边会把远处的树钉到前景（描边的粗细是距离的刻度）。
       只给一块偏移的受光团：往太阳那一侧上移 18% 半径，往天光混 42%，
       远树（D 小）的 alpha 本来就低，这块会自然跟着淡下去。 */
    const lit2 = (700 - x) >= 0 ? 1 : -1;
    g.fillStyle = rgbaOf(hexMix(TH.treeFar, TH.cloud, 0.42), 0.55);
    blobPath(g, x + lit2 * r * 0.18, cy - r * 0.22, r * 0.62, seed + 1.9);
    g.fill();
  }
  g.restore();
}

/* ---- 草脊：地面与远山之间那条边 ------------------------------------------
 *
 * **上一版是 `fillRect(0, 300, W, H - 300)` —— 一条横贯全屏的绝对水平线。**
 * 这是"背景像贴上去的"最大的单一来源：任何一条贯穿整幅画面的直线，
 * 眼睛都会读成"两块图拼在这里"。参考概念图里草地是**一条起伏的脊**，
 * 脊后面才是远山和雾林，所以才有前后。
 *
 * 两个正弦叠加（周期约 2027 / 873，振幅 13 / 6.5），合成起伏 ±19.5px。
 * 周期刻意不成整数比 —— 单个正弦在 960 宽里会左右各留一段同形，
 * 读作"复制粘贴的波浪"。
 *
 * 振幅上限 20 是被碰撞几何反推的：脊线最高 280.5，而最上面那层平台在 248、
 * 坡底在 350，脊线不能越过 300±22 这条带，否则会开始和玩法元素打架。
 */
function ridgeY(x) {
  return 300 + Math.sin(x * 0.0031 + 1.1) * 13 + Math.sin(x * 0.0072 + 3.4) * 6.5;
}

function drawForest(world) {
  const g = ctx;
  g.clearRect(0, 0, W, H);

  drawSky(g);

  // 云：远慢近快，三朵。位置用 hash 固定，不用随机 —— 每帧随机会闪。
  // x=690 那朵原来正好压在太阳上（太阳默认 700,74），整颗太阳被吃掉，
  // 只剩一圈光晕 —— 于是"有光没太阳"。向左让出 110。
  drawCloud(g, 160 + Math.sin(S.t * 0.10) * 14, 66, 1.0, 0.92);
  drawCloud(g, 470 + Math.sin(S.t * 0.14 + 2) * 18, 44, 0.74, 0.80);
  drawCloud(g, 560 + Math.sin(S.t * 0.08 + 4) * 10, 104, 0.62, 0.62);
  drawCloud(g, 300 + Math.sin(S.t * 0.12 + 1) * 12, 122, 0.48, 0.45);

  // 远山三层：最远一道近白的雾（只有轮廓）→ 远山 → 近山。
  // 两层不够 —— 只有两级的话"远"和"中"挨在一起，读作同一片背景。
  drawHills(g, 296, 104, rgbaOf("#FFFFFF", 0.20), 3, 224);
  drawHills(g, 310, 72, TH.hillFar, 7, 178);
  drawHills(g, 324, 46, TH.hillNear, 11, 134);

  // 光柱压在山之上、地表之下：光是在空气里走的，被山挡住就成了贴纸。
  drawSunShaft(g);

  // 地平线雾带：山脚到草地之间 68px 的天空色残余。
  // 没有这一层，草地是"一刀切"压在山脚上的，读作两块色板拼接。
  // **必须在草脊之前画** —— 它盖的是山脚，不是草地。
  const hz = g.createLinearGradient(0, 284, 0, 352);
  hz.addColorStop(0, rgbaOf(TH.horizon, 0.94));
  hz.addColorStop(1, rgbaOf(TH.horizon, 0));
  g.fillStyle = hz;
  g.fillRect(0, 284, W, 68);

  // 地面：明度纵深三档。地平线亮（远处受天光）、中段本色、画面底部最暗。
  // 一整片同色读作"一张绿色纸"；压一道 26% 的明度落差，地面自己就有纵深了。
  // **上边界是草脊曲线，不是一条直线**（见 ridgeY 的注释）。
  const gr = g.createLinearGradient(0, 276, 0, H);
  gr.addColorStop(0, TH.grassLight);
  gr.addColorStop(0.30, TH.grass2);
  gr.addColorStop(0.68, TH.grass);
  gr.addColorStop(1, TH.grassDark);
  g.fillStyle = gr;
  g.beginPath();
  g.moveTo(0, H);
  for (let x = 0; x <= W + 12; x += 12) g.lineTo(x, ridgeY(x));
  g.lineTo(W + 12, H);
  g.closePath();
  g.fill();

  /* 草脊的受光边：沿脊线走一条 2.5px 的浅金线。
     参考概念图里草地和远山交界处有一条被夕阳打亮的边 —— 就这一条线，
     把"两块色板拼接"变成了"一个坡顶"。alpha 只给 0.55（在 grassLight 上），
     再往上就是描边，会读成"贴了一条金丝"。
     往下压 1.2px：压在脊线的**内侧**，露出来的是草地自身的亮面。 */
  g.strokeStyle = rgbaOf(TH.grassLight, 0.55);
  g.lineWidth = 2.5;
  g.beginPath();
  for (let x = 0; x <= W + 12; x += 12) {
    const y = ridgeY(x) + 1.2;
    if (x === 0) g.moveTo(x, y); else g.lineTo(x, y);
  }
  g.stroke();

  // 地面上的浅色条纹：给"深度"，但只在低对比度下出现。
  // 已经有三档明度了，条纹只是补充；alpha 从 0.07 收到 0.05，
  // 否则每一道都是一条"横在战场上的白线"。
  g.globalAlpha = 0.05;
  g.fillStyle = "#FFFFFF";
  for (let i = 0; i < 5; i++) {
    const y = 352 + i * 48;
    g.beginPath();
    g.ellipse(W / 2, y, 460 - i * 30, 10 + i * 2, 0, 0, 6.283);
    g.fill();
  }
  g.globalAlpha = 1;

  /* 草面纹理：一撮撮小草，越靠下越大越密。
     没有这一层，300~556 是一整片纯渐变 —— 那是"一张绿色纸"的最后一块证据，
     也是"像贴上去"最直白的一条：真实的一整片草地里找不到一块干净的平面。
     一撮只画两根细弧，不做叶片造型 —— 草地上有 90 撮，
     每一撮都画清楚反而会读成"一片尖刺"。
     尺寸 / 线宽 / 透明度三样都随 y 递增（近大远小），这一层的纵深就出来了。 */
  for (let i = 0; i < 90; i++) {
    const tx = hash(i * 13.7) * W;
    const ty = ridgeY(tx) + 26 + Math.pow(hash(i * 7.9), 0.72) * 246;
    if (ty > 558) continue;
    const k = clamp((ty - 300) / 256, 0, 1);          // 0 = 远，1 = 近
    const s = 2 + k * 4.5;
    g.strokeStyle = rgbaOf(TH.grassDark, 0.10 + k * 0.13);
    g.lineWidth = 1.1 + k * 0.9;
    g.lineCap = "round";
    g.beginPath();
    g.moveTo(tx - s * 0.7, ty);
    g.quadraticCurveTo(tx - s * 0.4, ty - s * 1.3, tx, ty - s * 1.75);
    g.moveTo(tx + s * 0.7, ty);
    g.quadraticCurveTo(tx + s * 0.4, ty - s * 1.05, tx, ty - s * 1.5);
    g.stroke();
  }

  /* 树高统一乘这个系数。
   *
   * 表里的 sc 是"相对基准树"的比例，基准树（sc=1）高 60+27×1.9 ≈ 111px。
   * 乘 1.5 之后，最高的那棵 ≈ 167px = 屏高的 28%，加上草脊的位置，
   * 树冠顶到 y≈150 —— 正好落在最上层平台（248）之上、HUD（90）之下。
   *
   * 为什么必须放大：原来最高的树只有 111px = 屏高 18%，
   * 十五棵排开读作"草地上散着几棵小树"，而不是"战斗发生在一片林子的空地上"。
   * 概念图里中景树占到屏高一半 —— 背景的体量感直接来自这个比例，
   * 不是来自细节画得多不多。 */
  const TREE_SCALE = 1.5;

  /* 更远的一排树（第二道树线）：**专门用来填前排的缝**。
     只有一排树的时候，每棵树之间露出天空和草地，读作"草地上散着几棵蘑菇"——
     间距再随机也救不了，因为"稀疏"本身就是问题。
     后排尺寸只有前排的 40%~55%、贴着草脊站、颜色再往雾里推一档，
     它不负责造型，只负责把"树后面还有树"这件事画出来。
     这一层是概念图和当前实现差别最大的地方：概念图的背景是一**片**林，不是几棵树。 */
  const FAR_TREES = [
    [  12, 0.30, 0.16], [  62, 0.38, 0.24], [ 116, 0.26, 0.14],
    [ 176, 0.34, 0.20], [ 240, 0.28, 0.14], [ 306, 0.36, 0.22],
    [ 368, 0.25, 0.12], [ 442, 0.34, 0.20], [ 508, 0.30, 0.16],
    [ 578, 0.38, 0.24], [ 646, 0.26, 0.14], [ 706, 0.34, 0.18],
    [ 768, 0.30, 0.16], [ 830, 0.36, 0.22], [ 896, 0.27, 0.12],
  ];
  for (const [fx, fsc, fd] of FAR_TREES) {
    // 贴着草脊站（+3 让树干底边压进草皮 3px，不然会浮在脊线上面）
    drawTree(g, fx, ridgeY(fx) + 3, fsc * TREE_SCALE, true, fd);
  }

  /* 中景树：**三档深度 + 允许互相遮挡**。
     上一版 9 棵等距 118px、同一档尺寸（0.54~0.82）、同一条基线（308~320）——
     等距 + 等高 + 等大，三条凑齐就是"平"的定义，拍出来是一条墙纸条带。

     深度的唯一可靠线索是**遮挡**：一棵压住另一棵的边缘，眼睛才认为它在前面。
     所以这里刻意让相邻两棵重叠 20%~40%，间距 42~84 不等，尺寸分三档
     （0.44 / 0.66 / 0.94），基线按 depth 递进（越近越往下）。
     depth 同时喂给 drawTree 的 dim —— 越远的越往地平线雾色里混。
     格式：[x, 尺寸, depth] */
  const MID_TREES = [
    [  26, 0.62, 0.60], [  84, 0.42, 0.34], [ 138, 0.76, 0.80],
    [ 214, 0.48, 0.42], [ 272, 0.58, 0.56], [ 340, 0.40, 0.28],
    [ 396, 0.70, 0.74], [ 474, 0.46, 0.38], [ 532, 0.78, 0.82],
    [ 612, 0.52, 0.46], [ 672, 0.64, 0.64], [ 742, 0.44, 0.34],
    [ 800, 0.74, 0.78], [ 862, 0.50, 0.42], [ 930, 0.60, 0.58],
  ];
  for (const [tx, tsc, td] of MID_TREES) {
    /* 基线 = 草脊 + 一个和 depth 成正比的小位移。
       越近越靠下 —— 这是"从低角度看一片平地"时唯一成立的规律；
       少了它，树再大也贴在同一个平面上。
       **位移只给 12px，不能给 30。** 试过 30：树干会整根落到草脊以下，
       十五根立在草地前面、间距又均匀，读作"一排栅栏"。
       树必须**扎在脊线上**，深度靠尺寸和颜色差别的，不靠把树往下挪。
       **夹到 334**：350 那层平台从 350 起，树根扎进去就开始读作
       "战斗发生在树上"（之前踩过一次，六棵树画在战场背后）。 */
    const by = Math.min(334, ridgeY(tx) + 2 + td * 12);
    drawTree(g, tx, by, tsc * TREE_SCALE, true, td);
  }

  /* 树脚雾：草脊那一条上贴一层薄雾，把树根"化"进地面。
     **只能是贴着草脊的一条薄带（26px 高、alpha .14）。**
     第一版写成 48px 高、alpha .30，覆盖了树干下半截 —— 出来是
     "树干被拦腰切了一刀"，因为空气透视是**按距离**累积的，不是按高度。
     同一棵树的上半截和下半截离镜头一样远，凭什么下半截更雾？
     所以这一层只负责"地面和树根之间没有硬边界"，不负责纵深；
     纵深交给 drawTree 的 dim。 */
  const fog = g.createLinearGradient(0, 296, 0, 322);
  fog.addColorStop(0, rgbaOf(TH.horizon, 0.14));
  fog.addColorStop(1, rgbaOf(TH.horizon, 0));
  g.fillStyle = fog;
  g.fillRect(0, 296, W, 26);

  /* 两侧近景树：**一侧一棵**。
     原来是 "1.9 + 1.3" 两棵并排 —— 两个 blob 各自描边，描边在中间交叉，
     拍出来读作"两个球叠在一起"，是全场最像"没画完"的地方。
     blobPath 只能描自己的整圈，没有"只描并集外轮廓"的 API（canvas 不给），
     所以并排的两棵树要么合并成一个 blob，要么就别并排。选后者。 */
  drawTree(g, 6, 470, 1.9, false);
  drawTree(g, W - 8, 470, 1.9, false);

  // 空气里的浮尘：小圆点，向上飘。数量少、对比低
  for (let i = 0; i < 16; i++) {
    const ph = (S.t * 0.22 + hash(i * 7.7)) % 1;
    const x = 60 + hash(i * 2.3) * (W - 120) + Math.sin(S.t * 0.6 + i) * 10;
    const y = 520 - ph * 380;
    g.globalAlpha = 0.20 * (1 - Math.abs(ph - 0.5) * 2);
    g.fillStyle = "#FFFFFF";
    g.beginPath();
    g.arc(x, y, 1.6 + hash(i) * 1.8, 0, 6.283);
    g.fill();
    g.globalAlpha = 1;
  }

  // 顶部渐晕：只收掉过曝，不染色。0.22 的时候顶部被漂成灰白，
  // 整片天空的最高点反而比中段暗 —— 读作"天上盖了块脏玻璃"。
  const top = g.createLinearGradient(0, 0, 0, 40);
  top.addColorStop(0, "rgba(255,255,255,.10)");
  top.addColorStop(1, "rgba(255,255,255,0)");
  g.fillStyle = top;
  g.fillRect(0, 0, W, 40);

  if (world) {
    g.save();
    g.translate(0, 0);
    g.restore();
  }
}

/* ============================================================================
   14. 绘制：关卡
   ========================================================================== */

/* 平台体积参数 —— 浮空台和斜坡共用同一组数，"厚度吻合"就靠这个。
   之前斜坡用 26、浮空台用 h+6（18~26 之间浮动），两块接在一起永远差几像素，
   肉眼读出来的就是"拼上去的"。 */
const PLAT_TOP = 7;    // 顶面：俯视能看到的窄面带
/* 视觉总厚（从物理顶面 p.y 往下量）。
 *
 * **33 → 27 是用户一句"比较粗大了点"量出来的，不是审美偏好。**
 * 屏高 600，33 占 5.5%；参考概念图里圆木直径只占屏高 4%（= 24）。
 * 取 27 = 4.5%，是"细一档但仍然是根木头"的位置：
 *   再往下到 24 会读成"一块板"（层缝就没有高度可放了，3 层挤不进 8px）；
 *   再往上到 30 就回到"粗大"，和参考图差得太远。
 * 27 = 3 × 9，每层 9px —— 刚好够一条层缝(3.4) + 一个年轮(5.6)，
 * LAYER_SHIFT 的错缝语义不变。 */
const PLAT_TK  = 27;

/* 平台由几层木板叠成。27 / 3 = 9，每层刚好够放一条层缝 + 一个年轮。
   改这个数就要同步看 LAYER_SHIFT —— 层数是"错缝"的唯一来源。 */
const LAYERS = 3;
/* 每层拼缝的水平偏移。**必须互不相同且不成倍数**，否则三层缝会在
   某些 x 上重合，一眼就看出是"同一根线复制了三遍"。 */
const LAYER_SHIFT = [0, 16, 32];

/** 某个平台端点是不是接了斜坡。端点用 (x, 顶面 y) 表示。
 *
 *  接坡的那一端要"开口"：不做圆角、不描竖边，让坡的轮廓接管。
 *  否则平台整圈描边会横穿接缝，成了一道黑竖线。 */
function rampMating(x, y, tol) {
  const T = tol === undefined ? 3 : tol;
  for (const r of RAMPS) {
    if (Math.abs(r.x - x) < T && Math.abs(r.yL - y) < T) return { r, end: "L" };
    if (Math.abs(r.x + r.w - x) < T && Math.abs(r.yR - y) < T) return { r, end: "R" };
  }
  return null;
}

/** 圆角矩形路径，但两端可以单独做成直角（flatL / flatR）。
 *  填充用完整路径；描边分上下两段调用，接缝端才不会封口。 */
function platPath(g, x, y, w, h, r, flatL, flatR) {
  const k = Math.min(r, w / 2, h / 2);
  g.beginPath();
  if (flatL) g.moveTo(x, y);
  else { g.moveTo(x, y + k); g.quadraticCurveTo(x, y, x + k, y); }
  if (flatR) g.lineTo(x + w, y);
  else { g.lineTo(x + w - k, y); g.quadraticCurveTo(x + w, y, x + w, y + k); }
  if (flatR) g.lineTo(x + w, y + h);
  else { g.lineTo(x + w, y + h - k); g.quadraticCurveTo(x + w, y + h, x + w - k, y + h); }
  if (flatL) g.lineTo(x, y + h);
  else { g.lineTo(x + k, y + h); g.quadraticCurveTo(x, y + h, x, y + h - k); }
  g.closePath();
}

function drawPlat(g, p) {
  const isGround = p.kind === "ground";

  if (isGround) {
    // ---- 地面：泥土块 + 一层圆齿草皮。草齿是圆的，这是 Q 版和写实的唯一分界线
    const dg = g.createLinearGradient(0, p.y, 0, p.y + p.h + 26);
    dg.addColorStop(0, TH.dirt);
    dg.addColorStop(1, TH.dirt2);
    g.fillStyle = dg;
    g.fillRect(p.x, p.y, p.w, p.h + 26);

    // 土里的石子：几颗深色圆点，固定位置
    g.fillStyle = "rgba(0,0,0,.14)";
    for (let i = 0, x = p.x + 20; x < p.x + p.w - 16; i++, x += 62) {
      const o = hash(i + 31);
      g.beginPath();
      g.ellipse(x + o * 18, p.y + 16 + o * 20, 4 + o * 4, 3 + o * 3, 0, 0, 6.283);
      g.fill();
    }

    // 草皮底
    g.fillStyle = TH.grass2;
    g.beginPath();
    g.moveTo(p.x, p.y + 6);
    g.lineTo(p.x, p.y - 4);
    for (let x = p.x, i = 0; x <= p.x + p.w; i++, x += 22) {
      g.arc(x + 11, p.y - 4, 12, Math.PI, 0);
    }
    g.lineTo(p.x + p.w, p.y + 6);
    g.closePath();
    g.fill();

    // 草皮亮面
    g.fillStyle = TH.grass;
    g.beginPath();
    g.moveTo(p.x, p.y + 2);
    g.lineTo(p.x, p.y - 6);
    for (let x = p.x, i = 0; x <= p.x + p.w; i++, x += 26) {
      g.arc(x + 13, p.y - 6, 12, Math.PI, 0);
    }
    g.lineTo(p.x + p.w, p.y + 2);
    g.closePath();
    g.fill();

    // 草皮顶部深描边：只描上缘，不封边（封边会像贴纸框）
    g.strokeStyle = "rgba(24,58,34,.32)";
    g.lineWidth = 2;
    g.beginPath();
    g.moveTo(p.x, p.y - 4);
    for (let x = p.x, i = 0; x <= p.x + p.w; i++, x += 22) {
      g.arc(x + 11, p.y - 4, 12, Math.PI, 0);
    }
    g.stroke();

    // 草尖：三两根，稀疏
    g.strokeStyle = "rgba(40,110,52,.35)";
    g.lineWidth = 2;
    g.lineCap = "round";
    for (let i = 0, x = p.x + 14; x < p.x + p.w; i++, x += 74) {
      const hh = 5 + hash(i + 7) * 5;
      g.beginPath();
      g.moveTo(x, p.y - 7);
      g.quadraticCurveTo(x + 3, p.y - 7 - hh, x + 6, p.y - 7);
      g.stroke();
    }
    return;
  }

  // ---- 浮空台：一块有厚度的圆角木台
  // Q 版 2D 平台的正解是"一块砖"，不是"顶面 + 立面的伪 3D"。
  // 厚度由三件事建立：底部暗带、外轮廓、落在背景上的影子。
  const TOP = 6;
  const TK  = PLAT_TK;
  const R   = 11;

  // **接坡的那一端要开口**：不做圆角、不描竖边。
  // 整圈描边压在斜坡上，接缝处就是一条贯穿厚度的黑竖线 ——
  // 那条线是"两根木头对接"的全部证据，去掉它，台面才真的"弯了下去"。
  const flatL = !!rampMating(p.x, p.y);
  const flatR = !!rampMating(p.x + p.w, p.y);
  const openL = flatL ? 0 : 1;     // 1 = 这一端是真正的台头，要圆角 + 年轮
  const openR = flatR ? 0 : 1;

  // ① 影子：远影（落在背景/地面上）+ 贴地 AO。没有影子，平台就是贴纸
  const shX = p.x + (openL ? 8 : 0);
  const shW = p.w - (openL ? 8 : 0) - (openR ? 8 : 0);
  // 远影压在下面更远、更扁：距离感就是"影子和物体的间距"。
  g.fillStyle = "rgba(14,38,24,.22)";
  rr(g, shX, p.y + 20, shW, TK - 2, R + 2);
  g.fill();
  g.fillStyle = "rgba(14,38,24,.16)";
  rr(g, p.x + 2, p.y + TK - 6, p.w - 4, 12, 6);
  g.fill();

  // ② 主体：一块整体渐变（顶亮 → 中调 → 底暗）
  const bg = g.createLinearGradient(0, p.y, 0, p.y + TK);
  bg.addColorStop(0, TH.wood3);
  bg.addColorStop(0.12, TH.wood);
  bg.addColorStop(0.72, TH.wood);
  bg.addColorStop(1, TH.wood2);
  g.fillStyle = bg;
  platPath(g, p.x, p.y, p.w, TK, R, flatL, flatR);
  g.fill();

  // ③ 分层：一块台 = 3 层木板叠起来（33 / 3 = 11）。
  //    用户对上一版的判断是"像画出来的"——病根在这里：整块 33px 只有一条渐变
  //    和几道等距竖缝，读作"一块长了纹路的板"，不像木匠搭出来的东西。
  //    真实堆叠木板的证据只有三条：**层缝（水平暗线）、错缝（上下拼缝不对齐）、
  //    端头一层一个年轮**。三条都在，才读得作"叠"。
  //    外轮廓仍然整圈一体的（下面 ④），所以不会散成三块飞板。
  g.save();
  platPath(g, p.x, p.y, p.w, TK, R, flatL, flatR);
  g.clip();

  const LH = TK / LAYERS;
  // 顶部亮带：最上一层木板的受光面，比下面的层顶更宽更亮（天光直射）
  g.fillStyle = "rgba(255,255,255,.20)";
  g.fillRect(p.x, p.y, p.w, TOP);
  g.fillStyle = "rgba(255,255,255,.46)";
  g.fillRect(p.x, p.y, p.w, 2);
  // 底部暗带：厚度的"终点"
  g.fillStyle = "rgba(40,22,10,.30)";
  g.fillRect(p.x, p.y + TK - 6, p.w, 6);

  for (let L = 0; L < LAYERS; L++) {
    const y0 = p.y + L * LH;

    if (L > 0) {
      // 层缝：上面一条细亮边（下层木板的受光）、下面一条暗缝。
      // 只画暗线不画亮边，缝会读成"一条裂纹"；两条一起才是"两块板搭着"。
      g.fillStyle = "rgba(255,255,255,.30)";
      g.fillRect(p.x, y0, p.w, 1.8);
      g.fillStyle = "rgba(34,18,8,.34)";
      g.fillRect(p.x, y0 + 1.8, p.w, 1.6);
    }

    // 每层自己的底边暗收：这一层才是一个独立的"块"，
    // 否则三条层缝只是把一块木头切了三刀。
    g.fillStyle = "rgba(34,18,8,.15)";
    g.fillRect(p.x, y0 + LH - 2.2, p.w, 2.2);

    // 拼缝：**错缝**铺。三层错开 0 / 16 / 32，
    // 对齐的话读作"一根根栅栏"，错开才读作"木匠随手叠的"。
    const sh = LAYER_SHIFT[L % LAYER_SHIFT.length];
    g.strokeStyle = "rgba(52,30,16,.24)";
    g.lineWidth = 1.2;
    for (let x = p.x + 40 + sh; x < p.x + p.w - 26; x += 48) {
      g.beginPath();
      g.moveTo(x, y0 + 2.4);
      g.lineTo(x, y0 + LH - 3);
      g.stroke();
    }
  }

  // 端面：**只画真正的台头**。接坡那一端画年轮会读成"木头被锯断后再接上一块"。
  // 年轮改成一层一个（原来一个占满 33px 高的椭圆，等于又把它读成一根整木）。
  const ends = [];
  if (openL) ends.push(p.x);
  if (openR) ends.push(p.x + p.w - 13);
  for (const ex of ends) {
    g.fillStyle = "rgba(40,22,10,.13)";
    g.fillRect(ex, p.y, 13, TK);
    const cx = ex + 6.5;
    g.strokeStyle = "rgba(60,34,16,.24)";
    g.lineWidth = 1;
    for (let L = 0; L < LAYERS; L++) {
      const cy = p.y + L * LH + LH / 2;
      for (let k = 0; k < 2; k++) {
        g.beginPath();
        g.ellipse(cx, cy, 1.7, LH * 0.30 - k * 1.7, 0, 0, 6.283);
        g.stroke();
      }
    }
  }
  g.restore();

  // ④ 外轮廓：上下各描一段，接坡端不封口。
  //    整圈描边（rr + stroke）会 closePath，把接缝那道竖线画出来。
  g.strokeStyle = COL.outline;
  g.lineWidth = 2.6;
  g.lineJoin = "round";

  // 上缘：左上 → 右上
  g.beginPath();
  if (flatL) g.moveTo(p.x, p.y);
  else { g.moveTo(p.x, p.y + R); g.quadraticCurveTo(p.x, p.y, p.x + R, p.y); }
  if (flatR) g.lineTo(p.x + p.w, p.y);
  else { g.lineTo(p.x + p.w - R, p.y); g.quadraticCurveTo(p.x + p.w, p.y, p.x + p.w, p.y + R); }
  g.stroke();

  // 下缘：右下 → 左下
  g.beginPath();
  if (flatR) g.moveTo(p.x + p.w, p.y + TK);
  else { g.moveTo(p.x + p.w, p.y + TK - R); g.quadraticCurveTo(p.x + p.w, p.y + TK, p.x + p.w - R, p.y + TK); }
  if (flatL) g.lineTo(p.x, p.y + TK);
  else { g.lineTo(p.x + R, p.y + TK); g.quadraticCurveTo(p.x, p.y + TK, p.x, p.y + TK - R); }
  g.stroke();

  // 没接坡的端头补那条竖边（圆角之间的直段）
  if (openL) {
    g.beginPath();
    g.moveTo(p.x, p.y + R);
    g.lineTo(p.x, p.y + TK - R);
    g.stroke();
  }
  if (openR) {
    g.beginPath();
    g.moveTo(p.x + p.w, p.y + R);
    g.lineTo(p.x + p.w, p.y + TK - R);
    g.stroke();
  }
}

function drawPit(g, pit) {
  const x = pit.x, y = pit.y, w = pit.w;

  if (pit.kind === "fire") {
    // 凹陷的坑
    g.fillStyle = "#2A1A12";
    g.beginPath();
    g.moveTo(x, y);
    g.lineTo(x + 16, y + 26);
    g.lineTo(x + w - 16, y + 26);
    g.lineTo(x + w, y);
    g.closePath();
    g.fill();

    // 底部余烬
    const em = g.createRadialGradient(x + w / 2, y + 22, 4, x + w / 2, y + 22, w * 0.55);
    em.addColorStop(0, "rgba(255,120,30,.85)");
    em.addColorStop(1, "rgba(255,80,10,0)");
    g.fillStyle = em;
    g.fillRect(x, y, w, 30);

    // 火苗：用 S.t 做确定性动画
    for (let i = 0; i < 7; i++) {
      const fx = x + 14 + (i / 6) * (w - 28);
      const ph = S.t * 7 + i * 1.9;
      const hgt = 22 + Math.sin(ph) * 12 + Math.sin(ph * 2.3) * 6;
      const grd = g.createLinearGradient(fx, y + 6, fx, y + 6 - hgt);
      grd.addColorStop(0, "rgba(255,90,20,.95)");
      grd.addColorStop(0.55, "rgba(255,190,60,.85)");
      grd.addColorStop(1, "rgba(255,255,190,0)");
      g.fillStyle = grd;
      g.beginPath();
      g.moveTo(fx - 7, y + 8);
      g.quadraticCurveTo(fx - 3, y + 4 - hgt * 0.6, fx, y + 6 - hgt);
      g.quadraticCurveTo(fx + 3, y + 4 - hgt * 0.6, fx + 7, y + 8);
      g.closePath();
      g.fill();
    }

    // 边缘焦土
    g.strokeStyle = "rgba(40,24,14,.8)";
    g.lineWidth = 3;
    g.beginPath();
    g.moveTo(x, y); g.lineTo(x + 16, y + 26);
    g.moveTo(x + w, y); g.lineTo(x + w - 16, y + 26);
    g.stroke();
    return;
  }

  if (pit.kind === "water") {
    // 水面比坑口低一截，读起来才像"能沉下去"
    g.fillStyle = "#22323C";
    g.beginPath();
    g.moveTo(x, y);
    g.lineTo(x + 14, y + 24);
    g.lineTo(x + w - 14, y + 24);
    g.lineTo(x + w, y);
    g.closePath();
    g.fill();

    const wg = g.createLinearGradient(x, y + 2, x, y + 24);
    wg.addColorStop(0, "rgba(120,206,236,.95)");
    wg.addColorStop(1, "rgba(34,92,124,.96)");
    g.fillStyle = wg;
    g.beginPath();
    g.moveTo(x + 4, y + 2);
    g.lineTo(x + 16, y + 21);
    g.lineTo(x + w - 16, y + 21);
    g.lineTo(x + w - 4, y + 2);
    g.closePath();
    g.fill();

    // 两条随时间平移的亮带 —— 别的坑都在动，水面不动会被当成地板
    for (let i = 0; i < 3; i++) {
      const ph = (S.t * 0.55 + i * 0.34) % 1;
      g.globalAlpha = 0.55 * (1 - Math.abs(ph - 0.5) * 2);
      g.fillStyle = "#DCF6FF";
      g.beginPath();
      g.ellipse(x + 20 + ph * (w - 46), y + 9 + i * 5, 16, 2.1, 0, 0, 6.283);
      g.fill();
      g.globalAlpha = 1;
    }
    g.strokeStyle = "rgba(28,56,68,.85)";
    g.lineWidth = 3;
    g.beginPath();
    g.moveTo(x, y); g.lineTo(x + 14, y + 24);
    g.moveTo(x + w, y); g.lineTo(x + w - 14, y + 24);
    g.stroke();
    return;
  }

  // 泥坑
  g.fillStyle = COL.mud;
  g.beginPath();
  g.moveTo(x, y);
  g.lineTo(x + 14, y + 20);
  g.lineTo(x + w - 14, y + 20);
  g.lineTo(x + w, y);
  g.closePath();
  g.fill();
  g.fillStyle = "rgba(30,22,14,.6)";
  g.beginPath();
  g.ellipse(x + w / 2, y + 12, w * 0.38, 8, 0, 0, 6.283);
  g.fill();

  // 气泡
  for (let i = 0; i < 4; i++) {
    const bx = x + 20 + i * (w - 40) / 3;
    const ph = (S.t * 0.9 + i * 0.7) % 1;
    g.globalAlpha = 1 - ph;
    g.fillStyle = "#7A6242";
    g.beginPath();
    g.arc(bx, y + 14 - ph * 14, 2 + ph * 4, 0, 6.283);
    g.fill();
    g.globalAlpha = 1;
  }
  g.strokeStyle = "rgba(50,36,22,.85)";
  g.lineWidth = 3;
  g.beginPath();
  g.moveTo(x, y); g.lineTo(x + 14, y + 20);
  g.moveTo(x + w, y); g.lineTo(x + w - 14, y + 20);
  g.stroke();
}

/* ---------- 斜坡 ---------- */
function drawRamp(g, r) {
  // ---- 一条弯下去的路
  // 关键：厚度**垂直于路面**量，不是竖直量。
  // 竖直量的话，45° 的坡看起来只有平路的 70% 厚 —— 这就是"斜的比横的薄"。
  // 平台是水平的（垂直厚度 = 竖直厚度 = PLAT_TK），坡用同一个垂直厚度，
  // 竖直投影自动放大 1/cosθ，两块接在一起才真的"厚度吻合"。
  /* 栈道面厚度。
   *
   * **21 是"坡不能堵"量出来的。** 整条坡在最长的一关是 494 长，
   * 厚度 27 就等于 13000 平方像素的实色横在屏幕中间 —— 它把背景挡完了，
   * 背景再有层次也看不见，这就是用户说的"太堵"。
   * 收到 21（-22%）之后体量明显下去，但仍然是"一根木头"，不是"一张纸"。
   *
   * **接头处必须是 PLAT_TK，往前走 18% 行程才收到 21。**
   * 不做这个渐变，台面和坡的下缘会差 6px，接缝处出现一个看得见的台阶缺口
   * —— 那正是上一版花大力气消灭掉的"两根木头对接"。
   * 顺带白拿一点透视：越往下越薄。
   */
  const RAMP_TK = 21;
  const TOP = 6;
  const N   = 48;                // 采样点取密，弯的地方才没有折线感
  const x1 = r.x, x2 = r.x + r.w;

  // 接平台那一端水平往外伸一截，塞到台面底下（平台后画，会盖住）。
  // **只伸高端** —— 低端伸出去会悬空，球在肉眼看得到的坡上却踩不到东西。
  const highLeft = r.yL <= r.yR;
  const EXT = 26;
  const xa = highLeft ? x1 - EXT : x1;
  const xb = highLeft ? x2 : x2 + EXT;

  const yAt = (x) => rampSurfY(r, x);
  const xAt = (i) => xa + (xb - xa) * (i / N);

  // 坡度 → 竖直厚度系数：垂直厚度 t 对应的竖直偏移 = t·√(1+m²)
  const slopeAt = (x) => (yAt(x + 2) - yAt(x - 2)) / 4;
  const vk = (x) => Math.sqrt(1 + slopeAt(x) * slopeAt(x));
  const off = (x, t) => t * vk(x);

  /* 某一点的栈道面厚度。s 从**高的一端**量起 —— 高的一端接台面，要吻合。 */
  const tkAt = (x) => {
    let s = clamp((x - x1) / r.w, 0, 1);
    if (!highLeft) s = 1 - s;
    const k = clamp(s / 0.18, 0, 1);
    return PLAT_TK + (RAMP_TK - PLAT_TK) * k;
  };

  const yA = yAt(xa), yB = yAt(xb);
  const yTop = Math.min(yA, yB);
  const yBot = Math.max(yA, yB) + PLAT_TK * 1.7;

  // 沿曲线切一条带：上沿 / 下沿都可以是常数或 (x) => 竖直偏移
  const band = (topFn, botFn) => {
    const tv = (x) => (typeof topFn === "function" ? topFn(x) : topFn);
    const bv = (x) => (typeof botFn === "function" ? botFn(x) : botFn);
    g.beginPath();
    for (let i = 0; i <= N; i++) {
      const x = xAt(i);
      const y = yAt(x) + tv(x);
      if (i === 0) g.moveTo(x, y); else g.lineTo(x, y);
    }
    for (let i = N; i >= 0; i--) {
      const x = xAt(i);
      g.lineTo(x, yAt(x) + bv(x));
    }
    g.closePath();
  };

  // ① 环境遮蔽：贴着栈道底面的一条薄暗带。
  //    厚度收窄到 11（原来是 13~46 的一大条），alpha .16 → .13 ——
  //    它的职责已经从"影子"降级成"底面有厚度"，不再参与构图。
  g.fillStyle = "rgba(16,42,28,.13)";
  band((x) => off(x, 5), (x) => off(x, tkAt(x) + 10));
  g.fill();

  // ② 主体
  const bg = g.createLinearGradient(0, yTop, 0, yBot);
  bg.addColorStop(0, TH.wood3);
  bg.addColorStop(0.12, TH.wood);
  bg.addColorStop(0.72, TH.wood);
  bg.addColorStop(1, TH.wood2);
  g.fillStyle = bg;
  band(0, (x) => off(x, tkAt(x)));
  g.fill();

  // ③ 顶带 / 层缝 / 底带 / 拼缝，全部 clip 在路面里
  g.save();
  band(0, (x) => off(x, tkAt(x)));
  g.clip();

  // 顶带跟着曲线走 —— 这是"路"和"管子"的分界线：
  // 管子是均匀截面，路有一条明确的受光面。
  g.fillStyle = "rgba(255,255,255,.20)";
  band(0, TOP);
  g.fill();
  g.fillStyle = "rgba(255,255,255,.46)";
  band(0, 2);
  g.fill();
  g.fillStyle = "rgba(40,22,10,.30)";
  band((x) => off(x, tkAt(x)) - 5, (x) => off(x, tkAt(x)));
  g.fill();

  /* 分层：和浮空台同一套（3 层，层缝在 t = TK·⅓、TK·⅔）。
     **层缝必须沿曲线画**。用 fillRect 画水平线，在 40° 的坡上会直接穿出路面 ——
     这是"坡"和"台阶"最容易被写混的一处：台阶的缝是水平的，坡的缝平行于路面。
     厚度现在是 tkAt(x) 变的，所以层缝位置也得跟着变，不能再用常数。 */
  for (let L = 1; L < LAYERS; L++) {
    const f = L / LAYERS;
    g.fillStyle = "rgba(255,255,255,.30)";
    band((x) => off(x, tkAt(x) * f), (x) => off(x, tkAt(x) * f) + 1.8);
    g.fill();
    g.fillStyle = "rgba(34,18,8,.34)";
    band((x) => off(x, tkAt(x) * f) + 1.8, (x) => off(x, tkAt(x) * f) + 3.4);
    g.fill();
  }
  for (let L = 1; L <= LAYERS; L++) {
    const f = L / LAYERS;
    g.fillStyle = "rgba(34,18,8,.15)";
    band((x) => off(x, tkAt(x) * f) - 2.2, (x) => off(x, tkAt(x) * f));
    g.fill();
  }

  // 拼缝：每层一段，三层错开。贯穿全厚的竖线读作"一根木条"，
  // 分段错开才读作"几块板搭在坡上"。
  g.strokeStyle = "rgba(52,30,16,.24)";
  g.lineWidth = 1.2;
  for (let L = 0; L < LAYERS; L++) {
    const sh = LAYER_SHIFT[L % LAYER_SHIFT.length];
    for (let x = x1 + 26 + sh; x < x2 - 16; x += 48) {
      const y = yAt(x), tk = tkAt(x);
      const t0 = tk * (L / LAYERS) + 2.2;
      const t1 = tk * ((L + 1) / LAYERS) - 2.6;
      if (t1 <= t0 + 0.6) continue;     // 薄段放不下一道缝就跳过，别画成一条黑点
      g.beginPath();
      g.moveTo(x, y + off(x, t0));
      g.lineTo(x, y + off(x, t1));
      g.stroke();
    }
  }
  g.restore();

  /* ③b 短支腿 —— **这是"不堵"的关键，不是装饰。**
   *
   * 参考概念图里的栈道是「薄板 + 稀疏支腿 + 底下透空」。
   * 透空这件事有两个作用，缺一不可：
   *   ① 视觉体量直接砍掉一半 —— 实心厚板挡住的那 20~30px 背景回来了；
   *   ② 支腿给出了「这块板浮在地面之上」的唯一证据。
   *      没有它，一条薄板在 2D 里会读成"画在背景上的一条线"，
   *      反而比厚板更像贴纸。
   *
   * **支腿不落地。** 最长那一关坡顶离地 206px，落地就是战场中间竖一排栅栏，
   * 球道会被切成格子（可读性事故）。只出 18px 的短腿，读作"架起来的"就够 ——
   * 观众不需要知道它架在什么上，这是 Q 版卡通的默认豁免。 */
  const LEGS = [0.26, 0.46, 0.66, 0.84];
  for (const s of LEGS) {
    const bx = x1 + r.w * s;
    const byTop = yAt(bx) + off(bx, tkAt(bx));
    const lw = 7, lh = 18;
    g.fillStyle = TH.wood2;
    rr(g, bx - lw / 2, byTop - 3, lw, lh, 2.5);
    g.fill();
    // 斜撑：往上坡方向斜伸一根短木，给出"支"的方向
    g.strokeStyle = COL.outline;
    g.lineWidth = 1.8;
    g.lineJoin = "round";
    g.beginPath();
    g.moveTo(bx - lw / 2 + 1, byTop + 4);
    g.lineTo(bx - lw / 2 - 9, byTop - 6);
    g.stroke();
    // 腿的轮廓：左、下、右三边（上边被栈道面盖住，不描）
    g.lineWidth = 2;
    g.beginPath();
    g.moveTo(bx - lw / 2, byTop);
    g.lineTo(bx - lw / 2, byTop + lh - 2.5);
    g.quadraticCurveTo(bx, byTop + lh + 1.5, bx + lw / 2, byTop + lh - 2.5);
    g.lineTo(bx + lw / 2, byTop);
    g.stroke();
  }

  // ④ 外轮廓：上缘、下缘各描一条，**不闭合**。
  //    闭合就会在接平台那一端画出一道竖边，正好压在平台端头上 ——
  //    接缝处那条黑线，一半来自平台整圈描边，另一半来自这里。
  const joinsL = !!rampMating(r.x, r.yL);
  const joinsR = !!rampMating(r.x + r.w, r.yR);
  // 悬空端要封口（读作"桥到头了"）；落地端被草皮盖住，不封。
  const openL = !joinsL && r.yL < GROUND_Y - 6;
  const openR = !joinsR && r.yR < GROUND_Y - 6;

  g.strokeStyle = COL.outline;
  g.lineWidth = 2.6;
  g.lineJoin = "round";
  g.lineCap = "round";

  // 上缘
  g.beginPath();
  for (let i = 0; i <= N; i++) {
    const x = x1 + (x2 - x1) * (i / N);
    const y = yAt(x);
    if (i === 0) g.moveTo(x, y); else g.lineTo(x, y);
  }
  g.stroke();

  // 下缘
  g.beginPath();
  for (let i = 0; i <= N; i++) {
    const x = x1 + (x2 - x1) * (i / N);
    const y = yAt(x) + off(x, tkAt(x));
    if (i === 0) g.moveTo(x, y); else g.lineTo(x, y);
  }
  g.stroke();

  // 悬空端封口
  if (openL) {
    g.beginPath();
    g.moveTo(x1, yAt(x1));
    g.lineTo(x1, yAt(x1) + off(x1, tkAt(x1)));
    g.stroke();
  }
  if (openR) {
    g.beginPath();
    g.moveTo(x2, yAt(x2));
    g.lineTo(x2, yAt(x2) + off(x2, tkAt(x2)));
    g.stroke();
  }
}

/* ---------- 弹簧菇 ---------- */
function drawBouncer(g, b) {
  const ph = Math.sin(S.t * 4.4 + b.x * 0.02);
  const squash = 1 + ph * 0.10;
  const top = b.y - 30;
  const bw = 30 * (1 / squash), bh = 22 * squash;

  // 影子
  g.fillStyle = "rgba(20,40,26,.22)";
  g.beginPath();
  g.ellipse(b.x, b.y + 2, 26, 6, 0, 0, 6.283);
  g.fill();

  // 柄
  g.fillStyle = "#E8E0C2";
  g.beginPath();
  rr(g, b.x - 6, top + bh * 0.5, 12, b.y - top - bh * 0.5 - 2, 5);
  g.fill();

  // 伞
  const capG = g.createLinearGradient(b.x, top, b.x, top + bh);
  capG.addColorStop(0, "#FF9A7A");
  capG.addColorStop(1, "#D9463F");
  g.fillStyle = capG;
  g.beginPath();
  g.ellipse(b.x, top + bh * 0.55, bw, bh * 0.72, 0, Math.PI, 0);
  g.fill();
  g.fillStyle = "#FFC6A8";
  g.beginPath();
  g.ellipse(b.x, top + bh * 0.55, bw, 4.5, 0, 0, 6.283);
  g.fill();

  // 伞上的白点
  g.fillStyle = "rgba(255,246,200,.92)";
  for (const dx of [-14, 0, 14]) {
    g.beginPath();
    g.arc(b.x + dx, top + bh * 0.34 - Math.abs(dx) * 0.18, 3.2, 0, 6.283);
    g.fill();
  }
  g.strokeStyle = "rgba(40,64,36,.5)";
  g.lineWidth = 2;
  g.beginPath();
  g.ellipse(b.x, top + bh * 0.55, bw, bh * 0.72, 0, Math.PI, 0);
  g.stroke();
}

/* ---------- 传送洞 ---------- */
function drawPortal(g, pt) {
  const cy = pt.y - 16;
  // 洞
  g.fillStyle = "#101C26";
  g.beginPath();
  g.ellipse(pt.x, pt.y - 6, 28, 11, 0, 0, 6.283);
  g.fill();
  const pg = g.createRadialGradient(pt.x, pt.y - 6, 2, pt.x, pt.y - 6, 30);
  pg.addColorStop(0, "rgba(120,236,255,.95)");
  pg.addColorStop(0.55, "rgba(46,150,196,.55)");
  pg.addColorStop(1, "rgba(20,60,90,0)");
  g.fillStyle = pg;
  g.beginPath();
  g.ellipse(pt.x, pt.y - 6, 30, 13, 0, 0, 6.283);
  g.fill();

  // 三圈旋转的光环：静止的洞会被当成装饰
  for (let i = 0; i < 3; i++) {
    const k = ((S.t * 0.8 + i / 3) % 1);
    g.globalAlpha = 0.55 * (1 - k);
    g.strokeStyle = i % 2 ? "#9FE4FF" : "#D8F8FF";
    g.lineWidth = 2;
    g.beginPath();
    g.ellipse(pt.x, pt.y - 6, 10 + k * 22, (10 + k * 22) * 0.42, 0, 0, 6.283);
    g.stroke();
    g.globalAlpha = 1;
  }

  // 洞里飘起来的小火星
  for (let i = 0; i < 3; i++) {
    const k = ((S.t * 0.5 + i / 3) % 1);
    g.globalAlpha = 0.8 * (1 - k);
    g.fillStyle = "#BFF0FF";
    g.beginPath();
    g.arc(pt.x + Math.sin(S.t * 2 + i) * 12, cy - k * 26, 2.2, 0, 6.283);
    g.fill();
    g.globalAlpha = 1;
  }
}

function drawStump(g, s) {
  if (s.hp <= 0) {
    // 只剩个桩子印
    g.fillStyle = "rgba(70,50,32,.5)";
    g.beginPath();
    g.ellipse(s.x, s.y - 2, s.w * 0.55, 6, 0, 0, 6.283);
    g.fill();
    return;
  }
  const sx = s.x + (s.shake > 0 ? Math.sin(S.t * 60) * 3 : 0);
  const top = s.y - s.h;

  // 木桩用主题木色。原来写死 #6B4A2E / #4A3220 / #9A7048 ——
  // 第八关是紫夜关，插一根棕色柱子在紫色草地上，是全场最刺眼的一处"外来物"。
  g.fillStyle = TH.wood2;
  rr(g, sx - s.w / 2, top + 5, s.w, s.h - 5, 8);
  g.fill();
  g.strokeStyle = COL.ink;
  g.lineWidth = 3.2;
  g.stroke();

  // 树皮竖纹
  g.strokeStyle = "rgba(44,28,16,.32)";
  g.lineWidth = 1.4;
  for (let i = -1; i <= 1; i++) {
    g.beginPath();
    g.moveTo(sx + i * 12, top + 12);
    g.lineTo(sx + i * 12, s.y - 4);
    g.stroke();
  }

  // 顶面切口：有它才读得出"这是被锯断的树"，没它就只是根棕色柱子
  g.fillStyle = TH.wood3;
  g.beginPath();
  g.ellipse(sx, top + 5, s.w / 2, 8, 0, 0, 6.283);
  g.fill();
  g.strokeStyle = COL.ink;
  g.lineWidth = 2.6;
  g.stroke();
  g.strokeStyle = rgbaOf(TH.wood2, 0.55);
  g.lineWidth = 1.3;
  for (let i = 1; i <= 3; i++) {
    g.beginPath();
    g.ellipse(sx, top + 5, s.w * 0.14 * i, 2.6 * i, 0, 0, 6.283);
    g.stroke();
  }

  // 裂纹：hp 掉一层就裂一道，玩家能看出"再来一下就碎"
  if (s.hp <= 1) {
    g.strokeStyle = "rgba(30,18,10,.85)";
    g.lineWidth = 2;
    g.beginPath();
    g.moveTo(sx - 6, top + 14);
    g.lineTo(sx + 2, top + 34);
    g.lineTo(sx - 4, top + 52);
    g.stroke();
  }
}

function drawCamp(g) {
  const x = CAMP.x, w = CAMP.w, y = CAMP.y;
  // 草窝
  g.fillStyle = "rgba(90,66,38,.55)";
  g.beginPath();
  g.ellipse(x + w / 2, y - 4, w / 2, 12, 0, 0, 6.283);
  g.fill();

  // 编筐
  g.fillStyle = COL.camp;
  rr(g, x + 8, y - 46, w - 16, 42, 10);
  g.fill();
  g.strokeStyle = "#8A6430";
  g.lineWidth = 2;
  g.stroke();
  g.strokeStyle = "rgba(120,86,40,.55)";
  g.lineWidth = 1.4;
  for (let i = 1; i < 4; i++) {
    g.beginPath();
    g.moveTo(x + 8, y - 46 + i * 10.5);
    g.lineTo(x + w - 8, y - 46 + i * 10.5);
    g.stroke();
  }

  // 顶上的叶子
  g.fillStyle = "#4E9B54";
  for (let i = -2; i <= 2; i++) {
    g.beginPath();
    g.ellipse(x + w / 2 + i * 12, y - 52, 13, 6, i * 0.32, 0, 6.283);
    g.fill();
  }

  // "落袋"指示：轻轻闪
  g.globalAlpha = 0.5 + Math.sin(S.t * 3) * 0.25;
  g.fillStyle = "#FFE08A";
  g.font = "bold 13px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
  g.textAlign = "center";
  g.textBaseline = "middle";
  g.fillText("营地", x + w / 2, y - 66);
  g.globalAlpha = 1;
}

function drawLevel() {
  const g = ctx;
  // 顺序有讲究，三层各管一件事：
  //   ① 坡先画 → ② 地面盖上去（坡脚正好被草皮吃掉，不留一个"悬空的断头"）
  //   → ③ 浮空台最后画（坡顶那 26px 伸进台面里，被台面盖住 = 读成"路从台面延伸下来"）
  // 上一版是"地面 → 坡 → 台面"：坡脚压在草上，露出一截朝下的方头，
  // 看上去就是"木头架完没收拾"。把地面挪到坡后面就干净了。
  for (const r of RAMPS) drawRamp(g, r);
  for (const p of PLATS) if (p.kind === "ground") drawPlat(g, p);
  for (const pit of PITS) drawPit(g, pit);
  drawCamp(g);
  for (const p of PLATS) if (p.kind !== "ground") drawPlat(g, p);
  for (const b of BOUNCERS) drawBouncer(g, b);
  for (const pt of PORTALS) drawPortal(g, pt);
  for (const s of S.stumps) drawStump(g, s);
}

/* 前景灌木：画面最底边一排压暗的剪影。
 *
 * 为什么需要这一层：现在天空、远山、树、草地、平台、角色全挂在同一个对比度上，
 * 排在一起读作"一张插画上面摆了角色"。真实镜头里最近处一定有一层被压暗、
 * 只留剪影的东西挡着画面下缘 —— 纵深就是靠"远淡 / 中实 / 近暗"这三档拉开的。
 *
 * 高度死线：顶端不得高于 GROUND_Y + 14（= 570）。
 * 地面行走的视觉带一点都不能占，否则玩家分不清"球是落地了还是被草挡住了"。
 * 这条死线写进算式（cy 按 r 反推），不靠调参运气。
 */
function drawForeground(g) {
  const base = TH.shrub || TH.grass;
  const lit = TH.shrubLit || base;
  const DEAD = GROUND_Y - 4;       // 552：盖住草皮鼓包，只淹掉球底 4px
  /* 9 丛。上一版 11 丛 × 5 根细叶，每丛体量比球还小 —— 用户原话是
     "灌木大点 自然很多"。剪影层的说服力靠**体量**，不靠丛数：
     9 丛做得大，下沿才是"几丛灌木挡着镜头"，不是"地上插了一排草"。 */
  /* 丛的位置**写死，不均分**。
     均分（i/(N-1)）会让每一丛落在等距位置上，中段必然压住火坑 / 营地 ——
     那是玩法目标，被前景吃掉之后玩家找不到该往哪儿推（实测第 1 关火坑被盖掉一半）。
     所以丛集中在两侧，中段 0.30~0.70 留空，视线和球道从中间穿过。 */
  const SPOTS = [0.065, 0.185, 0.305, 0.695, 0.815, 0.935];
  const N = SPOTS.length;

  for (let i = 0; i < N; i++) {
    const t = SPOTS[i];

    /* 两侧抬高的上限是 **62**。
       这个数是从碰撞几何反推的，不是随口调：462 层台面底边在 482，
       顶到 490 还留 8px 余量。再高就直接盖住"能站的地方"，
       那是可读性事故，不是构图。
       幂次 2.2（不是 1.5）：抬高只发生在最外侧那几丛，靠里的保持贴地，
       否则六丛连成一条等高齿条。 */
    const edge = Math.abs(t - 0.5) * 2;
    const lift = Math.pow(edge, 2.2) * 62;

    const r = 50 + hash(i * 3.7) * 28 + edge * 24;          // 50 ~ 102：一丛的半宽
    /* x 用 t × W 直接取，**不加外扩**。
       上一版是 -56 + t×(W+112)：最外那丛的中心落在 -23，整个人在屏幕外，
       只剩几片叶子伸进来 —— 拍出来底部"只有几根草"，看不出有一丛灌木。 */
    const x = t * W + (hash(i * 4.7) - 0.5) * 34;
    /* 顶端**故意不等高**：随机幅度放到 30px。
       原来所有丛都贴 552 线，拍出来是一排锯齿齿条；
       真实的一排灌木是错落的，高的挡住矮的。 */
    const top = DEAD - lift + hash(i * 5.3) * 30 - 8;
    const cy = top + r * 0.86;                              // 团心

    /* ① 底座 —— 低矮的暗团，只负责"这块地方是实心的"，不负责造型。
       上一版让团占满整个轮廓（0.82r 半径），拍出来是"一个绿色圆丘上面插了几根尖"，
       读作石头或土包。**造型交给叶子，团只垫底。** */
    g.fillStyle = base;
    blobPath(g, x, cy + r * 0.76, r * 0.86, i * 1.7 + 0.4);
    g.fill();
    blobPath(g, x - r * 0.68, cy + r * 0.60, r * 0.60, i * 3.1 + 1.6);
    g.fill();
    blobPath(g, x + r * 0.72, cy + r * 0.56, r * 0.56, i * 4.9 + 2.8);
    g.fill();

    /* ② 叶子 —— **一丛的主体是 12 片宽叶，不是那个团。**
       叶宽按长度算（bw = len × 0.34），长叶细一点、短叶宽一点。
       试过三档都不对：写死宽度 + 长度差 0.5 倍 → 灰绿色的铲子；
       bw = len×0.20 的细长叶 → "几根草"；只有 7 片 → 叶间漏出地面，
       读作"几片叶子插在地上"，不读作一丛灌木。密到 12 片，缝才被填上。
       叶根也不许在同一水平线上：从同一点放射出去就是海胆，
       根部高度按 hash 错开 0.4r，才是"从团里长出来"。 */
    for (let k = 0; k < 12; k++) {
      const spread = ((k + 0.5) / 12 - 0.5) * 1.86;         // -0.93 ~ 0.93
      const ang = spread * 1.05 - 0.10;                     // 整体略偏左，跟着光源
      const len = r * (0.48 + hash(i * 7.3 + k * 3.1) * 0.62);
      const rootX = x + spread * r * 0.70;
      const rootY = cy + r * (0.04 + hash(i * 5.9 + k * 1.7) * 0.38);
      const tipX = rootX + Math.sin(ang) * len * 1.35;
      /* 夹到 top 上：叶尖越线就戳到球道，玩家会读成"球卡在草里了"。 */
      const tipY = Math.max(top - 1, rootY - len * Math.cos(ang));
      const cosA = Math.cos(ang), sinA = Math.sin(ang);
      const bw = len * 0.34;
      const midX = (rootX + tipX) / 2, midY = (rootY + tipY) / 2;
      g.fillStyle = hash(i * 4.1 + k * 1.9) > 0.42 ? lit : base;
      g.beginPath();
      g.moveTo(rootX, rootY);
      g.quadraticCurveTo(midX - cosA * bw, midY + sinA * bw, tipX, tipY);
      g.quadraticCurveTo(midX + cosA * bw, midY - sinA * bw, rootX, rootY);
      g.closePath();
      g.fill();
    }
  }

  // 再压一道从底边往上 34px 的暗角，把"镜头下沿"收住。
  const vg = g.createLinearGradient(0, H - 40, 0, H);
  vg.addColorStop(0, "rgba(10,24,18,0)");
  vg.addColorStop(1, "rgba(10,24,18,.34)");
  g.fillStyle = vg;
  g.fillRect(0, H - 40, W, 40);
}

/* ============================================================================
   15. 绘制：单位
   ========================================================================== */

/**
 * 眼睛。
 * mouth: true = 笑 / "flat" = 一条直嘴 / "down" = 撇下去
 * droop: 0..1，眼皮下垂。**用"眼睛变扁 + 下压"来表达，不用皮肤色去盖** ——
 *        盖眼皮需要知道身体色，而这个函数在 HUD 头像里也被调（那里没有身体色参数）。
 */
function drawEyes(g, x, y, gap, r, face, mouth, droop) {
  const dr = droop || 0;
  const eh = r * (1 - dr * 0.52);
  const ey = y + dr * r * 0.22;
  g.fillStyle = COL.ink;
  g.beginPath();
  g.ellipse(x - gap, ey, r, eh, 0, 0, 6.283);
  g.ellipse(x + gap, ey, r, eh, 0, 0, 6.283);
  g.fill();
  g.fillStyle = "#FFFFFF";
  g.beginPath();
  g.ellipse(x - gap + face * 1.2, ey - eh * 0.4, r * 0.38, eh * 0.40, 0, 0, 6.283);
  g.ellipse(x + gap + face * 1.2, ey - eh * 0.4, r * 0.38, eh * 0.40, 0, 0, 6.283);
  g.fill();
  if (mouth) {
    g.strokeStyle = COL.ink;
    g.lineWidth = 1.6;
    g.beginPath();
    if (mouth === "down") {
      g.arc(x, y + r * 2.9, r * 1.0, Math.PI + 0.5, -0.5);
    } else if (mouth === "flat") {
      g.moveTo(x - r * 1.1, y + r * 2.3);
      g.lineTo(x + r * 1.1, y + r * 2.3);
    } else {
      g.arc(x, y + r * 1.9, r * 0.9, 0.2, Math.PI - 0.2);
    }
    g.stroke();
  }
}

/** 宠物：一个通用体 + 耳朵/尾巴变体。形状圆、描边厚，卡通第一原则 */
function drawPet(g, x, footY, w, h, H, face, o) {
  o = o || {};
  // 整体透明度。**必须由画的人传进来**：这个函数据内部会反复改 globalAlpha
  // （影子 0.18、受击闪白、眼睛高光），外面设一次 globalAlpha 会被它清掉。
  // 门口"影狐隐进阴影"就是踩过这个坑 —— 设了 0.2，画出来还是全不透明。
  const A = o.alpha === undefined ? 1 : o.alpha;

  // 有美术立绘就贴图（只有进 Cocos 才有），否则走下面这一整套代码图形。
  // 碰撞体始终是 w×h，贴图只改绘制，手感不变。
  const art = artOf("pet-" + H.id);
  if (art) { drawPetSprite(g, art, x, footY, w, h, face, A, o, H.id); return; }

  const sq = o.squash || 0;
  const bw = w * (1 + sq * 0.16);
  const bh = h * (1 - sq * 0.14);
  const cy = footY - bh * 0.5;

  // 影子
  g.globalAlpha = 0.18 * A;
  g.fillStyle = "#16261C";
  g.beginPath();
  g.ellipse(x, footY + 2, bw * 0.44, 5, 0, 0, 6.283);
  g.fill();
  g.globalAlpha = 1 * A;

  // 尾巴（画在身体后）
  g.fillStyle = H.c3;
  if (H.ears === "cat") {
    g.strokeStyle = H.c3;
    g.lineWidth = 6;
    g.lineCap = "round";
    g.beginPath();
    g.moveTo(x - face * bw * 0.38, cy + bh * 0.12);
    g.quadraticCurveTo(x - face * bw * 0.78, cy + bh * 0.02, x - face * bw * 0.66, cy - bh * 0.26);
    g.stroke();
  } else if (H.ears === "fox") {
    g.beginPath();
    g.moveTo(x - face * bw * 0.3, cy + bh * 0.16);
    g.quadraticCurveTo(x - face * bw * 0.9, cy + bh * 0.2, x - face * bw * 0.86, cy - bh * 0.16);
    g.quadraticCurveTo(x - face * bw * 0.6, cy + bh * 0.02, x - face * bw * 0.3, cy + bh * 0.16);
    g.fill();
  } else if (H.ears === "dog") {
    g.strokeStyle = H.c3;
    g.lineWidth = 5;
    g.lineCap = "round";
    g.beginPath();
    g.moveTo(x - face * bw * 0.4, cy + bh * 0.1);
    g.quadraticCurveTo(x - face * bw * 0.66, cy - bh * 0.1, x - face * bw * 0.5, cy - bh * 0.22);
    g.stroke();
  }

  // 身体
  g.fillStyle = H.c1;
  rr(g, x - bw / 2, footY - bh, bw, bh, Math.min(bw, bh) * 0.42);
  g.fill();
  g.strokeStyle = COL.outline;
  g.lineWidth = 2.4;
  g.stroke();

  // 肚皮。belly 1 = 吃饱（撑出来）/ 0 = 饿扁。
  // 这是"饿"唯一不靠 UI 的表达：一只猫瘦了，玩家不需要读那个数字。
  const belly = o.belly === undefined ? 1 : o.belly;
  g.fillStyle = H.c2;
  g.beginPath();
  g.ellipse(x + face * bw * 0.05, footY - bh * 0.34,
            bw * (0.18 + 0.08 * belly), bh * (0.12 + 0.10 * belly), 0, 0, 6.283);
  g.fill();
  // 饿扁时补两道瘪纹。只把肚皮改小，在 40px 的角色上根本读不出来
  if (belly < 0.55) {
    g.strokeStyle = H.c3;
    g.lineWidth = 1.7;
    g.globalAlpha = 0.62 * A;
    for (let i = 0; i < 2; i++) {
      const yy = footY - bh * (0.24 + i * 0.12);
      g.beginPath();
      g.moveTo(x - bw * 0.15, yy);
      g.quadraticCurveTo(x, yy + 2.6, x + bw * 0.15, yy);
      g.stroke();
    }
    g.globalAlpha = 1 * A;
  }

  // 耳朵
  g.fillStyle = H.c1;
  g.strokeStyle = COL.outline;
  g.lineWidth = 2.2;
  const ey = footY - bh;
  if (H.ears === "cat") {
    for (const s of [-1, 1]) {
      g.beginPath();
      g.moveTo(x + s * bw * 0.30, ey + 4);
      g.lineTo(x + s * bw * 0.40, ey - 15);
      g.lineTo(x + s * bw * 0.10, ey - 2);
      g.closePath();
      g.fill();
      g.stroke();
    }
  } else if (H.ears === "rab") {
    for (const s of [-1, 1]) {
      g.beginPath();
      g.ellipse(x + s * bw * 0.22, ey - 16, 6, 18, s * 0.16, 0, 6.283);
      g.fill();
      g.stroke();
    }
  } else if (H.ears === "dog") {
    for (const s of [-1, 1]) {
      g.beginPath();
      g.ellipse(x + s * bw * 0.38, ey + 6, 7, 12, s * 0.5, 0, 6.283);
      g.fill();
      g.stroke();
    }
  } else if (H.ears === "ox") {
    for (const s of [-1, 1]) {
      g.beginPath();
      g.moveTo(x + s * bw * 0.34, ey + 6);
      g.quadraticCurveTo(x + s * bw * 0.62, ey - 4, x + s * bw * 0.56, ey - 12);
      g.lineWidth = 5;
      g.strokeStyle = "#E8EEF4";
      g.stroke();
      g.lineWidth = 2.2;
      g.strokeStyle = COL.outline;
    }
  } else if (H.ears === "ham") {
    for (const s of [-1, 1]) {
      g.beginPath();
      g.arc(x + s * bw * 0.32, ey + 5, 8, 0, 6.283);
      g.fill();
      g.stroke();
    }
  } else if (H.ears === "fox") {
    for (const s of [-1, 1]) {
      g.beginPath();
      g.moveTo(x + s * bw * 0.32, ey + 3);
      g.lineTo(x + s * bw * 0.44, ey - 17);
      g.lineTo(x + s * bw * 0.06, ey - 1);
      g.closePath();
      g.fill();
      g.stroke();
    }
  }

  // 脸。mood 0 = 正常 / 1 = 丧。眼睛压扁 + 嘴撇下去，两处一起改才读得出来
  const mood = o.mood || 0;
  drawEyes(g, x + face * 2, footY - bh * 0.62, bw * 0.17, 3.2, face,
           mood > 0.5 ? "down" : (belly < 0.35 ? "flat" : true), mood * 0.85);

  // 鼻子
  g.fillStyle = "#E0708A";
  g.beginPath();
  g.ellipse(x + face * bw * 0.04, footY - bh * 0.50, 3, 2.2, 0, 0, 6.283);
  g.fill();

  // 没有立绘时的迈步：身体还是那个圆角矩形，两条腿从髋部对摆。
  // 腿画在身体之后，脚才会伸到轮廓外面 —— 缩在身体里等于没画。
  if (o.stepping) {
    const s = Math.sin(o.gait || 0) * bw * 0.62;
    g.strokeStyle = H.c3;
    g.lineWidth = Math.max(2.4, bw * 0.09);
    g.lineCap = "round";
    const hip = footY - bh * 0.28;
    g.beginPath();
    g.moveTo(x - face * bw * 0.10, hip);
    g.lineTo(x - face * bw * 0.10 + s, footY + 1);
    g.moveTo(x + face * bw * 0.18, hip);
    g.lineTo(x + face * bw * 0.18 - s, footY + 1);
    g.stroke();
  }

  // 出手瞬间的挤压
  if (o.flash > 0) {
    g.globalAlpha = o.flash * 0.7 * A;
    g.fillStyle = "#FFFFFF";
    rr(g, x - bw / 2, footY - bh, bw, bh, Math.min(bw, bh) * 0.42);
    g.fill();
    g.globalAlpha = 1 * A;
  }
}

/* ----------------------------------------------------------------------------
   贴美术立绘（只有进 Cocos 注入了图才会走到这里，见文件顶部的 ART）

   三件事和代码图形不一样，必须按图处理：
     ① 宽高比：立绘是 409×640 这种竖长的，硬按 w 画会把猫压成方的 ——
        所以按**高度**等比，宽度反推。
     ② 落脚点：立绘的脚在图片底边，所以底边对齐 footY。
     ③ 朝向：美术只画了一张（正面偏右），往左走靠 scale(-1,1) 镜像。

   画出来多高只看 PET_VIS_K（见下方）：立绘按体高缩放，不是按碰撞盒原样贴。
   -------------------------------------------------------------------------- */
/** 立绘的"体高 / 图高"。
 *
 *  美术管道（tools/prep_pets.py）出的六张是**统一体高**的：图高 640，
 *  脚底到头顶（不含耳朵）占 420，其余是耳朵和留白。420 / 640 = 0.656。
 *
 *  这个数只在两个地方出现：prep_pets.py 的 BODY_H / PET_H，和这里。
 *  改美术管道就要同步改 —— 不然六只的角色会集体变大或变小，
 *  而且因为六只一起变，单看画面很难发现，只有跟小怪并排才露馅。 */
const PET_BODY_K = 0.656;

/** 视觉体高 / 碰撞高。
 *
 *  **这个数是场景比例的唯一旋钮，改它等于改"宠物在画面里多大"。**
 *  画出来的图高 = 碰撞高 × PET_VIS_K / PET_BODY_K。
 *
 *  硬约束不是概念图，是两层平台之间的空：
 *    地面脚底 556，上一层台面 462，中间 94px；
 *    木板从台面往下画 33px（PLAT_TK），真正能站人的空气只剩 61px。
 *    立绘比 61px 高，头顶就插进上一层木板里。
 *
 *  走过的值，别再按"球直径 88"调回去 —— 那是量错的。
 *  普通球半径 22、直径 44（88 是 BOSS 球的直径）。
 *    1.82 / 1.60 → 猫的图高 107px，比空气缝还高 46px，头在木板里面。
 *    0.78 → 猫的图高 53px，身体和 44px 的球同一量级，头顶离木板还有空。
 *           老实牛碰撞最高（52），图高约 62px，刚好贴着缝的上沿。 */
const PET_VIS_K = 0.78;

/** 站立图上前后腿的切法。原图都朝左，split 左侧是前腿。
 *  hip 是髋在图高上的位置（0 = 图顶，1 = 脚底）。数字是对着六张立绘的
 *  不透明像素量的：再往上切会把肚子切进腿里，再往下切只剩脚尖。 */
const WALK_CUT = {
  cat: { hip: 0.87, split: 0.54 },
  dog: { hip: 0.90, split: 0.55 },
  fox: { hip: 0.87, split: 0.48 },
  ham: { hip: 0.93, split: 0.55 },
  ox:  { hip: 0.84, split: 0.55 },
  rab: { hip: 0.88, split: 0.52 },
};

function drawPetSprite(g, img, x, footY, w, h, face, A, o, id) {
  // 影子：和代码图形同一套，贴地
  g.globalAlpha = 0.18 * A;
  g.fillStyle = "#16261C";
  g.beginPath();
  g.ellipse(x, footY + 2, w * 0.44, 5, 0, 0, 6.283);
  g.fill();

  const sq = o.squash || 0;
  /* dh 按**体高**算，不是按图高。
   *
   * 六张立绘是美术管道统一出来的：图高 640，其中体高（脚底到头顶）只占 420，
   * 顶上那 220 是耳朵和留给耳朵的留白。直接 `h * 1.35` 等于按图高缩，
   * 画出来身体只有该有的 65.6% —— 换图那天六只集体缩水三分之一，
   * 站在小怪旁边像只幼崽。 */
  const dh = h * PET_VIS_K / PET_BODY_K * (1 - sq * 0.14);
  const dw = dh * ((img.width || img.naturalWidth) / (img.height || img.naturalHeight)) * (1 + sq * 0.16);

  g.globalAlpha = 1 * A;
  g.save();
  g.translate(x, footY);
  /* 翻转判据是 **face > 0**，不是 face < 0。
   *
   * 立绘原图（pet-*.png）是朝**左**的：尾巴在画面左侧、身体朝左前侧。
   * 上一版写 `face < 0` 翻转，于是向右走/向右施法时贴的是原图 = 朝左，
   * 向左时反而被翻成朝右 —— 正好全反。玩家看到的就是"右施法、脸朝左"。
   *
   * 这条约束的前提是**六张立绘都朝左**。以后美术换图，先确认朝向再动这里，
   * 混着来会出现"猫朝右、狗朝左"这种一队人方向不一致的情况。 */
  if (face > 0) g.scale(-1, 1);
  // 出手闪白：代码图形是盖一层白矩形；贴图改提亮度，只作用于不透明像素，
  // 不会在角色周围留一个白框。浏览器不支持 filter 时赋值被忽略，不报错。
  //
  // 系数 0.8 不是 1.8。1.8 的时候 brightness 到 1.72，橙色猫直接被提成白猫 ——
  // 截图里看就是"换了只宠物"。闪白只该让人注意到"它在出手"，不该改颜色。
  if (o.flash > 0) g.filter = "brightness(" + (1 + o.flash * 0.8).toFixed(2) + ")";

  const cut = o.stepping && WALK_CUT[id];
  if (!cut) {
    g.drawImage(img, -dw / 2, -dh, dw, dh);
    g.restore();
    g.globalAlpha = 1;
    return;
  }

  /* 走路姿势：同一张站立图切三块。
   *   后腿、身体、前腿，绕髋关节对摆。身体反方向轻轻前倾。
   * 不做整只上下蹦 —— 那读成跳。脚离地是腿在转，身子的脚点不动。
   * 裁切发生在旋转之后的同一套坐标里，转出去的脚不会被切掉。 */
  const hipY = -dh * (1 - cut.hip);
  const xL = -dw / 2;
  const xR = dw / 2;
  const split = xL + dw * cut.split;
  const swing = Math.sin(o.gait || 0) * 0.95;
  const rock = Math.sin(o.gait || 0) * 0.10;
  const yTop = hipY - 2;
  const legH = 8 - yTop;

  function part(x0, y0, rw, rh, rot, px, py) {
    g.save();
    g.translate(px, py);
    g.rotate(rot);
    g.translate(-px, -py);
    g.beginPath();
    g.rect(x0, y0, rw, rh);
    g.clip();
    g.drawImage(img, xL, -dh, dw, dh);
    g.restore();
  }

  part(split - 3, yTop, xR - split + 8, legH, swing, (split + xR) / 2, hipY);
  // 身体只压过髋线 3px。再往下会把站立的脚也画出来，和摆出去的腿叠成两双脚。
  part(xL - 4, -dh - 8, dw + 8, hipY + 3 - (-dh - 8), -rock, 0, hipY);
  part(xL - 6, yTop, split - xL + 8, legH, -swing, (xL + split) / 2, hipY);

  g.restore();
  g.globalAlpha = 1;
}

/* ----------------------------------------------------------------------------
   BOSS 的外形：紫身体 + 两只角 + 白描边。要一眼看出"这是这关最大的东西"，
   靠的是尺寸和角，不是颜色 —— 颜色在八套主题里都会变。
   -------------------------------------------------------------------------- */
function drawBoss(g, f) {
  const cx = f.x, cy = f.y - f.h / 2;
  const bw = f.w, bh = f.h;
  const squash = f.hitT > 0 ? f.hitT / 0.20 : 0;
  const br = 1 + Math.sin(f.bob * 1.6) * 0.018;
  // 砸地抬手：整个身体先往上抬一点，再砸下来
  const lift = f.slamming > 0.35 ? -22 * Math.sin((1.15 - f.slamming) * 2.0) : 0;
  // 产卵：肚子鼓；吸气：整个身子缩一下。两个动作方向相反，玩家一眼分得清
  const breed = f.breeding > 0 ? Math.sin((0.9 - f.breeding) * 3.6) : 0;
  const suck = f.spitting > 0 ? Math.sin((0.72 - f.spitting) * 4.4) : 0;
  const OUT = COL.outline;

  g.globalAlpha = 0.22;
  g.fillStyle = "#1A1224";
  g.beginPath(); g.ellipse(cx, f.y + 3, bw * 0.44, 8, 0, 0, 6.283); g.fill();
  g.globalAlpha = 1;

  g.save();
  g.translate(cx, cy + lift);
  g.scale((1 + squash * 0.14 + breed * 0.07) * br, (1 - squash * 0.12 - suck * 0.05) * br);
  g.save();
  // 只画朝右的版本，靠镜像翻面
  g.scale(f.face, 1);

  /* ---- 六条腿：先粗深色当描边，再细亮色当腿本身 ----
     单画一条线的话，在红棕身体上会糊成"一坨影子" */
  // 腿必须**伸到身体轮廓外面**才看得见。缩在身下的话，
  // 无论画多粗都会被鞘翅整个盖住 —— 那就变成了"一个没有腿的球"。
  const gait = Math.sin(f.bob * 4.2) * 4;
  const legs = [];
  for (let i = 0; i < 3; i++) {
    const lx = -bw * 0.26 + i * bw * 0.23;
    const ph = i % 2 ? gait : -gait;
    for (const sd of [-1, 1]) {
      legs.push([lx, bh * 0.12, lx + sd * 30 + ph, bh * 0.30, lx + sd * 34 + ph, bh * 0.50]);
    }
  }
  for (const [x0, y0, qx, qy, x2, y2] of legs) {
    g.strokeStyle = "#3A1A12"; g.lineWidth = 10; g.lineCap = "round";
    g.beginPath(); g.moveTo(x0, y0); g.quadraticCurveTo(qx, qy, x2, y2); g.stroke();
  }
  for (const [x0, y0, qx, qy, x2, y2] of legs) {
    g.strokeStyle = "#8E3A2A"; g.lineWidth = 4.5;
    g.beginPath(); g.moveTo(x0, y0); g.quadraticCurveTo(qx, qy, x2, y2); g.stroke();
  }

  /* ---- 触角：两根带球的须，虫子的第一识别特征 ---- */
  g.strokeStyle = "#3A1A12";
  g.lineWidth = 5;
  g.lineCap = "round";
  for (const sd of [-1, 1]) {
    const ex = bw * 0.42 + sd * 16, ey = -bh * 0.54;
    g.beginPath();
    g.moveTo(bw * 0.16 + sd * 6, -bh * 0.34);
    g.quadraticCurveTo(bw * 0.28 + sd * 14, -bh * 0.60, ex, ey);
    g.stroke();
    g.fillStyle = "#F2DFA8";
    g.beginPath(); g.arc(ex, ey, 5.5, 0, 6.283); g.fill();
    g.strokeStyle = OUT; g.lineWidth = 2; g.stroke();
    g.lineWidth = 5;
  }

  /* ---- 鞘翅（身体） ---- */
  const body = g.createLinearGradient(0, -bh * 0.50, 0, bh * 0.46);
  body.addColorStop(0, "#F0906A");
  body.addColorStop(0.42, "#D4664A");
  body.addColorStop(1, "#8E3A2A");
  g.fillStyle = body;
  g.beginPath(); g.ellipse(0, -bh * 0.02, bw * 0.48, bh * 0.44, 0, 0, 6.283); g.fill();
  g.strokeStyle = OUT; g.lineWidth = 3.6; g.stroke();

  // 背脊中缝：一块圆的红身体和"甲虫"的区别就在这条线
  g.strokeStyle = "rgba(64,22,14,.50)";
  g.lineWidth = 3;
  g.beginPath();
  g.moveTo(bw * 0.04, -bh * 0.42);
  g.quadraticCurveTo(bw * 0.10, -bh * 0.02, bw * 0.03, bh * 0.40);
  g.stroke();

  // 鞘翅上的斑点
  g.fillStyle = "#7A2A1E";
  for (const [sx, sy, r] of [[-bw * 0.22, -bh * 0.24, 0.095],
                             [-bw * 0.34, -bh * 0.10, 0.062],
                             [-bw * 0.10, bh * 0.02, 0.055]]) {
    g.beginPath();
    g.ellipse(sx, sy, bw * r, bw * r * 0.86, 0, 0, 6.283);
    g.fill();
  }
  // 背部高光：一个亮弧，读起来是"壳"，不是"皮"
  g.strokeStyle = "rgba(255,224,200,.42)";
  g.lineWidth = 5;
  g.lineCap = "round";
  g.beginPath();
  g.arc(0, -bh * 0.06, bw * 0.34, -2.5, -1.1);
  g.stroke();

  /* ---- 头 ---- */
  const hx = bw * 0.36, hy = bh * 0.10;
  g.fillStyle = "#C2563E";
  g.beginPath(); g.ellipse(hx, hy, bw * 0.20, bh * 0.19, 0, 0, 6.283); g.fill();
  g.strokeStyle = OUT; g.lineWidth = 3.2; g.stroke();

  // 嘴：吐弹时张开（配合 f.spitting）
  const jaw = f.spitting > 0 ? 1 : 0;
  g.fillStyle = "#3A1410";
  g.beginPath();
  g.ellipse(hx + bw * 0.10, hy + bh * 0.05, bw * 0.06, bh * (0.03 + jaw * 0.05), 0, 0, 6.283);
  g.fill();

  // 大颚：两片象牙色的钩子
  // 大颚：两片象牙色的钳子。要粗、要外张 —— 它是这张脸上唯一的"凶"信号，
  // 画细了就成了两根牙签。
  g.fillStyle = "#F7EAC0";
  g.strokeStyle = OUT;
  g.lineWidth = 3.4;
  g.lineJoin = "round";
  for (const sd of [-1, 1]) {
    g.beginPath();
    g.moveTo(hx + bw * 0.06, hy + sd * 6);
    g.quadraticCurveTo(hx + bw * 0.34, hy + sd * 10, hx + bw * 0.30, hy + sd * 26);
    g.quadraticCurveTo(hx + bw * 0.22, hy + sd * 14, hx + bw * 0.02, hy + sd * 13);
    g.closePath();
    g.fill();
    g.stroke();
  }

  drawCuteEyes(g, hx - bw * 0.02, hy - bh * 0.03, 7.5, 8.5, false);

  /* ---- 苔藓层：糊了几层就贴几块，颜色递进 —— 这是唯一的"进度"反馈。
     只贴下半身：贴到脸上会把眼睛和嘴糊住，玩家就读不出"它举起来了"，
     砸地那一下的抬手是他唯一需要读的动作。 ---- */
  const cm = f.cm || 3;
  for (let i = 0; i < f.coat; i++) {
    const tt = f.coat === 1 ? 0.5 : i / (f.coat - 1);
    // 只贴**后半身**（左下 → 左上）。原来从 0.14π 开始贴，第一块正落在头的下面，
    // 读起来像"嘴里吐出来的绿球"，而且把大颚挡住了。
    // 打散：整齐排成一列会变成"背上一串葡萄"，看不出是"壳被糊住了"
    const ang = Math.PI * (0.56 + 0.68 * tt) + Math.sin(i * 3.7) * 0.22;
    const ring = 0.56 + ((i * 7) % 3) * 0.15;
    const mx = Math.cos(ang) * bw * 0.46 * ring;
    const my = bh * 0.02 + Math.sin(ang) * bh * 0.44 * ring;
    const sr = 12 + ((i * 5) % 3) * 3;
    g.globalAlpha = 0.85;
    g.fillStyle = i % 2 ? "#8FD35A" : "#6FBF46";
    g.beginPath(); g.ellipse(mx, my, sr + 3, sr, ang, 0, 6.283); g.fill();
    g.strokeStyle = OUT; g.lineWidth = 1.6; g.stroke();
    g.globalAlpha = 1;
  }

  g.restore();
  g.restore();
}

/** BOSS 的粘液弹：拖尾 + 高光。飞得快，没有拖尾就是"飘着的绿点" */
function drawFoeShots(g) {
  for (const s of S.foeShots) {
    const k = clamp(s.life / 2.4, 0, 1);
    g.globalAlpha = 0.30 * k;
    g.fillStyle = "#9BD24E";
    for (let i = 1; i <= 3; i++) {
      g.beginPath();
      g.arc(s.x - s.vx * 0.010 * i, s.y - s.vy * 0.010 * i, s.r * (1 - i * 0.24), 0, 6.283);
      g.fill();
    }
    g.globalAlpha = 1;
    g.fillStyle = "#C7E86B";
    g.beginPath(); g.arc(s.x, s.y, s.r, 0, 6.283); g.fill();
    g.strokeStyle = COL.outline; g.lineWidth = 2.2; g.stroke();
    g.fillStyle = "rgba(255,255,255,.85)";
    g.beginPath(); g.arc(s.x - s.r * 0.3, s.y - s.r * 0.34, s.r * 0.30, 0, 6.283); g.fill();
  }
}

function drawShocks(g) {
  for (const s of S.shocks) {
    const k = clamp(s.t / s.life, 0, 1);
    const h = 44 * (1 - k * 0.2);
    g.globalAlpha = 0.72 * (1 - k);
    g.strokeStyle = "#FFC46A";
    g.lineWidth = 8;
    g.lineCap = "round";
    g.beginPath();
    g.moveTo(s.x - 20, s.y - 3);
    g.quadraticCurveTo(s.x, s.y - h, s.x + 20, s.y - 3);
    g.stroke();

    g.globalAlpha = 0.92 * (1 - k);
    g.strokeStyle = "#FFF6DC";
    g.lineWidth = 2.4;
    g.beginPath();
    g.moveTo(s.x - 11, s.y - 3);
    g.quadraticCurveTo(s.x, s.y - h * 0.72, s.x + 11, s.y - 3);
    g.stroke();
  }
  g.globalAlpha = 1;
}

/** Q 版脸。卡通和"小圆脸"的分界线就是有没有眼白 —— 没有眼白的敌人
 *  只是"带眼睛的圆"，看不出它在看哪儿，也读不出情绪。 */
function drawCuteEyes(g, x, y, r, gap, blink) {
  for (const s of [-1, 1]) {
    if (blink) {
      g.strokeStyle = COL.ink;
      g.lineWidth = 2.0;
      g.lineCap = "round";
      g.beginPath();
      g.arc(x + s * gap, y, r * 0.9, 0.34, Math.PI - 0.34);
      g.stroke();
      continue;
    }
    g.fillStyle = "#FFFFFF";
    g.beginPath(); g.ellipse(x + s * gap, y, r, r * 1.12, 0, 0, 6.283); g.fill();
    g.strokeStyle = COL.outline; g.lineWidth = 1.5; g.stroke();
    g.fillStyle = COL.ink;
    g.beginPath(); g.arc(x + s * gap + r * 0.26, y + r * 0.10, r * 0.54, 0, 6.283); g.fill();
    g.fillStyle = "rgba(255,255,255,.96)";
    g.beginPath(); g.arc(x + s * gap + r * 0.12, y - r * 0.36, r * 0.21, 0, 6.283); g.fill();
  }
  // 腮红：这两个点一加，整张脸就从"玩具"变成"活的"
  g.globalAlpha = 0.42;
  g.fillStyle = "#FF8FA0";
  for (const s of [-1, 1]) {
    g.beginPath();
    g.ellipse(x + s * (gap + r * 1.3), y + r * 1.5, r * 0.62, r * 0.4, 0, 0, 6.283);
    g.fill();
  }
  g.globalAlpha = 1;
}

/** 刺毛虫：三节身体 + 触角 + 六条小短腿。毛虫的读法是"分节"，不是"绿圆球" */
function drawWorm(g, f, bw, bh, t) {
  const d = f.def;
  // 三节要**都露出来**：头节画大了会把中节整个盖住，看起来就是"两个球"。
  // 所以头节只比中节大一点，节间距留够。
  const seg = [
    { x: -bw * 0.36, rx: 0.17, ry: 0.30, c: d.c3 },
    { x: -bw * 0.06, rx: 0.21, ry: 0.38, c: d.c1 },
    { x: bw * 0.27,  rx: 0.28, ry: 0.46, c: d.c1 },
  ];

  // 腿：左右各三条，交替摆 —— 没有腿的毛虫读起来像一坨面团
  g.strokeStyle = d.c3;
  g.lineWidth = 3.0;
  g.lineCap = "round";
  for (let i = 0; i < 3; i++) {
    for (const sd of [-1, 1]) {
      const sw = Math.sin(t * 9 + i * 1.5 + (sd > 0 ? 1.7 : 0)) * 2.6;
      g.beginPath();
      g.moveTo(seg[i].x + sd * 2, bh * 0.18);
      g.lineTo(seg[i].x + sd * 2 + sw, bh * 0.50);
      g.stroke();
    }
  }

  // 身体：尾 → 头，一节比一节大
  for (let i = 0; i < seg.length; i++) {
    const q = seg[i];
    g.fillStyle = q.c;
    g.beginPath();
    g.ellipse(q.x, 0, bw * q.rx, bh * q.ry, 0, 0, 6.283);
    g.fill();
    g.strokeStyle = COL.outline;
    g.lineWidth = 2.4;
    g.stroke();
    // 背上的斑点
    g.globalAlpha = 0.5;
    g.fillStyle = "#2F6B2A";
    g.beginPath();
    g.ellipse(q.x - bw * 0.06, -bh * 0.16 * q.ry * 2, bw * 0.045, bh * 0.05, 0, 0, 6.283);
    g.ellipse(q.x + bw * 0.06, -bh * 0.10 * q.ry * 2, bw * 0.035, bh * 0.04, 0, 0, 6.283);
    g.fill();
    g.globalAlpha = 1;
  }

  // 触角：两根带小球的触须，虫子的第一识别特征
  const hx = bw * 0.30, hy = -bh * 0.44;
  g.strokeStyle = COL.outline;
  g.lineWidth = 2.0;
  g.lineCap = "round";
  for (const sd of [-1, 1]) {
    const ex = hx + sd * 9, ey = hy - bh * 0.34;
    g.beginPath();
    g.moveTo(hx + sd * 3, hy + 3);
    g.quadraticCurveTo(hx + sd * 12, hy - bh * 0.16, ex, ey);
    g.stroke();
    g.fillStyle = "#FFD34E";
    g.beginPath(); g.arc(ex, ey, 3.4, 0, 6.283); g.fill();
    g.strokeStyle = COL.outline; g.lineWidth = 1.2; g.stroke();
    g.lineWidth = 2.0;
  }

  drawCuteEyes(g, hx + 1, -bh * 0.02, 4.5, 4.7, false);
  g.strokeStyle = COL.outline;
  g.lineWidth = 1.6;
  g.lineCap = "round";
  g.beginPath();
  g.arc(hx + 2, bh * 0.16, 3.2, 0.25, Math.PI - 0.35);
  g.stroke();
}

/** 幼虫：两节小胖虫，只会往 BOSS 身边爬。它得比刺毛虫更小更傻，
 *  否则玩家会把它当成"又一波怪"，而不是"Boss 的口粮" */
function drawLarva(g, f, bw, bh, t) {
  const d = f.def;
  const wig = Math.sin(t * 15);

  g.strokeStyle = d.c3;
  g.lineWidth = 2.6;
  g.lineCap = "round";
  for (const bx of [-bw * 0.10, bw * 0.14]) {
    for (const sd of [-1, 1]) {
      const sw = Math.sin(t * 15 + bx) * 2;
      g.beginPath();
      g.moveTo(bx, bh * 0.16);
      g.lineTo(bx + sw, bh * 0.50);
      g.stroke();
    }
  }

  // 尾节（左）+ 头节（右）
  for (const [bx, r, col] of [[-bw * 0.20, 0.32, d.c3], [bw * 0.16, 0.44, d.c1]]) {
    g.fillStyle = col;
    g.beginPath();
    g.ellipse(bx, wig * (bx > 0 ? 1.4 : -1.4), bw * r, bh * 0.44, 0, 0, 6.283);
    g.fill();
    g.strokeStyle = COL.outline;
    g.lineWidth = 2.2;
    g.stroke();
  }
  // 一根小触角：和刺毛虫的两根区分开
  g.strokeStyle = COL.outline;
  g.lineWidth = 1.8;
  g.beginPath();
  g.moveTo(bw * 0.22, -bh * 0.36);
  g.quadraticCurveTo(bw * 0.30, -bh * 0.62, bw * 0.40, -bh * 0.56);
  g.stroke();

  drawCuteEyes(g, bw * 0.20, -bh * 0.02, 3.4, 3.6, false);
}

/** 乌鸦：圆胖身子 + 扇翅膀 + 呆毛。飞行敌人要"看得出来在飞"，靠翅膀和尾羽 */
function drawCrow(g, f, bw, bh, t) {
  const d = f.def;
  const flap = Math.sin(t * 12);

  // 尾羽
  g.fillStyle = d.c3;
  g.strokeStyle = COL.outline;
  g.lineWidth = 2.0;
  for (const i of [-1, 0, 1]) {
    g.beginPath();
    g.moveTo(-bw * 0.24, 0);
    g.lineTo(-bw * 0.64, i * 7 - 3 + flap * 2);
    g.lineTo(-bw * 0.26, bh * 0.20);
    g.closePath();
    g.fill();
    g.stroke();
  }

  // 身体
  g.fillStyle = d.c1;
  g.beginPath(); g.ellipse(0, bh * 0.04, bw * 0.40, bh * 0.40, 0, 0, 6.283); g.fill();
  g.strokeStyle = COL.outline; g.lineWidth = 2.4; g.stroke();
  // 肚皮
  g.fillStyle = d.c2;
  g.beginPath(); g.ellipse(bw * 0.04, bh * 0.16, bw * 0.26, bh * 0.22, 0, 0, 6.283); g.fill();

  // 头
  const hx = bw * 0.20, hy = -bh * 0.30;
  g.fillStyle = d.c1;
  g.beginPath(); g.ellipse(hx, hy, bw * 0.27, bh * 0.27, 0, 0, 6.283); g.fill();
  g.strokeStyle = COL.outline; g.lineWidth = 2.4; g.stroke();

  // 呆毛
  g.strokeStyle = COL.outline; g.lineWidth = 2.2; g.lineCap = "round";
  for (const sd of [-1, 1]) {
    g.beginPath();
    g.moveTo(hx - sd * 3, hy - bh * 0.22);
    g.quadraticCurveTo(hx - sd * 6, hy - bh * 0.48, hx - sd * 1, hy - bh * 0.52);
    g.stroke();
  }

  // 喙
  g.fillStyle = "#FFB443";
  g.beginPath();
  g.moveTo(hx + bw * 0.20, hy + 1);
  g.lineTo(hx + bw * 0.44, hy + 5);
  g.lineTo(hx + bw * 0.20, hy + 9);
  g.closePath();
  g.fill();
  g.strokeStyle = COL.outline; g.lineWidth = 1.8; g.stroke();

  // 翅膀：贴着身体两侧扇，扇的是"扁椭圆"，不是圆
  const wf = 0.55 + flap * 0.45;
  for (const sd of [-1, 1]) {
    g.fillStyle = sd > 0 ? d.c2 : d.c3;
    g.beginPath();
    g.ellipse(-bw * 0.06, bh * 0.02 + sd * 2, bw * 0.24 * wf, bh * 0.34, sd * 0.5, 0, 6.283);
    g.fill();
    g.strokeStyle = COL.outline; g.lineWidth = 2.0; g.stroke();
  }

  drawCuteEyes(g, hx + 1, hy - 1, 4.4, 4.8, false);
}

/** 小野猪：圆身子 + 大猪鼻 + 獠牙 + 卷尾巴。猪鼻是唯一识别点，画小了就认不出 */
function drawBoar(g, f, bw, bh, t) {
  const d = f.def;

  // 腿
  g.strokeStyle = d.c3;
  g.lineWidth = 5.4;
  g.lineCap = "round";
  for (const [bx, ph] of [[-bw * 0.26, 0], [-bw * 0.06, 1.6], [bw * 0.14, 0], [bw * 0.32, 1.6]]) {
    const sw = Math.sin(t * 10 + ph) * 3.2;
    g.beginPath();
    g.moveTo(bx, bh * 0.22);
    g.lineTo(bx + sw, bh * 0.50);
    g.stroke();
  }

  // 卷尾巴
  g.strokeStyle = COL.outline;
  g.lineWidth = 2.2;
  g.beginPath();
  g.arc(-bw * 0.44, -bh * 0.06, 5.5, 0.9, 5.0);
  g.stroke();

  // 耳朵
  g.fillStyle = d.c3;
  g.strokeStyle = COL.outline;
  g.lineWidth = 2.0;
  for (const sd of [-1, 1]) {
    g.beginPath();
    g.moveTo(bw * 0.12 + sd * 6, -bh * 0.32);
    g.lineTo(bw * 0.20 + sd * 10, -bh * 0.58);
    g.lineTo(bw * 0.30 + sd * 6, -bh * 0.26);
    g.closePath();
    g.fill();
    g.stroke();
  }

  // 身体
  g.fillStyle = d.c1;
  g.beginPath(); g.ellipse(0, bh * 0.02, bw * 0.48, bh * 0.44, 0, 0, 6.283); g.fill();
  g.strokeStyle = COL.outline; g.lineWidth = 2.6; g.stroke();
  // 浅色肚皮
  g.fillStyle = d.c2;
  g.beginPath(); g.ellipse(bw * 0.02, bh * 0.18, bw * 0.30, bh * 0.20, 0, 0, 6.283); g.fill();

  // 猪鼻：粉色大椭圆 + 两个鼻孔
  const nx = bw * 0.40, ny = bh * 0.08;
  g.fillStyle = "#F8A0B0";
  g.beginPath(); g.ellipse(nx, ny, bw * 0.13, bh * 0.14, 0, 0, 6.283); g.fill();
  g.strokeStyle = COL.outline; g.lineWidth = 1.8; g.stroke();
  g.fillStyle = "#8E4658";
  for (const sd of [-1, 1]) {
    g.beginPath();
    g.ellipse(nx + sd * bw * 0.045, ny, bw * 0.020, bh * 0.045, 0, 0, 6.283);
    g.fill();
  }

  // 獠牙：两颗小白牙从鼻子下面翘出来
  g.fillStyle = "#FFF8EA";
  g.strokeStyle = COL.outline;
  g.lineWidth = 1.4;
  for (const sd of [-1, 1]) {
    g.beginPath();
    g.moveTo(bw * 0.30 + sd * 5, bh * 0.22);
    g.quadraticCurveTo(bw * 0.36 + sd * 7, bh * 0.30, bw * 0.30 + sd * 3, bh * 0.36);
    g.lineTo(bw * 0.26 + sd * 5, bh * 0.24);
    g.closePath();
    g.fill();
    g.stroke();
  }

  drawCuteEyes(g, bw * 0.20, -bh * 0.16, 5.0, 5.6, false);
}

function drawFoe(g, f) {
  if (f.isBoss) { drawBoss(g, f); return; }
  const d = f.def;
  const cx = f.x, cy = f.y - f.h / 2;
  const bw = f.w, bh = f.h;
  const squash = f.hitT > 0 ? f.hitT / 0.20 : 0;
  const t = S.t + (f.bob || 0);

  // 影子
  if (!f.fly) {
    g.globalAlpha = 0.16;
    g.fillStyle = "#16261C";
    g.beginPath();
    g.ellipse(cx, f.y + 2, bw * 0.42, 4.5, 0, 0, 6.283);
    g.fill();
    g.globalAlpha = 1;
  }

  const sx = 1 + squash * 0.18, sy = 1 - squash * 0.16;

  g.save();
  g.translate(cx, cy + (f.fly ? Math.sin(f.bob) * 2.5 : 0));
  g.scale(sx, sy);
  // 只画朝右的版本，靠镜像翻面 —— 三套造型各自处理左右会把代码写成三份
  g.save();
  g.scale(f.face, 1);
  if (f.larva) drawLarva(g, f, bw, bh, t);
  else if (f.kind === "fly") drawCrow(g, f, bw, bh, t);
  else if (f.kind === "charge") drawBoar(g, f, bw, bh, t);
  else drawWorm(g, f, bw, bh, t);
  g.restore();
  g.restore();

  // ---- 包裹层：这是这个游戏里唯一的"血条"，必须一眼数得清
  if (f.coat > 0) {
    for (let i = 0; i < f.coat; i++) {
      const p = i / 3;
      g.strokeStyle = i === 2 ? "#B9F06A" : "#8FD45A";
      g.lineWidth = 3.2 - i * 0.5;
      g.globalAlpha = 0.95;
      g.beginPath();
      g.ellipse(cx, cy, bw * 0.5 + 3 + p * 5, bh * 0.5 + 3 + p * 5,
        (i * 0.5 + S.t * 0.6) % 3.14, 0.3 + i, 3.9 + i);
      g.stroke();
    }
    g.globalAlpha = 1;
    if (f.coat === 2) {
      g.globalAlpha = 0.28 + Math.sin(S.t * 8) * 0.14;
      g.fillStyle = "#B9F06A";
      g.beginPath();
      g.ellipse(cx, cy, bw * 0.72, bh * 0.72, 0, 0, 6.283);
      g.fill();
      g.globalAlpha = 1;
    }
  }
}

function drawBall(g, b) {
  const cx = b.x, cy = b.y - b.r;
  const r = b.r;
  // 被推的那一刻沿运动方向拉长、垂直方向压扁（0..0.45，0.3 秒内收回去）。
  // 球是圆的，圆的滚动本身看不出"受力" —— 这一下形变是推球唯一的物理读数。
  const sq = b.pushSquash || 0;
  const rx = r * (1 + sq * 0.42);
  const ry = r * (1 - sq * 0.26);

  // 拖影：速度越快拖得越长。四个残影，alpha 递减。
  const sp = Math.abs(b.vx);
  if (sp > 260) {
    const k = Math.min(1, (sp - 260) / 700);
    for (let i = 1; i <= 3; i++) {
      g.globalAlpha = 0.16 * k * (1 - i * 0.24);
      g.fillStyle = b.mud ? "#8A6A40" : "#CFEE7C";
      g.beginPath();
      g.ellipse(cx - sign(b.vx) * i * 11 * k, cy, rx * (1 - i * 0.08), ry * (1 - i * 0.08), 0, 0, 6.283);
      g.fill();
    }
    g.globalAlpha = 1;
  }

  // 影子
  g.globalAlpha = 0.2;
  g.fillStyle = "#16261C";
  g.beginPath();
  g.ellipse(cx, b.y + 2, r * 0.9, 6, 0, 0, 6.283);
  g.fill();
  g.globalAlpha = 1;

  // 外发光：球是场上唯一"可交互"的东西，必须一眼从敌人里挑出来。
  // 刺毛虫本身也是绿圆球（#8FC96A），只靠颜色分不开 —— 靠光晕和体量。
  g.globalAlpha = 0.22 + Math.sin(S.t * 7) * 0.09;
  g.fillStyle = b.mud ? "#B08A52" : "#D8F98C";
  g.beginPath();
  g.arc(cx, cy, r * 1.34, 0, 6.283);
  g.fill();
  g.globalAlpha = 1;

  // 球体
  g.fillStyle = b.mud ? "#7A5C36" : "#C9E96E";
  g.beginPath();
  g.ellipse(cx, cy, rx, ry, 0, 0, 6.283);
  g.fill();
  g.strokeStyle = COL.outline;
  g.lineWidth = 2.4;
  g.stroke();

  // 高光
  g.globalAlpha = 0.5;
  g.fillStyle = "#FFFFFF";
  g.beginPath();
  g.ellipse(cx - r * 0.32, cy - r * 0.38, r * 0.24, r * 0.16, -0.6, 0, 6.283);
  g.fill();
  g.globalAlpha = 1;

  // 冰壳：层数越多，外圈越白越厚，还长出几根冰刺。
  // 这是"这颗球现在一撞就整只卷走"的**唯一**读数 ——
  // 不做成数字，因为战斗中没人会去读数字。
  if (b.frost > 0) {
    g.globalAlpha = 0.16 + 0.13 * b.frost;
    g.fillStyle = "#DFF6FF";
    g.beginPath();
    g.arc(cx, cy, r, 0, 6.283);
    g.fill();
    g.globalAlpha = 1;

    g.strokeStyle = "rgba(226,248,255,.92)";
    g.lineWidth = 2 + b.frost;
    g.lineCap = "round";
    for (let i = 0; i < b.frost * 2 + 1; i++) {
      const a0 = b.spin * 0.6 + i * 1.9;
      g.beginPath();
      g.arc(cx, cy, r - 2, a0, a0 + 0.5);
      g.stroke();
    }

    for (let i = 0; i < b.frost; i++) {
      const a = b.spin + i * 2.1;
      const px = cx + Math.cos(a) * (r - 1), py = cy + Math.sin(a) * (r - 1);
      g.fillStyle = "#EAFBFF";
      g.beginPath();
      g.moveTo(px + Math.cos(a) * 8, py + Math.sin(a) * 8);
      g.lineTo(px + Math.cos(a + 1.9) * 7, py + Math.sin(a + 1.9) * 7);
      g.lineTo(px + Math.cos(a - 1.9) * 7, py + Math.sin(a - 1.9) * 7);
      g.closePath();
      g.fill();
      g.strokeStyle = "rgba(120,170,200,.75)";
      g.lineWidth = 1.2;
      g.stroke();
    }
  }

  // 缠绕的苔绳：跟着 spin 转，读得出"在滚"
  g.save();
  g.translate(cx, cy);
  g.rotate(b.spin);
  g.strokeStyle = b.mud ? "rgba(50,36,20,.55)" : "rgba(60,110,40,.55)";
  g.lineWidth = 2.6;
  g.lineCap = "round";
  for (let i = 0; i < 3; i++) {
    g.beginPath();
    g.arc(0, 0, r * (0.5 + i * 0.16), i * 1.1, i * 1.1 + 1.5);
    g.stroke();
  }
  g.restore();

  // 里面那位的眼睛 —— 让球"是个活物被包起来了"，不是道具
  g.fillStyle = "rgba(20,26,18,.75)";
  g.beginPath();
  g.arc(cx - r * 0.18, cy - r * 0.02, r * 0.11, 0, 6.283);
  g.arc(cx + r * 0.18, cy - r * 0.02, r * 0.11, 0, 6.283);
  g.fill();

  // 装载数
  if (b.holds > 1) {
    g.fillStyle = "#FFE58A";
    g.font = "bold 13px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
    g.textAlign = "center";
    g.textBaseline = "middle";
    g.lineWidth = 3;
    g.strokeStyle = "rgba(24,32,20,.85)";
    g.strokeText("x" + b.holds, cx, cy + r * 0.52);
    g.fillText("x" + b.holds, cx, cy + r * 0.52);
  }

  // 剩余的气：球外侧画一圈弧。这是"这颗球还能滚多久"的**唯一**读数，
  // 必须能在不读数字的情况下看出大概 —— 所以用长度而不是数字。
  const air = b.air === undefined ? 1 : b.air;
  const a0 = -Math.PI / 2;
  g.lineWidth = 3.4;
  g.lineCap = "round";
  g.strokeStyle = "rgba(20,30,22,.28)";
  g.beginPath();
  g.arc(cx, cy, r + 6, 0, 6.283);
  g.stroke();
  g.strokeStyle = air > 0.55 ? "rgba(150,235,120,.85)"
                : air > 0.28 ? "rgba(255,206,90,.9)"
                : "rgba(255,110,90,.95)";
  g.beginPath();
  g.arc(cx, cy, r + 6, a0, a0 + 6.283 * air);
  g.stroke();

  // 快漏完了：裂纹 + 抖。给一个"再不动手就没了"的即时信号
  if (air < 0.42) {
    const k = (0.42 - air) / 0.42;
    const jx = Math.sin(S.t * 46) * k * 2.2;
    g.strokeStyle = "rgba(255,90,70," + (0.3 + k * 0.55).toFixed(2) + ")";
    g.lineWidth = 2;
    for (let i = 0; i < 3; i++) {
      const a = i * 2.1 + hash(i) * 3;
      g.beginPath();
      g.moveTo(cx + jx + Math.cos(a) * r * 0.2, cy + Math.sin(a) * r * 0.2);
      g.lineTo(cx + jx + Math.cos(a) * r * 0.85, cy + Math.sin(a) * r * 0.85);
      g.stroke();
    }
  }
}

/* ----------------------------------------------------------------------------
   预瞄线：画在关卡之上、单位之下。压在所有东西下面，但比地面亮。
   -------------------------------------------------------------------------- */
const AIM_COL = {
  fire:  "255,146,72",
  camp:  "255,212,88",
  stump: "226,226,226",
  stop:  "126,232,255",
  air:   "126,232,255",
  water: "120,214,255",
};

function drawAimLine(g, b, A, dir) {
  const pts = A.pts;
  if (!pts || pts.length < 2) return;
  const col = AIM_COL[A.end] || AIM_COL.air;

  // 按"反弹前 / 反弹后"切段。撞墙之后球会滚回来，这一段是真的，
  // 但它和"我主动推出去"不是同一件事 —— 画成同样的线，玩家会以为
  // 球会一直往那个方向走（截图里看起来就是一条笔直的长线）。
  const parts = [];
  let cur = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    if (pts[i].ph !== pts[i - 1].ph) { parts.push(cur); cur = [pts[i - 1]]; }
    cur.push(pts[i]);
  }
  parts.push(cur);

  g.lineCap = "round";
  g.setLineDash([8, 7]);
  for (let k = 0; k < parts.length; k++) {
    const seg = parts[k];
    if (seg.length < 2) continue;
    g.globalAlpha = k === 0 ? 1 : 0.3;
    g.strokeStyle = "rgba(10,22,14,.62)";
    g.lineWidth = 6.5;
    g.beginPath();
    g.moveTo(seg[0].x, seg[0].y);
    for (let i = 1; i < seg.length; i++) g.lineTo(seg[i].x, seg[i].y);
    g.stroke();
    g.strokeStyle = "rgba(" + col + ",1)";
    g.lineWidth = 3.4;
    g.beginPath();
    g.moveTo(seg[0].x, seg[0].y);
    for (let i = 1; i < seg.length; i++) g.lineTo(seg[i].x, seg[i].y);
    g.stroke();
  }
  g.setLineDash([]);
  g.globalAlpha = 0.9;

  // 终点：一个空心圈。落点比路径更重要 —— 玩家算的是"最后停在哪"
  const last = pts[pts.length - 1];
  g.globalAlpha = 0.82;
  g.beginPath();
  g.arc(last.x, last.y, 8, 0, 6.283);
  g.stroke();
  g.beginPath();
  g.arc(last.x, last.y, 3, 0, 6.283);
  g.fillStyle = "rgba(" + col + ",.9)";
  g.fill();

  // 沿途事件
  g.globalAlpha = 0.95;
  g.font = "bold 12px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
  g.textAlign = "center";
  g.textBaseline = "middle";
  for (const m of A.marks) {
    const label = m.kind === "fire" ? "烧"
                : m.kind === "camp" ? "袋"
                : m.kind === "mud"  ? "泥"
                : m.kind === "stump" ? "桩"
                : m.kind === "water" ? "水"
                : m.kind === "bounce" ? "弹"
                : m.kind === "portal" ? "洞"
                : m.kind === "expire" ? "散"
                : String(m.n);
    g.lineWidth = 3;
    g.strokeStyle = "rgba(16,26,20,.85)";
    g.strokeText(label, m.x, m.y);
    g.fillStyle = m.kind === "fire" ? "#FFB07A"
                : m.kind === "camp" ? "#FFE08A"
                : m.kind === "foe"  ? "#C9F06E"
                : m.kind === "water" ? "#8FD8F0"
                : m.kind === "bounce" ? "#B6EE72"
                : m.kind === "portal" ? "#9FE4FF"
                : "rgba(220,235,240,.9)";
    g.fillText(label, m.x, m.y);
  }

  // 这一球能撞几只 —— 连锁关唯一的决策依据
  if (A.hits > 0) {
    g.font = "bold 12px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
    g.textAlign = "left";
    g.fillStyle = "rgba(" + col + ",.95)";
    g.strokeStyle = "rgba(16,26,20,.85)";
    g.lineWidth = 3;
    const tx = last.x + 12, ty = last.y - 14;
    g.strokeText("撞 " + A.hits, tx, ty);
    g.fillText("撞 " + A.hits, tx, ty);
  }
  g.restore();
}

function drawAim(g) {
  // 站在台面上时提醒"↓ 能下去"。只在能穿的时候画 —— 一直画就成了噪音
  const p = S.p;
  if (p && !p.dead && p.onGround && p.ground && p.ground.kind !== "ground") {
    const bob = Math.sin(S.t * 5) * 3;
    g.save();
    g.globalAlpha = 0.55;
    g.strokeStyle = "#FFFFFF";
    g.lineWidth = 2.6;
    g.lineCap = "round";
    g.beginPath();
    g.moveTo(p.x - 7, p.y + 5 + bob);
    g.lineTo(p.x, p.y + 13 + bob);
    g.lineTo(p.x + 7, p.y + 5 + bob);
    g.stroke();
    g.restore();
  }

  // 轨迹默认**不画**。用户原话："球滚动的轨迹不用显示出来了"。
  // 常驻的预测线会把画面变成一张工程图，而且看久了玩家就不再看球本身。
  // 想算的时候按住 Shift —— 它退回到"可选辅助"的位置。
  if (!S.aim) return;

  for (const b of S.balls) {
    if (b.dead) continue;
    const dirs = b.onGround && Math.abs(b.vx) < 140 ? [-1, 1] : [sign(b.vx) || 1];
    for (const d of dirs) drawAimLine(g, b, aimFor(b, d), d);
  }
}

function drawShot(g, s) {
  const k = clamp(s.life / s.maxLife, 0, 1);

  /* ---- 溜溜球：一根绳 + 一个转起来的盘。绳子从人身上出去，这条线是"特色"本身 ---- */
  if (s.kind === "yoyo") {
    const u = s.u;
    g.globalAlpha = 1;
    g.strokeStyle = "#FFF3D6";
    g.lineWidth = 2.2;
    g.lineCap = "round";
    g.beginPath();
    if (u && !u.dead) {
      g.moveTo(u.x + s.dir * 14, u.y - 30);
      g.quadraticCurveTo((u.x + s.x) / 2, Math.min(u.y - 30, s.y) - 16, s.x, s.y);
    }
    g.stroke();

    g.save();
    g.translate(s.x, s.y);
    g.rotate(s.spin);
    g.fillStyle = "#FFC94E";
    g.beginPath();
    g.arc(0, 0, s.r, 0, 6.283);
    g.fill();
    g.strokeStyle = COL.outline;
    g.lineWidth = 2.4;
    g.stroke();
    g.fillStyle = "#FF8A3C";
    g.beginPath();
    g.arc(0, 0, s.r * 0.42, 0, 6.283);
    g.fill();
    g.strokeStyle = "rgba(255,255,255,.85)";
    g.lineWidth = 1.6;
    g.beginPath();
    g.moveTo(-s.r * 0.8, 0);
    g.lineTo(s.r * 0.8, 0);
    g.stroke();
    g.restore();
    return;
  }

  /* ---- 音波：一团往前推的弧。外圈张得越开，读起来才是"锥"不是"圈" ---- */
  if (s.kind === "wave") {
    const dir = s.dir || 1;
    const fade = clamp(k * 1.6, 0, 1);
    g.lineCap = "round";
    for (let i = 0; i < 3; i++) {
      const rr2 = s.r * (0.46 + i * 0.26);
      const wide = 0.52 + i * 0.16;
      g.lineWidth = 6.4 - i * 1.5;
      g.globalAlpha = fade * (0.95 - i * 0.24);
      g.strokeStyle = s.color;
      g.beginPath();
      if (dir > 0) g.arc(s.x, s.y, rr2, -wide, wide);
      else g.arc(s.x, s.y, rr2, Math.PI - wide, Math.PI + wide);
      g.stroke();
    }
    // 波心一点白：没有它，三圈弧在浅色背景上会糊成一片
    g.globalAlpha = fade * 0.85;
    g.fillStyle = "#FFFFFF";
    g.beginPath();
    g.arc(s.x - dir * s.r * 0.18, s.y, 4.6, 0, 6.283);
    g.fill();
    g.globalAlpha = 1;
    return;
  }

  /* ---- 飞刀：一把转着飞的刀。刀尖在前、柄在后，转起来才像"丢出去" ---- */
  if (s.kind === "knife") {
    g.globalAlpha = 1;
    g.save();
    g.translate(s.x, s.y);
    g.rotate(s.spin);

    // 拖影：高速旋转的东西必须有轨迹，否则看起来只是"一个东西在飘"
    g.globalAlpha = 0.28;
    g.strokeStyle = s.color;
    g.lineWidth = 3;
    g.lineCap = "round";
    g.beginPath();
    g.arc(0, 0, 16, -2.2, -0.9);
    g.stroke();
    g.globalAlpha = 1;

    // 刀身
    g.fillStyle = s.color;
    g.beginPath();
    g.moveTo(24, 0);
    g.quadraticCurveTo(8, -7.5, -8, -5);
    g.lineTo(-12, 0);
    g.lineTo(-8, 5);
    g.quadraticCurveTo(8, 7.5, 24, 0);
    g.fill();
    g.strokeStyle = COL.outline;
    g.lineWidth = 2.2;
    g.stroke();

    // 磨出来的一道白
    g.strokeStyle = "rgba(255,255,255,.92)";
    g.lineWidth = 1.7;
    g.beginPath();
    g.moveTo(18, -1.2);
    g.lineTo(-6, -2.2);
    g.stroke();

    // 刀柄
    g.fillStyle = "#7A5230";
    rr(g, -24, -3.6, 13, 7.2, 3);
    g.fill();
    g.strokeStyle = COL.outline;
    g.lineWidth = 1.8;
    g.stroke();
    g.restore();
    return;
  }

  /* ---- 坚果：贴地滚，带旋转的纹路 ---- */
  if (s.kind === "nut") {
    g.globalAlpha = 1;
    g.save();
    g.translate(s.x, s.y);
    g.rotate(s.spin);
    g.fillStyle = s.color;
    g.beginPath();
    g.arc(0, 0, s.r, 0, 6.283);
    g.fill();
    g.strokeStyle = COL.outline;
    g.lineWidth = 2.4;
    g.stroke();
    g.strokeStyle = "rgba(255,236,196,.8)";
    g.lineWidth = 2;
    g.beginPath();
    g.arc(0, 0, s.r * 0.62, -0.6, 1.9);
    g.stroke();
    g.beginPath();
    g.arc(0, 0, s.r * 0.62, 2.1, 4.4);
    g.stroke();
    g.restore();
    return;
  }

  /* ---- 萝卜炮：一颗带绿叶的胡萝卜，翻滚 ---- */
  if (s.kind === "lob") {
    g.globalAlpha = 1;
    g.save();
    g.translate(s.x, s.y);
    g.rotate(s.spin);
    g.fillStyle = s.color;
    g.beginPath();
    g.moveTo(-11, -6);
    g.quadraticCurveTo(4, -11, 12, 0);
    g.quadraticCurveTo(4, 11, -11, 6);
    g.closePath();
    g.fill();
    g.strokeStyle = COL.outline;
    g.lineWidth = 2;
    g.stroke();
    g.fillStyle = "#5FBF5A";
    g.beginPath();
    g.ellipse(-13, -4, 6, 3.4, -0.5, 0, 6.283);
    g.ellipse(-13, 4, 5, 3, 0.5, 0, 6.283);
    g.fill();
    g.restore();
    return;
  }

  /* ---- 影分身：三只小狐影平推。要有尖耳和尖吻，否则读起来只是三个白团 ---- */
  if (s.kind === "shadow") {
    const a = clamp(k * 1.5, 0, 1);
    const dir = s.dir || 1;
    const drawFox = (cx, cy, sc, alpha, body) => {
      g.globalAlpha = alpha;
      g.fillStyle = body;
      g.beginPath();
      g.ellipse(cx, cy, s.r * 1.0 * sc, s.r * 0.72 * sc, 0, 0, 6.283);
      g.fill();
      // 尖吻（朝飞行方向）
      g.beginPath();
      g.moveTo(cx + dir * s.r * 0.7 * sc, cy - s.r * 0.16 * sc);
      g.lineTo(cx + dir * s.r * 1.7 * sc, cy + s.r * 0.10 * sc);
      g.lineTo(cx + dir * s.r * 0.66 * sc, cy + s.r * 0.42 * sc);
      g.closePath();
      g.fill();
      // 两只尖耳
      for (const sd of [-1, 1]) {
        g.beginPath();
        g.moveTo(cx + sd * s.r * 0.62 * sc - dir * s.r * 0.1 * sc, cy - s.r * 0.30 * sc);
        g.lineTo(cx + sd * s.r * 0.42 * sc - dir * s.r * 0.2 * sc, cy - s.r * 1.24 * sc);
        g.lineTo(cx + sd * s.r * 0.12 * sc - dir * s.r * 0.2 * sc, cy - s.r * 0.52 * sc);
        g.closePath();
        g.fill();
      }
      // 一条甩起来的尾巴
      g.strokeStyle = body;
      g.lineWidth = s.r * 0.34 * sc;
      g.lineCap = "round";
      g.beginPath();
      g.moveTo(cx - dir * s.r * 0.85 * sc, cy + s.r * 0.1 * sc);
      g.quadraticCurveTo(cx - dir * s.r * 1.6 * sc, cy - s.r * 0.5 * sc,
                         cx - dir * s.r * 1.35 * sc, cy - s.r * 1.0 * sc);
      g.stroke();
    };

    // 拖尾
    for (let t = 3; t >= 1; t--) {
      drawFox(s.x - dir * t * 16, s.y, 1 - t * 0.10, a * 0.16 * (4 - t) / 3, s.color);
    }
    // 本体
    drawFox(s.x, s.y, 1, a, "#EDE6FF");
    g.globalAlpha = a;
    // 眼睛
    g.fillStyle = "#3B2E6B";
    g.beginPath();
    g.arc(s.x + dir * s.r * 0.28, s.y - s.r * 0.12, s.r * 0.13, 0, 6.283);
    g.arc(s.x + dir * s.r * 0.62, s.y - s.r * 0.10, s.r * 0.13, 0, 6.283);
    g.fill();
    g.globalAlpha = 1;
    return;
  }

  // 兜底：一个带拖尾的圆
  g.globalAlpha = clamp(k * 1.6, 0, 1);
  g.fillStyle = s.color;
  g.beginPath();
  g.arc(s.x, s.y, s.r * (0.8 + k * 0.2), 0, 6.283);
  g.fill();
  g.globalAlpha = 1;
}

/* ============================================================================
   16. 绘制：HUD 与选择界面
   ========================================================================== */

/* ----------------------------------------------------------------------------
   目标进度 / 判定
   ---------------------------------------------------------------------------- */

function goalProgress() {
  const st = curStage();
  const done = S.killed >= S.total;
  if (st.goal === "limit") {
    const left = Math.max(0, st.ballLimit - S.stat.made);
    return {
      text: "球 " + S.stat.made + " / " + st.ballLimit + (done ? "" : " · 已清 " + S.killed + "/" + S.total),
      frac: S.stat.made / st.ballLimit, done,
    };
  }
  if (st.goal === "chain") {
    return {
      text: "最大 x" + S.stat.maxHolds + " / " + st.chain + (done ? "" : " · 已清 " + S.killed + "/" + S.total),
      frac: S.stat.maxHolds / st.chain,
      done: S.stat.maxHolds >= st.chain,
    };
  }
  if (st.goal === "bank") {
    return {
      text: "落袋 " + S.stat.bankHolds + " / " + st.bank + (done ? "" : " · 已清 " + S.killed + "/" + S.total),
      frac: S.stat.bankHolds / st.bank,
      done: S.stat.bankHolds >= st.bank,
    };
  }
  if (st.goal === "collect") {
    return {
      text: "收成 " + S.food + " / " + st.collect + (done ? "" : " · 已清 " + S.killed + "/" + S.total),
      frac: S.food / st.collect,
      done: S.food >= st.collect,
    };
  }
  // 两种"不许犯错"的目标：数字越小越好，进度条反着走
  if (st.goal === "intact") {
    return {
      text: "崩开 " + S.stat.burst + " 次 · 一次都不行" + (done ? "" : " · 已清 " + S.killed + "/" + S.total),
      frac: S.stat.burst === 0 ? 1 : 0,
      done: S.stat.burst === 0,
    };
  }
  if (st.goal === "nohit") {
    return {
      text: "挨打 " + S.stat.hits + " 次 · 一次都不行" + (done ? "" : " · 已清 " + S.killed + "/" + S.total),
      frac: S.stat.hits === 0 ? 1 : 0,
      done: S.stat.hits === 0,
    };
  }
  return {
    text: "剩余 " + (S.total - S.killed) + " 只 · 球 " + S.stat.made,
    frac: S.killed / Math.max(1, S.total), done,
  };
}

/** 结算评价：时间达标 +1 分，球数达标 +1 分。2 分 S，1 分 A，0 分 B */
function rate() {
  const st = curStage();
  let sc = 0;
  if (S.playT <= st.par.time) sc++;
  if (S.stat.made <= st.par.made) sc++;
  return sc >= 2 ? "S" : sc === 1 ? "A" : "B";
}

/* 关卡轨迹：顶上一排点。推关的「进度感」全靠这一条 ——
   没有它，玩家打第 5 关和打第 1 关的感觉是一样的。 */
function drawTrail(g) {
  const n = LEVELS.length;
  const gap = 22;
  const cx = W / 2;
  const total = (n - 1) * gap;

  g.textAlign = "left";
  g.textBaseline = "middle";
  g.font = "bold 13px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
  g.lineWidth = 3.4;
  g.strokeStyle = "rgba(6,20,14,.55)";
  const label = "第 " + (S.stage + 1) + " / " + n + " 关   " + curStage().name;

  /* 波次：一关 2~3 波，最后一波是 BOSS。没有这一行，玩家不知道"还剩多久"。
   *
   * **两块一起量、一起居中。** 上一版把关卡名居中、波次钉在 cx+132 ——
   * 关卡名一变长（"泥沼"→"陡坡·顶层推球"），两块之间的缝就忽大忽小，
   * 看起来像两个没对齐的控件。现在按两块的实际宽度算起点。
   */
  const wtxt = "第 " + Math.min(S.wave + 1, WAVES.length) + " / " + WAVES.length + " 波";
  const PAD = 24;
  const w1 = g.measureText(label).width;
  const w2 = g.measureText(wtxt).width;
  const x0 = cx - (w1 + PAD + w2) / 2;

  g.strokeText(label, x0, 22);
  g.fillStyle = "rgba(255,255,255,.94)";
  g.fillText(label, x0, 22);

  g.strokeText(wtxt, x0 + w1 + PAD, 22);
  g.fillStyle = (S.wave >= WAVES.length - 1) ? "#FF9E82" : "rgba(255,255,255,.82)";
  g.fillText(wtxt, x0 + w1 + PAD, 22);
  g.textAlign = "center";

  const pipOff = artOf("ui-pip");
  const pipOn = artOf("ui-pip-on");

  for (let i = 0; i < n; i++) {
    const x = cx - total / 2 + i * gap;
    const y = 45;
    const done = i < S.stage;
    const cur = i === S.stage;

    if (pipOff && pipOn) {
      // 有点/亮点图就贴图。深色底圈必须留着 —— 亮天空主题里，
      // 浅色方块糊在白云上就没了（原代码的圆点也是靠这个底圈才看得见）
      const s = cur ? 16 : 11;
      // 底圈跟着方块走（圆角矩形，不是圆）：形状不一致时读起来像"灰点 + 灰块"两层东西
      rr(g, x - s / 2 - 2, y - s / 2 - 2, s + 4, s + 4, 4.5);
      g.fillStyle = cur || done ? "rgba(20,34,26,.42)" : "rgba(20,34,26,.26)";
      g.fill();
      g.globalAlpha = cur ? 1 : done ? 0.95 : 0.72;
      g.drawImage(done || cur ? pipOn : pipOff, x - s / 2, y - s / 2, s, s);
      g.globalAlpha = 1;
    } else {
      // 深色底圈：亮天空主题里，浅灰点在白云上根本看不见
      g.beginPath();
      g.arc(x, y, (cur ? 6 : 4.2) + 2, 0, 6.283);
      g.fillStyle = "rgba(20,34,26,.38)";
      g.fill();
      g.beginPath();
      g.arc(x, y, cur ? 6 : 4.2, 0, 6.283);
      g.fillStyle = cur ? "#FFE066" : done ? "#B9F06A" : "rgba(255,255,255,.58)";
      g.fill();
    }

    if (cur) {
      g.strokeStyle = "rgba(255,224,102,.55)";
      g.lineWidth = 2.4;
      g.beginPath();
      g.arc(x, y, 10 + Math.sin(S.t * 4) * 1.6, 0, 6.283);
      g.stroke();
    }
  }
}

/** 下一波预告：地上画三圈扩散的标记 + 一行倒计时。看不见的刷新最气人 */
function drawWaveGap(g) {
  if (S.waveGap <= 0) return;
  const nx = WAVES[S.wave + 1] || [];
  const boss = nx.some(sp => sp.foe === "boss");
  const k = 1 - S.waveGap / (boss ? 1.6 : 1.1);

  g.save();
  g.textAlign = "center";
  g.textBaseline = "middle";
  g.font = "bold 22px 'Microsoft YaHei','PingFang SC',system-ui,sans-serif";
  const txt = boss ? "地面在震…" : "下一波";
  g.strokeStyle = "rgba(8,16,12,.72)";
  g.lineWidth = 4;
  g.strokeText(txt, W / 2, 128);
  g.fillStyle = boss ? "#FFB08A" : "#FFE9A8";
  g.fillText(txt, W / 2, 128);

  // 在每一只即将出现的敌人脚下画一个收缩的圈
  for (const sp of nx) {
    const r = 34 * (1 - k) + 10;
    g.globalAlpha = 0.35 + 0.45 * k;
    g.strokeStyle = boss ? "#FF9A6B" : "#FFE066";
    g.lineWidth = 3;
    g.beginPath();
    g.arc(sp.x, (sp.y || GROUND_Y) - 6, r, 0, 6.283);
    g.stroke();
  }
  g.globalAlpha = 1;
  g.restore();
}

/* ============================================================================
   14b. 面板 / 皮肤
   ============================================================================
   有美术面板图就走"奶油风"，没有就退回原来的深色玻璃风。

   **两套配色写在同一处**：上一版把颜色散在 drawHUD 和结算里各写一遍，
   改了一处忘了另一处，出现过"底是奶白、字是浅绿"（对比度 1.4:1，
   截图上几乎读不出来）。这里只允许通过 hudSkin() 取色。
   ========================================================================== */

/**
 * 九宫格拉伸。四个角不拉伸、四条边单向拉伸、中间双向拉伸。
 * 直接 `drawImage(img, x, y, w, h)` 拉一张圆角面板，圆角会变成椭圆 ——
 * 在 548×500 的结算卡上那四个角一眼就看得出是"被拽开的"。
 *
 * `ds` 是**源图**上的角尺寸。目标角尺寸要按缩放比折算，不能直接用 ds：
 * 上一版写死 `dd = min(ds, w/2, h/2)`，把 583×96 的提示条铺到 236×62 时
 * dd 被算成 31，而 31+31 已经等于 62 —— 中间那一行高度变成 0，
 * 上下两边硬压在一起，圆角挤成一条缝。
 */
function drawNine(g, img, x, y, w, h, ds) {
  const iw = img.width || img.naturalWidth;
  const ih = img.height || img.naturalHeight;
  if (!iw || !ih || w <= 0 || h <= 0) return;
  const k = Math.min(w / iw, h / ih);
  const dd = Math.max(2, Math.min(ds * k, w / 2 - 1, h / 2 - 1));
  const ss = Math.min(ds, iw / 2 - 1, ih / 2 - 1);
  const sx = [0, ss, iw - ss], sw = [ss, iw - ss * 2, ss];
  const dx = [x, x + dd, x + w - dd], dw = [dd, w - dd * 2, dd];
  const sy = [0, ss, ih - ss], sh = [ss, ih - ss * 2, ss];
  const dy = [y, y + dd, y + h - dd], dh = [dd, h - dd * 2, dd];
  for (let r = 0; r < 3; r++) {
    for (let c = 0; c < 3; c++) {
      if (sw[c] <= 0 || sh[r] <= 0 || dw[c] <= 0 || dh[r] <= 0) continue;
      g.drawImage(img, sx[c], sy[r], sw[c], sh[r], dx[c], dy[r], dw[c], dh[r]);
    }
  }
}

/* ----------------------------------------------------------------------------
   奶白结算卡：**代码画，不贴图**
   ----------------------------------------------------------------------------
   上一版拿 ui-res.png 九宫格铺 620×520，整个卡面摊成了一颗蛋。

   病根不在 ds，在这张资产本身：ui-res.png 的圆角半径实测 **≈150px**
   （图高 420 的 36%）—— 它是一张"泡泡卡"。九宫格的前提是 ds ≥ 圆角半径；
   ds=56 时边条会把这段圆弧**顺着边拉长**，卡面变成"小圆角 + 一条长肩线"，
   就是蛋形。ds 提到 150 能让形状忠实，但圆角会变成 189px，读作胶囊。
   结论：这张资产只能在它自己的 524×420 上待着，一变形就没救。

   所以按 26px 圆角自己画。色值**全部取自资产**，不另起一套配色：
     顶 #FFFCFB → 中 #FBF8ED → 底 #F3E9D6，描边 #754E2D，
     另外资产顶部有一道 1.5px 的高光、底部有一圈内阴影 —— 这两笔是"纸感"的来源，
     少了它卡面会变成一块纯色塑料。
   -------------------------------------------------------------------------- */
function creamCard(g, x, y, w, h, r) {
  const R = r === undefined ? 26 : r;

  // 投影：偏下 6px、不扩散，让卡"坐在"压暗层上而不是浮着
  g.fillStyle = "rgba(24,14,6,.26)";
  rr(g, x + 2, y + 7, w, h, R);
  g.fill();

  const gr = g.createLinearGradient(0, y, 0, y + h);
  gr.addColorStop(0, "#FFFCFB");
  gr.addColorStop(0.34, "#FBF8EE");
  gr.addColorStop(0.80, "#F8F0DF");
  gr.addColorStop(1, "#F3E9D6");
  g.fillStyle = gr;
  rr(g, x, y, w, h, R);
  g.fill();

  // 顶部高光：只在圆角内沿上方 1/3 走，长度收在中间，不顶到两端圆角
  g.save();
  g.beginPath();
  rr(g, x, y, w, h, R);
  g.clip();
  const hl = g.createLinearGradient(0, y, 0, y + h * 0.30);
  hl.addColorStop(0, "rgba(255,255,255,.85)");
  hl.addColorStop(1, "rgba(255,255,255,0)");
  g.fillStyle = hl;
  g.fillRect(x + R * 0.5, y + 3, w - R, h * 0.30);
  // 底部内阴影：把卡"压"出厚度
  const sh = g.createLinearGradient(0, y + h - 46, 0, y + h);
  sh.addColorStop(0, "rgba(168,136,96,0)");
  sh.addColorStop(1, "rgba(168,136,96,.30)");
  g.fillStyle = sh;
  g.fillRect(x, y + h - 46, w, 46);
  g.restore();

  /* 描边两条：外面一条实棕 #754E2D（3.4px，和 HUD 那套同一支笔），
     里面再压一条 1.2px 的淡棕，作用是**把奶油底和描边分开** ——
     只画一条实棕，深棕直接啃进白面，边缘读作"锯齿"。 */
  g.strokeStyle = "#754E2D";
  g.lineWidth = 3.4;
  rr(g, x + 1.7, y + 1.7, w - 3.4, h - 3.4, Math.max(4, R - 1.7));
  g.stroke();
  g.strokeStyle = "rgba(138,100,64,.42)";
  g.lineWidth = 1.2;
  rr(g, x + 4.4, y + 4.4, w - 8.8, h - 8.8, Math.max(3, R - 4.4));
  g.stroke();
}

/** 画一块面板底：有图贴图（九宫格），没图画原来的半透明圆角。 */
function panelBg(g, key, x, y, w, h, ds, fallbackFill, fallbackRadius) {
  const img = artOf(key);
  const r = fallbackRadius === undefined ? 14 : fallbackRadius;

  /* 贴纸三件套：投影 → 面板 → 深棕描边。
   *
   * 之前只贴了一张奶白图，图本身的边是 1~2px 淡棕，落在绿草地上"没有轮廓" ——
   * 截图里那块 UI 读起来像网页里的 card，不像游戏里的牌子。
   * Q 版卡通的识别特征就是**深色粗描边**：只加这一圈，东西立刻从"控件"变"贴纸"。
   */
  g.fillStyle = "rgba(26,16,8,.22)";
  rr(g, x + 1, y + 4, w, h, r);
  g.fill();

  let okArt = false;
  if (img) {
    drawNine(g, img, x, y, w, h, ds);
    okArt = true;
  } else {
    g.fillStyle = fallbackFill || "rgba(12,26,20,.72)";
    rr(g, x, y, w, h, r);
    g.fill();
  }

  /* 描边按概念图重定过：`#754E2D`、3.4px。
   *
   * 上一版是 2.2px / rgba(92,60,34,.40) —— 半透明的细线。在奶白底上还看得见，
   * 一落到绿草地/暖黄天空上就糊进背景，"牌子"退化成"控件"。
   * 概念稿（concept/Game_UI_kit_sheet_*.png）里的面板边是**实色深棕 + 3~4px**，
   * 尺寸比 1:100 左右 —— 960 宽的画面正好对应 3.4px。 */
  g.strokeStyle = img ? "#754E2D" : "rgba(255,255,255,.14)";
  g.lineWidth = img ? 3.4 : 1.5;
  rr(g, x + 1.7, y + 1.7, w - 3.4, h - 3.4, Math.max(6, r - 1.7));
  g.stroke();
  return okArt;
}

/** 取当前配色。cream = 奶油面板图到位。 */
function hudSkin() {
  const cream = !!artOf("ui-tip");
  if (cream) {
    return {
      cream: true,
      ink: "#4A3524",          // 主文字 / 深棕
      ink2: "rgba(74,53,36,.70)",
      ink3: "rgba(74,53,36,.46)",
      hi: "#A85E20",           // 强调（目标名、关卡名）
      good: "#3F7D24",
      warn: "#B06A2C",
      bad: "#B0453A",
      barBg: "rgba(120,92,64,.20)",
      barOn: "#E0A23C",
      barDone: "#5FA53A",
    };
  }
  return {
    cream: false,
    ink: "#EAF6E2",
    ink2: "rgba(200,230,200,.72)",
    ink3: "rgba(190,220,190,.45)",
    hi: "#FFE9B0",
    good: "#B9F06A",
    warn: "#FFD86B",
    bad: "#FF9E8E",
    barBg: "rgba(255,255,255,.13)",
    barOn: "#8ED6F0",
    barDone: "#B9F06A",
  };
}

function drawHUD(g) {
  const p = S.p;
  if (!p) return;
  const H = HEROES[p.hero];

  drawTrail(g);
  drawWaveGap(g);

  // BOSS 层数条：贴在最上面，和关卡名分开一层 ——
  // BOSS 战中玩家最需要知道的是"还差几层"，不是自己还有几颗心。
  const boss = S.foes.find(f => f.isBoss && !f.dead);
  if (boss) {
    const cm = boss.cm || 3;
    const bw2 = 300, bx = W / 2 - bw2 / 2, by = 66;
    g.fillStyle = "rgba(12,8,22,.62)";
    rr(g, bx - 8, by - 7, bw2 + 16, 22, 11);
    g.fill();
    g.fillStyle = "rgba(255,255,255,.12)";
    rr(g, bx, by, bw2, 8, 4);
    g.fill();
    const k = clamp(boss.coat / cm, 0, 1);
    g.fillStyle = "#9BE86E";
    rr(g, bx, by, Math.max(5, bw2 * k), 8, 4);
    g.fill();
    // 每 3 层一道刻度：告诉玩家"再糊 3 层就变球"
    g.strokeStyle = "rgba(10,20,12,.55)";
    g.lineWidth = 2;
    for (let i = 3; i < cm; i += 3) {
      const px = bx + bw2 * (i / cm);
      g.beginPath(); g.moveTo(px, by - 1); g.lineTo(px, by + 9); g.stroke();
    }
    g.font = "bold 12px 'Microsoft YaHei','PingFang SC',system-ui,sans-serif";
    g.textAlign = "center";
    g.textBaseline = "middle";
    g.strokeStyle = "rgba(6,10,20,.7)";
    g.lineWidth = 3;
    const bt = "苔原巨兽 · 壳 " + boss.coat + " / " + cm;
    g.strokeText(bt, W / 2, by + 24);
    g.fillStyle = "#FFE6C8";
    g.fillText(bt, W / 2, by + 24);
  }

  // 左上：角色 + 心
  const K = hudSkin();
  panelBg(g, "ui-tip", 16, 14, 236, 62, 40, "rgba(12,26,20,.72)", 14);

  // 头像：有美术圆头像就贴，没图就画代码脸
  const av = artOf("head-" + H.id);
  const ring = artOf("ui-ring");
  if (ring) {
    // 徽章环：外圈一圈描边，把头像从奶油底上"抠"出来
    g.drawImage(ring, 26 - 3, 23 - 3, 50, 50);
  }
  g.save();
  g.beginPath();
  g.arc(48, 45, 22, 0, 6.283);
  g.clip();
  if (av) {
    g.drawImage(av, 26, 23, 44, 44);
  } else {
    g.fillStyle = H.c1;
    g.fillRect(26, 23, 44, 44);
  }
  g.restore();
  if (!ring) {
    g.strokeStyle = av ? "rgba(255,255,255,.55)" : H.c3;
    g.lineWidth = 2;
    g.beginPath();
    g.arc(48, 45, 22, 0, 6.283);
    g.stroke();
  }
  if (!av) drawEyes(g, 48, 44, 7, 2.6, 1, false);

  g.fillStyle = K.ink;
  g.font = "bold 16px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
  g.textAlign = "left";
  g.textBaseline = "middle";
  g.fillText(H.name, 78, 36);
  g.font = "12px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
  g.fillStyle = K.ink2;
  g.fillText(H.tag, 78, 52);

  // 心
  for (let i = 0; i < p.maxHp; i++) {
    const hx = 168 + i * 20, hy = 45;
    const on = i < p.hp;
    g.fillStyle = on ? "#E85466" : (K.cream ? "rgba(120,92,64,.22)" : "rgba(255,255,255,.16)");
    g.beginPath();
    g.moveTo(hx, hy + 7);
    g.bezierCurveTo(hx - 11, hy - 2, hx - 6, hy - 11, hx, hy - 5);
    g.bezierCurveTo(hx + 6, hy - 11, hx + 11, hy - 2, hx, hy + 7);
    g.fill();
  }

  // 右上：目标 + 进度
  // 底色 0.72 不是随手定的：这一块正好压在顶部树冠上，0.55 的时候
  // 树冠的黑影会透过来，目标名读不清（截图里第一眼就发现了）
  panelBg(g, "ui-cream", W - 268, 14, 252, 100, 26, "rgba(12,26,20,.72)", 14);

  // 卡片里**不放关卡名**。顶部正中已经有「第 2 / 8 关 泥沼」，
  // 同一句话在一屏上说两遍，卡片第一行就白占了 —— 这里只留目标。
  g.textAlign = "left";
  g.textBaseline = "middle";
  g.fillStyle = K.hi;
  g.font = "bold 19px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
  g.fillText(curGoal().name, W - 250, 40);

  // 进度条：目标数值 / 当前值。四关共用一条，字换，形状不换。
  // 底板用美术的胶囊条，填充仍用代码画 —— 填充要按百分比变长，
  // 贴图做不到"裁一半"，除非再切一张图。
  const pr = goalProgress();
  const progArt = artOf("ui-prog");
  const BX = W - 250, BY = 58, BW = 216, BH = 14;
  // 次序：先贴美术胶囊（它内部是不透明的奶油白 + 一圈棕描边），
  // 再在里侧 3px 铺一层暗色当"空槽"，最后才是橙色填充。
  // 上一版把暗槽画在美术**前面**，被那张不透明的内芯整个盖掉了 ——
  // 0% 的时候进度条只剩一圈描边，读起来像"一个输入框"。
  if (progArt) {
    // 整图拉伸，不走九宫格：这张图 456×72，目标是 216×14，九宫格会把
    // 两端的圆头压成两个针尖。整图拉伸的圆头变成扁椭圆，反而更像一条胶囊。
    g.drawImage(progArt, BX, BY, BW, BH);
  } else {
    g.fillStyle = K.cream ? "rgba(122,92,60,.55)" : "rgba(255,255,255,.20)";
    rr(g, BX, BY, BW, BH, BH / 2);
    g.fill();
  }
  // 空槽的对比度是量出来的：0.34 的时候这条读不出"槽"，只剩一根浅线 ——
  // 玩家看不到"还差多少"，进度条就退化成一条装饰线。
  g.fillStyle = K.cream ? "rgba(96,66,40,.52)" : "rgba(255,255,255,.16)";
  rr(g, BX + 3, BY + 3, BW - 6, BH - 6, (BH - 6) / 2);
  g.fill();
  if (pr.frac > 0) {
    g.fillStyle = pr.done ? K.barDone : K.barOn;
    rr(g, BX + 3, BY + 3, Math.max(5, (BW - 6) * clamp(pr.frac, 0, 1)), BH - 6, (BH - 6) / 2);
    g.fill();
  }

  // 进度文字里去掉和目标名重复的前缀。
  // goalProgress() 给的是 "收成 0 / 12 · 已清 0/8"，而上面的大字已经写着"收成"——
  // 逐字重复的标题读起来像表单，不像 HUD。只在这一处剥，函数本身不动
  // （结算和冒烟断言都吃它的原文）。
  let gline = pr.text;
  const gname = curGoal().name;
  if (gline.indexOf(gname + " ") === 0) gline = gline.slice(gname.length + 1);

  g.fillStyle = pr.done ? K.good : K.ink2;
  g.font = "12px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
  g.fillText(gline, BX, 85);

  // 收成挪到这一行的右端，不再单占一行。
  // 单占一行时它写的是「收成 0」，而进度行（收成关）读的是同一个数 S.food ——
  // 上下两行同一个数字，玩家会以为看错了。现在左边是"目标和打到哪了"，
  // 右边是"手上有多少"，是两件事。
  const coinArt = artOf("ui-coin");
  const coinTxt = "" + S.food;
  g.font = "bold 14px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
  const cw = g.measureText(coinTxt).width;
  const cxRight = W - 34;
  if (coinArt) {
    g.drawImage(coinArt, cxRight - cw - 19, 78, 15, 15);
  } else {
    g.fillStyle = "#FFD86B";
    g.beginPath();
    g.arc(cxRight - cw - 12, 85, 6.5, 0, 6.283);
    g.fill();
  }
  g.textAlign = "right";
  g.fillStyle = K.hi;
  g.fillText(coinTxt, cxRight, 85);
  g.textAlign = "left";

  // 卡片里不再挂"ESC 回选 · R 重来 · Shift 预测线"。
  // 屏幕底部本来就有那条 8 秒操作提示（含 Shift），两处都说等于都没说 ——
  // 而且它占了卡片最后 20px，把目标卡撑成一个表格。

  // 底部操作提示（前 8 秒）
  if (S.playT < 8) {
    g.globalAlpha = clamp((8 - S.playT) / 3, 0, 1) * 0.82;
    g.textAlign = "center";
    // 奶油风下是浅底，白字看不见 —— 换成深字 + 一条浅底
    if (K.cream) {
      g.fillStyle = "rgba(255,250,238,.80)";
      rr(g, W / 2 - 300, H - 36, 600, 26, 13);
      g.fill();
    }
    g.fillStyle = K.cream ? K.ink : "#E8F6DC";
    g.font = "13px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
    g.fillText("← → 移动   ·   空格 跳   ·   J 喷裹   ·   K 撞飞   ·   走进球里推它   ·   Shift 看全部预测线", W / 2, H - 22);
    g.globalAlpha = 1;
  }
}

/* ---------- 门口那间小屋 ---------- */
function drawHut(g, T, open) {
  const WX = 62, WY = 264, WW = 276, WB = 442;

  // 墙：夜色下压暗的深木
  const wg = g.createLinearGradient(0, WY, 0, WB);
  wg.addColorStop(0, "#4A3320");
  wg.addColorStop(1, "#2E1F14");
  g.fillStyle = wg;
  rr(g, WX, WY, WW, WB - WY, 7);
  g.fill();

  // 木板横纹
  g.strokeStyle = "rgba(18,10,6,.30)";
  g.lineWidth = 1.2;
  for (let y = WY + 22; y < WB - 6; y += 26) {
    g.beginPath(); g.moveTo(WX + 3, y); g.lineTo(WX + WW - 3, y); g.stroke();
  }

  // 屋顶：不对称的斜顶，比对称三角更像"自己搭的"
  g.fillStyle = "#1E130C";
  g.beginPath();
  g.moveTo(38, WY + 10);
  g.lineTo(WX + WW * 0.46, 152);
  g.lineTo(366, WY + 10);
  g.closePath();
  g.fill();
  // 月光勾一条边，屋顶才不糊进夜空
  g.strokeStyle = "rgba(176,222,190,.26)";
  g.lineWidth = 2;
  g.beginPath();
  g.moveTo(38, WY + 10);
  g.lineTo(WX + WW * 0.46, 152);
  g.stroke();
  // 屋檐
  g.fillStyle = "#2A1B11";
  rr(g, 32, WY + 6, 372, 12, 5);
  g.fill();

  // 窗：暖黄，里面有一盏灯。窗光轻微呼吸
  const fl = 0.86 + 0.14 * Math.sin(T * 3.1);
  g.fillStyle = "rgba(255,203,107," + (0.92 * fl).toFixed(3) + ")";
  rr(g, 104, 300, 62, 50, 6); g.fill();
  g.fillStyle = "rgba(255,168,70," + (0.55 * fl).toFixed(3) + ")";
  rr(g, 118, 318, 34, 32, 4); g.fill();
  g.strokeStyle = "#3A2415"; g.lineWidth = 4;
  rr(g, 104, 300, 62, 50, 6); g.stroke();
  g.beginPath(); g.moveTo(135, 300); g.lineTo(135, 350); g.stroke();
  g.beginPath(); g.moveTo(104, 325); g.lineTo(166, 325); g.stroke();
  // 窗光在地面的投影
  g.fillStyle = "rgba(255,190,96,.07)";
  g.beginPath(); g.ellipse(135, 454, 48, 9, 0, 0, 6.283); g.fill();

  // 门洞（暗）
  g.fillStyle = "#1A1008";
  rr(g, 244, 318, 76, 124, 5); g.fill();

  // 门帘：**open 是掀开的程度**。0 = 关着，1 = 全开露出里面。
  // 这里是"家里有人"的证据 —— 帘子一动，门口就从背景变成了场景。
  const lift = 6 + open * 118;      // 全开时整块帘子升到门框顶上
  g.save();
  rr(g, 244, 318, 76, 124, 5);
  g.clip();
  // 里面：**先铺一层暗底，再打光。** 只铺暖光的话，门洞是一块平的亮黄方块，
  // 读起来像贴在墙上的黄纸，而不是"一个能走进去的地方"。
  g.fillStyle = "#241608";
  g.fillRect(244, 318, 76, 124);
  const ig = g.createLinearGradient(0, 318, 0, 442);
  ig.addColorStop(0, "rgba(255,214,140," + (0.10 + open * 0.55).toFixed(3) + ")");
  ig.addColorStop(0.55, "rgba(255,186,96," + (0.22 + open * 0.58).toFixed(3) + ")");
  ig.addColorStop(1, "rgba(255,150,44," + (0.34 + open * 0.52).toFixed(3) + ")");
  g.fillStyle = ig;
  g.fillRect(244, 318, 76, 124);
  // 门帘本体：**底边是波浪形，而且一直在轻轻摆。**
  // 一块方方正正的矩形读作"木门"，只有布才会被风吹成那样。
  // 这是门口画面里唯一一直在动的东西 —— 有它，场景才不是一张图。
  const bh2 = Math.max(4, 124 - lift);
  const flap = 1.8 + Math.sin(T * 1.7) * 1.2;
  g.fillStyle = "#5A3B22";
  g.beginPath();
  g.moveTo(242, 318);
  g.lineTo(322, 318);
  for (let x = 322; x >= 242; x -= 6) {
    g.lineTo(x, 318 + bh2 + Math.sin(x * 0.19 + T * 2.1) * flap);
  }
  g.closePath();
  g.fill();
  // 褶皱
  g.fillStyle = "rgba(20,12,6,.26)";
  for (let i = 0; i < 4; i++) {
    const fx = 250 + i * 18;
    g.fillRect(fx, 320, 3, Math.max(4, bh2 - 2 + Math.sin(fx * 0.19 + T * 2.1) * flap));
  }
  g.restore();
  g.strokeStyle = "#33200F"; g.lineWidth = 4;
  rr(g, 244, 318, 76, 124, 5); g.stroke();

  // 门口的台阶和草垫
  g.fillStyle = "#3A2919";
  rr(g, 232, 440, 100, 10, 4); g.fill();
  g.fillStyle = "#4C5B33";
  rr(g, 258, 448, 50, 8, 4); g.fill();

  // 门牌
  g.fillStyle = "#6B4A2A";
  rr(g, 250, 284, 64, 21, 4); g.fill();
  g.fillStyle = "rgba(255,225,170,.82)";
  g.font = "bold 12px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
  g.textAlign = "center"; g.textBaseline = "middle";
  g.fillText("爪 队", 282, 295);
}

/* ---------- 头顶气泡 ---------- */
function drawBubble(g, x, y, text, alpha) {
  if (alpha <= 0.01) return;
  g.font = "13px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
  const tw = g.measureText(text).width;
  const bw = tw + 26, bh = 31;
  const bx = Math.max(8, Math.min(W - bw - 8, x - bw / 2));
  const by = y - bh;

  g.globalAlpha = alpha;
  g.fillStyle = "rgba(11,24,19,.92)";
  rr(g, bx, by, bw, bh, 10); g.fill();
  g.strokeStyle = "rgba(185,240,106,.40)";
  g.lineWidth = 1.4;
  rr(g, bx, by, bw, bh, 10); g.stroke();
  g.beginPath();
  g.moveTo(x - 5, by + bh - 1);
  g.lineTo(x + 5, by + bh - 1);
  g.lineTo(x, by + bh + 7);
  g.closePath();
  g.fillStyle = "rgba(11,24,19,.92)";
  g.fill();
  g.fillStyle = "#EAF6E2";
  g.textAlign = "center";
  g.textBaseline = "middle";
  g.fillText(text, bx + bw / 2, by + bh / 2 + 1);
  g.globalAlpha = 1;
}

function drawSelect(g) {
  const d = S.door;
  const T = d.t;
  const lv = d.leaveT;
  const picked = d.pick;

  const HZ = 442;                                   // 地平线
  // **门要在人跑到一半时就开。** 0.70 才开的话，跑到门口那一刻门还是关的，
  // 读起来是"它站在门口发呆"。0.45 起开 → 撞上跑动中段，画面里"门为它让开"。
  const doorOpen = picked >= 0 ? Math.min(1, Math.max(0, (lv - 0.45) / 0.42)) : 0;

  // ---------- 夜空 ----------
  const sky = g.createLinearGradient(0, 0, 0, HZ + 10);
  sky.addColorStop(0, "#0A1520");
  sky.addColorStop(0.52, "#12232A");
  sky.addColorStop(1, "#1A3029");
  g.fillStyle = sky;
  g.fillRect(0, 0, W, H);

  // 星：用 hash 不抖。Math.random 每帧变，整片星空会闪成噪点
  for (let i = 0; i < 54; i++) {
    const x = hash(i * 7 + 1) * W;
    const y = hash(i * 13 + 5) * 330;
    const tw = Math.sin(T * 1.3 + i * 0.9) * 0.5 + 0.5;
    g.fillStyle = "rgba(214,238,226," + (0.10 + 0.40 * tw).toFixed(3) + ")";
    g.fillRect(x, y, 1.7, 1.7);
  }

  // 月亮
  g.fillStyle = "rgba(226,240,214,.86)";
  g.beginPath(); g.arc(816, 94, 29, 0, 6.283); g.fill();
  g.fillStyle = "rgba(226,240,214,.045)";
  g.beginPath(); g.arc(816, 94, 74, 0, 6.283); g.fill();

  // ---------- 远树剪影 ----------
  g.fillStyle = "#0E2820";
  for (let i = 0; i < 12; i++) {
    const x = i * 86 + (hash(i * 3) - 0.5) * 44;
    const h = 88 + hash(i * 11) * 80;
    const w = 38 + hash(i * 17) * 28;
    g.beginPath();
    g.moveTo(x, HZ + 6);
    g.lineTo(x + w * 0.5, HZ + 6 - h);
    g.lineTo(x + w, HZ + 6);
    g.closePath();
    g.fill();
  }
  g.fillStyle = "rgba(9,24,20,.50)";
  g.fillRect(0, HZ - 10, W, 16);

  // ---------- 地面 ----------
  const gr = g.createLinearGradient(0, HZ, 0, H);
  gr.addColorStop(0, "#274230");
  gr.addColorStop(0.34, "#1C3124");
  gr.addColorStop(1, "#111A14");
  g.fillStyle = gr;
  g.fillRect(0, HZ, W, H - HZ);

  // 草尖：轻微摆动，六只站着的地方才有"风"
  g.strokeStyle = "rgba(122,182,122,.15)";
  g.lineWidth = 1.4;
  for (let i = 0; i < 120; i++) {
    const x = hash(i * 5 + 2) * W;
    const y = HZ + 8 + hash(i * 9 + 7) * (H - HZ - 12);
    const sw = Math.sin(T * 1.1 + i) * 2.4;
    g.beginPath();
    g.moveTo(x, y);
    g.quadraticCurveTo(x + sw * 0.5, y - 5, x + sw, y - 9);
    g.stroke();
  }

  // ---------- 萤火虫 ----------
  // 上半屏原本 40% 是空天（CR-028 记过的老问题）。不放远山 —— 那会把视线拉远；
  // 放几只慢飘的萤火，视线留在门口，同时画面有了"晚上"的温度。
  for (let i = 0; i < 9; i++) {
    const bx = 240 + hash(i * 23 + 7) * 680;
    const by = 170 + hash(i * 31 + 3) * 220;
    const ph = T * 0.55 + i * 2.1;
    const fx = bx + Math.sin(ph) * 24;
    const fy = by + Math.cos(ph * 0.8) * 13;
    const a = 0.30 + 0.70 * Math.abs(Math.sin(ph * 1.5));
    const r = 8 + Math.sin(ph * 2.6) * 1.6;
    const fgl = g.createRadialGradient(fx, fy, 0, fx, fy, r);
    fgl.addColorStop(0, "rgba(216,255,152," + (0.50 * a).toFixed(3) + ")");
    fgl.addColorStop(0.45, "rgba(196,246,120," + (0.16 * a).toFixed(3) + ")");
    fgl.addColorStop(1, "rgba(196,246,120,0)");
    g.fillStyle = fgl;
    g.beginPath(); g.arc(fx, fy, r, 0, 6.283); g.fill();
  }

  // ---------- 小屋 ----------
  drawHut(g, T, doorOpen);

  // ---------- 门光：门开了会更亮。这是"要出门了"的唯一提示 ----------
  const glow = 0.5 + 0.5 * doorOpen;
  const lg = g.createRadialGradient(DOOR.x, HZ - 12, 6, DOOR.x, HZ + 18, 250);
  lg.addColorStop(0, "rgba(255,206,120," + (0.44 * glow).toFixed(3) + ")");
  lg.addColorStop(0.44, "rgba(255,186,96," + (0.16 * glow).toFixed(3) + ")");
  lg.addColorStop(1, "rgba(255,170,80,0)");
  g.fillStyle = lg;
  g.fillRect(0, HZ - 180, 660, 350);

  // ---------- 带回来的果子 ----------
  // 这是"出门有产出"的唯一视觉证据。家园还没做，所以先堆在屋前 ——
  // 一堆会变多的东西，比一个数字更能让人想"再来一趟"。
  // 分四档而不是按数量逐颗画：60 个的时候画 60 颗就是一片红点。
  // 底下必须有个筐：散在地上的果子读作"掉的"，装进筐才读作"攒的"。
  {
    const n = S.home.loot;
    const cnt = [0, 3, 5, 7][n <= 0 ? 0 : n < 20 ? 1 : n < 60 ? 2 : 3];
    if (cnt > 0) {
      const bx = 202, by = 516;
      // 筐身（上宽下窄）
      g.fillStyle = "#6E4926";
      g.beginPath();
      g.moveTo(bx - 24, by - 12);
      g.lineTo(bx + 24, by - 12);
      g.lineTo(bx + 18, by + 2);
      g.lineTo(bx - 18, by + 2);
      g.closePath();
      g.fill();
      g.strokeStyle = "#3E2814";
      g.lineWidth = 1.8;
      g.stroke();
      // 两道编织纹
      g.strokeStyle = "rgba(180,130,74,.55)";
      g.lineWidth = 1.4;
      for (const ox of [-11, 11]) {
        g.beginPath();
        g.moveTo(bx + ox, by - 10);
        g.lineTo(bx + ox * 0.82, by);
        g.stroke();
      }
      // 筐口
      g.fillStyle = "#8E6038";
      rr(g, bx - 26, by - 16, 52, 7, 3.5);
      g.fill();
      g.strokeStyle = "#3E2814";
      g.lineWidth = 1.6;
      rr(g, bx - 26, by - 16, 52, 7, 3.5);
      g.stroke();

      // 果子：hash 散布而不是均分圆周。
      // 均分排成一个环，8 颗红的挤在一起读成一朵花 —— 筐里的东西应该是乱的。
      for (let i = 0; i < cnt; i++) {
        const rx = bx + (hash(i * 7 + 3) - 0.5) * 46;
        const ry = by - 16 - hash(i * 11 + 5) * 13 - (i > 3 ? 7 : 0);
        const rr2 = 5.6 + hash(i * 13 + 1) * 2.0;
        g.fillStyle = hash(i * 5 + 9) > 0.45 ? "#E4694C" : "#D9553F";
        g.beginPath(); g.arc(rx, ry, rr2, 0, 6.283); g.fill();
        g.strokeStyle = "#8E3A2A";
        g.lineWidth = 1.4;
        g.beginPath(); g.arc(rx, ry, rr2, 0, 6.283); g.stroke();
        g.fillStyle = "rgba(255,235,200,.85)";
        g.beginPath(); g.arc(rx - rr2 * 0.32, ry - rr2 * 0.38, rr2 * 0.28, 0, 6.283); g.fill();
        g.fillStyle = "#6FAE5A";
        g.beginPath(); g.ellipse(rx + rr2 * 0.5, ry - rr2 * 0.85, 2.6, 1.4, -0.6, 0, 6.283); g.fill();
      }
    }
  }

  // ---------- 六只 ----------
  // 按 y 排序：靠前的后画，才不会出现"后面那只压住前面那只的脚"
  const order = HEROES.map((H, i) => i).sort((a, b) => DOOR_SLOTS[a].y - DOOR_SLOTS[b].y);
  const react = Math.min(1, Math.max(0, (lv - 0.48) / 0.42));   // 落选反应强度

  for (const i of order) {
    const H = HEROES[i];
    const M = MOODS[H.id] || MOODS.cat;
    const slot = DOOR_SLOTS[i];
    const hov = S.hover === i && picked < 0;
    const isPick = picked === i;
    const isIdle = picked >= 0 && picked !== i;

    let x = slot.x, y = slot.y;
    let sc = 1, alpha = 1, sq = 0, face = -1;
    let wMul = 1, hMul = 1;      // 牛"趴下"不是压扁，是摊开

    // 待机呼吸（六只相位错开，不同步浮动才像活物）
    y -= Math.sin(T * 1.7 + i * 1.3) * 1.5;
    if (hov) { sc = 1.06; y -= 2; }

    if (isPick) {
      if (lv < 0.22) {
        // 蓄力
        sq = Math.sin((lv / 0.22) * Math.PI) * 0.55;
      } else if (lv < 0.84) {
        // 跑向门口
        const k = (lv - 0.22) / 0.62;
        // **跑动末段就开始淡出。** 它最后会停在门洞正中（x=282，门 244..320），
        // 全不透明的话正好把门糊死 —— 画面上是"一只兔子贴在门上"。
        // 0.62 起淡出，跑到门口时已经半只身子在门里。
        alpha = 1 - Math.max(0, (k - 0.62) / 0.38) * 0.55;
        const e = k * k * (3 - 2 * k);
        const hop = M.leave === "hop" ? Math.abs(Math.sin(k * 12)) * 16
                  : M.leave === "plod" ? 0
                  : Math.abs(Math.sin(k * 15)) * 8;
        x = slot.x + (DOOR.x - slot.x) * e;
        y = slot.y + (DOOR.y - slot.y) * e - hop;
        face = 1;                                   // 门在左边？不，门在 x=282，六只在 392 起 → 往左跑
        face = -1;
        sq = Math.abs(Math.sin(k * 15)) * 0.10;
        // 跑法就是性格：plod 走得慢（用非线性位置）
        if (M.leave === "plod") {
          const slow = k * k;                       // 慢起，越走越急
          x = slot.x + (DOOR.x - slot.x) * slow;
          y = slot.y + (DOOR.y - slot.y) * slow;
        }
      } else {
        // 进门
        const k = Math.min(1, (lv - 0.84) / 0.20);
        x = DOOR.x + 14; y = DOOR.y;      // 偏右 14px：门洞左半边才露得出来
        alpha = 1 - k;
        sc = 1 - k * 0.30;
        face = -1;
      }
    }

    if (isIdle) {
      sc = 1 - 0.06 * react;
      alpha = 1 - 0.10 * react;
      if (M.stayAct === "follow") {
        x = slot.x - 42 * react;                    // 追到门口
        y = slot.y + 4 * react;
      } else if (M.stayAct === "turn") {
        face = react > 0.45 ? 1 : -1;               // 扭头背对
      } else if (M.stayAct === "lie") {
        // **趴下不是压扁。** squash 只压 14%，读起来是"蹲了一下"。
        // 真正趴下是横向摊开、纵向塌掉 —— 用 w/h 比值，不用 squash。
        wMul = 1 + 0.20 * react;
        hMul = 1 - 0.46 * react;
      } else if (M.stayAct === "eat") {
        sq = Math.sin(T * 6) * 0.05;                // 还在吃
      } else if (M.stayAct === "droop") {
        y += 5 * react;                             // 缩下去
      } else if (M.stayAct === "hide") {
        // 影狐：**真的退半步**（says one thing and does it）。
        // 只调 alpha 的话，台词写着"往后退了半步"，画面上它一寸没动。
        x = slot.x + 34 * react;
        alpha = 1 - 0.66 * react;
      }
    }

    // 脚下的高亮圈
    if (hov) {
      g.strokeStyle = "rgba(185,240,106,.50)";
      g.lineWidth = 2;
      g.beginPath(); g.ellipse(x, y + 2, 42, 9, 0, 0, 6.283); g.stroke();
    }

    const dw = H.w * 1.82 * sc * wMul;
    const dh = H.h * 1.82 * sc * hMul;
    // alpha 必须走 o.alpha —— drawPet 内部会反复改 globalAlpha，外面设的会被清掉
    // 门口的肚子跟着 S.belly 走：中途 ESC 回来会看到它们饿着，收工回来是圆的
    drawPet(g, x, y, dw, dh, H, face, {
      squash: sq, alpha: alpha,
      belly: 0.18 + 0.82 * clamp(S.belly / 100, 0, 1),
      mood: bellyTier() === 0 ? 1 : bellyTier() === 1 ? 0.2 : 0,
    });

    // 名字（脚下）。不是卡片标题 —— 名字放在脚边，读作"它站在那"。
    // **落选的也要留名字**：上一版一到 0.6 就藏名，结果画面变成"四只无名怪"
    if (true) {
      g.globalAlpha = alpha * (hov ? 1 : 0.72);
      g.fillStyle = hov ? "#D8F98C" : "#CFE6CE";
      g.font = (hov ? "bold " : "") + "14px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
      g.textAlign = "center"; g.textBaseline = "middle";
      g.fillText(H.name, x, y + 24);
      g.globalAlpha = 1;
    }

    // 台词。**相邻两只必须错开高度**：狗追到门口时会挤在猫旁边，
    // 两条气泡同高就是一团糊字。按 i 的奇偶分两条道。
    const bubY = y - dh - 16 - (i % 2) * 36;
    if (hov) {
      drawBubble(g, x, bubY, M.pick, 1);
    } else if (isPick) {
      const ba = lv < 0.70 ? 1 : Math.max(0, 1 - (lv - 0.70) / 0.18);
      drawBubble(g, x, bubY, M.pick, ba);
    } else if (isIdle && react > 0.55 && M.stay !== "") {
      drawBubble(g, x, bubY, M.stay, Math.min(1, (react - 0.55) / 0.3) * 0.92);
    }
  }

  // ---------- 标题 ----------
  g.textAlign = "center"; g.textBaseline = "middle";

  // 顶部压一层暗，标题才不糊在星上
  const tg = g.createLinearGradient(0, 0, 0, 130);
  tg.addColorStop(0, "rgba(8,16,22,.62)");
  tg.addColorStop(1, "rgba(8,16,22,0)");
  g.fillStyle = tg;
  g.fillRect(0, 0, W, 130);

  g.fillStyle = "#F2FBEC";
  g.font = "bold 30px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
  g.fillText("今天带谁出门？", W / 2, 52);

  g.fillStyle = "rgba(198,226,198,.62)";
  g.font = "13px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
  g.fillText(S.progress > 0
    ? ("走到第 " + (S.progress + 1) + " 关 · 一只出门，五只看家")
    : "六只都在等 · 一只出门，五只看家", W / 2, 84);

  if (S.home.loot > 0) {
    g.fillStyle = "rgba(255,216,107,.70)";
    g.font = "12px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
    g.fillText("屋里攒了 " + S.home.loot + " 个果子" +
              (S.home.runs > 1 ? "  ·  第 " + (S.home.runs + 1) + " 趟" : ""), W / 2, 106);
  }

  // ---------- 底部提示 ----------
  g.fillStyle = "rgba(206,232,206,.44)";
  g.font = "13px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
  g.fillText(picked >= 0 ? "门在身后合上了。" : "1–6 或点一只 · 出门前想清楚带谁", W / 2, H - 26);
}

/* ============================================================================
   17. 主循环
   ========================================================================== */

function checkGoal() {
  const st = curStage();
  if (S.killed < S.total) return false;
  if (st.goal === "limit") return S.stat.made <= st.ballLimit;
  if (st.goal === "chain") return S.stat.maxHolds >= st.chain;
  if (st.goal === "bank")  return S.stat.bankHolds >= st.bank;
  if (st.goal === "collect") return S.food >= st.collect;
  if (st.goal === "intact")  return S.stat.burst === 0;
  if (st.goal === "nohit")   return S.stat.hits === 0;
  return true;
}

function goalFailWhy() {
  const st = curStage();
  if (st.goal === "chain") return "人都送走了，但没有一颗球装够 " + st.chain + " 只（最大 x" + S.stat.maxHolds + "）";
  if (st.goal === "bank")  return "人都送走了，但从营地过的只有 " + S.stat.bankHolds + " 只（要 " + st.bank + " 只）";
  if (st.goal === "collect") return "人都送走了，但收成只有 " + S.food + "（要 " + st.collect + "）—— 火坑 ×2 才是正路";
  if (st.goal === "intact")  return "人都送走了，但崩了 " + S.stat.burst + " 颗球（一次都不许）";
  if (st.goal === "nohit")   return "人都送走了，但挨了 " + S.stat.hits + " 下（一次都不许）";
  return "人都送走了，但用了 " + S.stat.made + " 颗球（只给 " + st.ballLimit + " 颗）";
}

function tick(dt) {
  S.t += dt;

  if (S.hitStop > 0) {
    S.hitStop = Math.max(0, S.hitStop - dt);
    dt *= 0.28;   // 命中顿帧：只在撞击那一瞬慢下来，不用全局慢放
  }

  // ---------- 门口动画 ----------
  // 只在 select 阶段走。leaveT 到 1.62 才真正 beginRun ——
  // 这 1.62 秒是"其余五只的反应"唯一的存在时间。
  if (S.phase === "select") {
    S.door.t += dt;
    if (S.door.pick >= 0) {
      S.door.leaveT += dt;
      if (S.door.leaveT >= 1.62) {
        S.heroIdx = S.door.pick;
        S.door.pick = -1;
        S.door.leaveT = 0;
        beginRun(S.progress);
      }
    }
  }

  if (S.phase === "play") {
    S.playT += dt;
    updatePlayer(dt);
    for (const f of S.foes) updateFoe(f, dt);
    updateShots(dt);
    updateBalls(dt);
    updateShocks(dt);
    updateFoeShots(dt);

    // ---- 台词 ----
    // 三个触发点各自只响一次/关。挑的都是"玩家会停一下"的瞬间：
    // 第一颗球滚出去、一球卷走三个、挨了一下。
    if (!S.say.fired.first && S.stat.made >= 1) { S.say.fired.first = true; sayLine("first"); }
    if (!S.say.fired.big && S.stat.maxHolds >= 3) { S.say.fired.big = true; sayLine("big"); }
    if (S.say.life > 0) { S.say.t += dt; S.say.life -= dt; }

    // 清掉死亡的敌人
    let w = 0;
    for (let i = 0; i < S.foes.length; i++) if (!S.foes[i].dead) S.foes[w++] = S.foes[i];
    S.foes.length = w;

    /* ---- 波次推进 ----
       不是"清完才刷"，是"剩 1 只就刷"。理由：最后一只常常站在高台上，
       玩家得爬两层、糊三下、再推一趟 —— 那 20 秒里没有任何决策，
       只有赶路。推球游戏最不该有的就是赶路。

       BOSS 波是例外，必须**清干净**才开场：BOSS 和残兵一起上是夹击，
       玩家两边都要防，那时候他想的就不是"这球怎么推"了。 */
    S.waveT += dt;
    const lastWave = S.wave >= WAVES.length - 1;
    if (!lastWave && S.waveGap <= 0) {
      const nextWv = WAVES[S.wave + 1] || [];
      const nextBoss = nextWv.some(sp => sp.foe === "boss");
      const alive = S.foes.length;
      const trigger = nextBoss ? alive === 0 : alive <= 1;
      // 3.5 秒的呼吸：一球卷三只会瞬间清场，不缓一下的话玩家还没看清
      // 数字就进下一波了，节奏上是"被推着走"，不是"自己在推"。
      if (trigger && S.waveT > 3.5) S.waveGap = nextBoss ? 1.6 : 1.1;
    }
    if (S.waveGap > 0) {
      S.waveGap -= dt;
      if (S.waveGap <= 0) spawnWave(S.wave + 1);
    }

    // 收工判定：最后一波也刷完了、场上没人、也没有还在滚的球（球里装着人）
    const allSpawned = S.wave >= WAVES.length - 1 && S.waveGap <= 0;
    if (allSpawned && S.foes.length === 0 && S.balls.length === 0 && S.phase === "play") {
      if (checkGoal()) {
        S.phase = "clear";
        S.food += 3;   // 清场奖励
        recordClear(S.stage);   // 给主界面解锁用的一笔账
        // ---- 一趟的账 ----
        // loot 累加、倍率涨一档、肚子掉一档。**重打同一关不会重复计**，
        // 因为只有 checkGoal 通过（真的过关）才走到这里，失败重打时 S.food 是 0。
        S.trip.loot += S.food;
        S.trip.stages += 1;
        S.trip.multi = Math.min(2, 1 + 0.15 * S.trip.stages);
        S.belly = Math.max(0, S.belly - 16);
        const rk = rate();
        const ORD2 = { B: 1, A: 2, S: 3 };
        const idx = S.stage;
        if (!S.best[idx] || ORD2[rk] > ORD2[S.best[idx]]) S.best[idx] = rk;
        S.progress = Math.max(S.progress, S.stage + 1);
        saveProgress();
        addText(W / 2, 250, "这一屏清干净了", "#FFE9B0", 32, 2.2);
      } else {
        S.phase = "fail";
        S.failWhy = goalFailWhy();
      }
    }

    // 死局：限球关额度用完、场上没球、还有人没送走 —— 这局没救了。
    // 直接判负比让人干等着好，留一个"还能翻"的假象最伤。
    if (S.phase === "play" && curStage().goal === "limit") {
      const st = curStage();
      const alive = S.foes.length;
      if (st.ballLimit - S.stat.made <= 0 && S.balls.length === 0 && alive > 0) {
        S.phase = "fail";
        S.failWhy = "球用完了，还有 " + alive + " 只没送走";
      }
    }
  }

  // 通关面板自动推进。**从 3 秒放长到 5.5 秒**：多出来的时间是为了让人看清
  // "这一趟攒了多少 × 多少倍"——不读那个数字，"贪一关"就没分量。
  // 鼠标停在按钮上时暂停：他正在读，别替他做决定。
  if (S.phase === "clear" && !S.aim && S.hoverBtn < 0) {
    S.clearT += dt;
    if (S.clearT > 5.5) nextLevel();
  }

  tickFx(dt);

  // 边沿输入在这一帧已经被所有人消费过了，清掉。
  // 不清的话，一个 keydown 会在后续每一帧都触发一次。
  S.press = {};
}

/* 结算卡片与两个按钮的几何。**绘制和点击判定共用这一份** ——
 * 门口那六只踩过一次"画一遍算一遍坐标、判定再算一遍"的坑，改布局必错开。 */
const CARD_Y = 40, CARD_H = 520;
const BTN_Y = CARD_Y + 444, BTN_W = 210, BTN_H = 44, BTN_GAP = 28;
function settleBtns() {
  const cx = W / 2;
  return {
    cont: { x: cx - BTN_W - BTN_GAP / 2, y: BTN_Y, w: BTN_W, h: BTN_H },
    home: { x: cx + BTN_GAP / 2, y: BTN_Y, w: BTN_W, h: BTN_H },
  };
}
function inRect(p, r) {
  return p.x >= r.x && p.x <= r.x + r.w && p.y >= r.y && p.y <= r.y + r.h;
}

function render() {
  const g = ctx;
  g.save();

  // 震屏
  if (S.shake > 0.4) {
    g.translate(rand(-S.shake, S.shake) * 0.4, rand(-S.shake, S.shake) * 0.4);
  }

  drawForest(false);
  drawLevel();
  // 前景压在地面之后（它吃掉草皮下沿）、单位之前（绝不挡角色和球）。
  // 顺序错了会直接毁掉玩法可读性：草挡住球，玩家就不知道球落没落地。
  drawForeground(g);

  if (S.phase === "play" || S.phase === "clear" || S.phase === "fail") {
    // 预测线画在关卡之上、单位之下：它属于"地形信息"，不属于"角色"
    drawShocks(g);
    if (S.phase === "play") drawAim(g);

    // 按 y 排序：后面的先画，前面的盖住后面的
    const units = [];
    for (const f of S.foes) units.push({ y: f.y, d: () => drawFoe(g, f) });
    for (const b of S.balls) units.push({ y: b.y, d: () => drawBall(g, b) });
    if (S.p && !S.p.dead) units.push({ y: S.p.y, d: () => {
      const p = S.p, H = HEROES[p.hero];
      if (p.invT > 0 && Math.floor(S.t * 20) % 2 === 0) {
        // 无敌闪烁：半透明，不是消失 —— 消失会让人以为死了
        g.globalAlpha = 0.45;
      }

      /* ---- 施法动作 ----
         立绘是静态站姿（还有一半是正脸），光靠"闪白"根本读不出在出手。
         这里用**以脚为轴的切变**做前倾/后坐：
           0 → 0.28  后坐蓄力（往后仰，越仰越慢）
           0.28 → 1  前冲（整个人朝施法方向甩出去，再落回站姿）
         切变比旋转好：旋转会把脚也转走，人就浮起来了；
         切变脚在原地不动，只有上身往前压 —— 那才像"使劲"。

         代码图形版和贴图版都走这一层（包在 drawPet 外面），
         所以以后换了美术也不用再改一次动作。 */
      const ck = p.castAnim > 0 ? 1 - p.castAnim / CAST_T : -1;
      let lean = 0;
      if (ck >= 0) {
        lean = ck < 0.28 ? -(ck / 0.28) : Math.pow(1 - (ck - 0.28) / 0.72, 1.5);
      }
      // 推球后坐：和施法方向相反的小幅平移
      const pb = p.pushBack > 0 ? Math.sin((p.pushBack / 0.16) * Math.PI) : 0;
      const dir = p.castAnim > 0 ? (p.castDir || p.face) : p.face;

      g.save();
      g.translate(-p.face * pb * 7, 0);

      /* 不做残影。试过一版"身后留半透明影子"，截图里读起来就是两只宠物，
         玩家第一反应是"出 bug 了"，不是"它在冲"。动效宁缺勿滥。 */
      if (lean !== 0) {
        /* 位移 + 切变都以脚为轴：脚钉在地上，只有上身朝 dir 甩出去。
         *
         * **切变系数必须乘 dir。** 上一版的 -lean*0.52 是常量 ——
         * 向右施法时上半身往右压（对），向左施法时身体虽然整体左移了，
         * 上半身却还是被往右推：读起来就是"人往左冲、脸朝右看"。
         */
        g.translate(p.x + dir * lean * p.w * 0.50, p.y);
        g.transform(1, 0, -lean * 0.56 * dir, 1, 0, 0);
        g.translate(-p.x, -p.y);
      }
      // 朝向也走 dir：施法这 0.26 秒里，脸的朝向和身体的倾斜必须是同一个数，
      // 分开取（一个 p.face 一个 castDir）就会出现"往左打、转过来看右边"。
      const stepping = p.onGround && p.dashT <= 0 && Math.abs(p.vx) > 40;
      drawPet(g, p.x, p.y, p.w, p.h, H, dir, {
        // 前冲段再压一点：形变比位移更容易读成"发力"，而且不用改立绘
        squash: (p.onGround ? 0 : (p.vy < 0 ? -0.16 : 0.12)) + Math.max(0, lean) * 0.18,
        flash: p.castAnim > 0 && ck > 0.24 && ck < 0.6 ? 0.42 : 0,
        belly: 0.15 + 0.85 * clamp(S.belly / 100, 0, 1),
        mood: bellyTier() === 0 ? 1 : bellyTier() === 1 ? 0.22 : 0,
        stepping: stepping,
        gait: stepping ? p.walkPhase : 0,
      });
      g.restore();
      g.globalAlpha = 1;

      // 出手光：手的位置炸一圈十字光。**画在身前** ——
      // 它同时也是朝向的读数，正脸立绘翻面看不出来，光的方向一眼就看得出来。
      if (ck >= 0.16 && ck < 0.72) {
        const k = (ck - 0.16) / 0.56;
        const hx = p.x + dir * (p.w * 0.5 + k * 16);
        const hy = p.y - p.h * 0.60;
        const rr2 = 8 + k * 15;
        g.globalAlpha = (1 - k) * 0.9;
        // 先画一圈暖色外描边再画白十字：纯白十字在浅绿草地上读不出来
        for (const [col, lw] of [["#FFB43C", 5.4 * (1 - k * 0.5)], ["#FFFFFF", 2.4 * (1 - k * 0.5)]]) {
          g.strokeStyle = col;
          g.lineWidth = lw;
          g.lineCap = "round";
          for (let i = 0; i < 4; i++) {
            const a = i * Math.PI / 2 + 0.78;
            g.beginPath();
            g.moveTo(hx + Math.cos(a) * rr2 * 0.42, hy + Math.sin(a) * rr2 * 0.42);
            g.lineTo(hx + Math.cos(a) * rr2, hy + Math.sin(a) * rr2);
            g.stroke();
          }
        }
        g.fillStyle = "#FFFFFF";
        g.beginPath();
        g.arc(hx, hy, 4 * (1 - k * 0.45), 0, 6.283);
        g.fill();
        g.globalAlpha = 1;
      }

      // 冲撞的方向指示
      if (p.dashT > 0) {
        g.strokeStyle = "rgba(200,245,180,.5)";
        g.lineWidth = 3;
        for (let i = 0; i < 3; i++) {
          g.beginPath();
          g.moveTo(p.x - p.face * (18 + i * 12), p.y - p.h * 0.5 - 4 + i * 5);
          g.lineTo(p.x - p.face * (28 + i * 12), p.y - p.h * 0.5 - 4 + i * 5);
          g.stroke();
        }
      }
    }});

    units.sort((a, b) => a.y - b.y);
    for (const u of units) u.d();

    /* ---- 它说的话，和它的饿 ----
       都画在单位之上、跟着玩家走。挂在 HUD 上就变成"一条状态"，跟着人走才是"它在说"。 */
    if (S.p && !S.p.dead) {
      const p = S.p;

      // 台词气泡。开头 0.14s 弹入、结尾 0.35s 淡出 —— 直接出现/消失像 UI 弹窗
      if (S.say.life > 0) {
        const a = clamp(S.say.life / 0.35, 0, 1) * clamp(S.say.t / 0.14, 0, 1);
        drawBubble(g, p.x, p.y - p.h - 32, S.say.txt, a);
      }

      if (bellyTier() === 0) {
        // 肚子叫：每 4 秒一圈从肚子上扩散出去。纯视觉的"咕"，不用写一个字
        const ph = (S.t % 4) / 4;
        if (ph < 0.26) {
          const k = ph / 0.26;
          g.globalAlpha = (1 - k) * 0.34;
          g.strokeStyle = "#FFCFA8";
          g.lineWidth = 2;
          g.beginPath();
          g.ellipse(p.x, p.y - p.h * 0.34, 12 + k * 28, 8 + k * 19, 0, 0, 6.283);
          g.stroke();
          g.globalAlpha = 1;
        }
        // 饿牌挂在**肚子旁边**，不挂头顶 —— 头顶是台词气泡的地盘，
        // 两样都在上面必然叠成一坨。挂在肚子上语义也对：它表达的是"肚子饿"。
        const bx = p.x - p.face * (p.w * 0.5 + 14);
        const by = p.y - p.h * 0.34 + Math.sin(S.t * 2.2) * 2.5;
        g.globalAlpha = 0.58 + 0.24 * Math.sin(S.t * 3.1);
        g.fillStyle = "rgba(14,26,20,.92)";
        g.beginPath(); g.arc(bx, by, 10, 0, 6.283); g.fill();
        g.strokeStyle = "rgba(255,170,140,.72)";
        g.lineWidth = 1.4;
        g.beginPath(); g.arc(bx, by, 10, 0, 6.283); g.stroke();
        g.fillStyle = "#FFC7A8";
        g.font = "bold 11px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
        g.textAlign = "center";
        g.textBaseline = "middle";
        g.fillText("饿", bx, by + 0.5);
        g.globalAlpha = 1;
      }
    }

    for (const s of S.shots) drawShot(g, s);
    // 敌方弹幕画在单位之上：它比角色快得多，压在角色下面会"从身体里冒出来"
    drawFoeShots(g);

    // 地上的掉落物。每一种长得不一样 —— "惊喜感"的一半来自"一眼认出这是什么"
    for (const d of S.drops) {
      if (d.taken) continue;
      const K = DROP_KINDS[d.kind] || DROP_KINDS.fruit;
      const bob = Math.sin((d.t || 0) * 4 + (d.spin || 0)) * 1.6;
      const dy = d.y + bob;

      // 落地一圈微光，草丛里也能看见
      const glow = g.createRadialGradient(d.x, dy, 1, d.x, dy, 16);
      glow.addColorStop(0, K.ring);
      glow.addColorStop(1, "rgba(255,255,255,0)");
      g.globalAlpha = 0.42;
      g.fillStyle = glow;
      g.beginPath();
      g.arc(d.x, dy, 16, 0, 6.283);
      g.fill();
      g.globalAlpha = 1;

      // 宝箱：金色箱子 + 深色包边 + 中间的锁扣，比其它掉落大一圈。
      // 大一圈是必要的 —— 它需要"被一眼看见"，而不是"被捡到的时候才发现"。
      if (d.kind === "chest") {
        const bw = 26, bh = 20;
        g.globalAlpha = 0.5 + 0.2 * Math.sin((d.t || 0) * 5);
        g.fillStyle = "#FFF3C0";
        g.beginPath();
        g.arc(d.x, dy + 2, 26, 0, 6.283);
        g.fill();
        g.globalAlpha = 1;

        // 箱体
        g.fillStyle = "#C9882E";
        rr(g, d.x - bw / 2, dy - 4, bw, bh, 4);
        g.fill();
        g.strokeStyle = COL.outline;
        g.lineWidth = 2.4;
        g.stroke();
        // 箱盖（半圆顶）
        g.fillStyle = K.color;
        g.beginPath();
        g.moveTo(d.x - bw / 2, dy - 3);
        g.quadraticCurveTo(d.x, dy - 20, d.x + bw / 2, dy - 3);
        g.closePath();
        g.fill();
        g.stroke();
        // 两道包边
        g.strokeStyle = "#8A5A16";
        g.lineWidth = 2.2;
        for (const ox of [-7, 7]) {
          g.beginPath();
          g.moveTo(d.x + ox, dy - 12);
          g.lineTo(d.x + ox, dy + bh - 5);
          g.stroke();
        }
        // 锁扣
        g.fillStyle = "#FFE98A";
        rr(g, d.x - 4, dy - 6, 8, 8, 2);
        g.fill();
        g.strokeStyle = COL.outline;
        g.lineWidth = 1.8;
        g.stroke();
        // 顶盖高光
        g.strokeStyle = "rgba(255,255,255,.8)";
        g.lineWidth = 2;
        g.beginPath();
        g.arc(d.x, dy - 3, bw * 0.34, -2.5, -1.2);
        g.stroke();
        continue;
      }

      if (d.kind === "gem") {
        g.fillStyle = K.color;
        g.beginPath();
        g.moveTo(d.x, dy - 11); g.lineTo(d.x + 8, dy); g.lineTo(d.x, dy + 11); g.lineTo(d.x - 8, dy);
        g.closePath(); g.fill();
        g.fillStyle = "rgba(255,255,255,.75)";
        g.beginPath();
        g.moveTo(d.x, dy - 8); g.lineTo(d.x + 4, dy - 1); g.lineTo(d.x, dy + 2); g.lineTo(d.x - 4, dy - 1);
        g.closePath(); g.fill();
      } else if (d.kind === "air") {
        g.fillStyle = K.color;
        rr(g, d.x - 7, dy - 10, 14, 20, 5);
        g.fill();
        g.fillStyle = "rgba(255,255,255,.8)";
        rr(g, d.x - 3, dy - 6, 4, 10, 2);
        g.fill();
      } else if (d.kind === "heart") {
        g.fillStyle = K.color;
        g.beginPath();
        g.arc(d.x - 5, dy - 3, 5.4, 0, 6.283);
        g.arc(d.x + 5, dy - 3, 5.4, 0, 6.283);
        g.fill();
        g.beginPath();
        g.moveTo(d.x - 10, dy - 1); g.lineTo(d.x, dy + 10); g.lineTo(d.x + 10, dy - 1);
        g.closePath(); g.fill();
      } else if (d.kind === "berry") {
        g.fillStyle = K.color;
        for (const [ox, oy] of [[-5, 2], [5, 2], [0, -5]]) {
          g.beginPath(); g.arc(d.x + ox, dy + oy, 6, 0, 6.283); g.fill();
        }
        g.fillStyle = "rgba(255,255,255,.6)";
        g.beginPath(); g.arc(d.x - 6, dy - 6, 1.8, 0, 6.283); g.fill();
      } else {
        g.fillStyle = K.color;
        g.beginPath(); g.arc(d.x, dy, 7.5, 0, 6.283); g.fill();
        g.fillStyle = "#5DA84E";
        g.beginPath(); g.ellipse(d.x + 3, dy - 7, 5, 2.6, -0.5, 0, 6.283); g.fill();
      }
    }

    // 粒子
    for (const f of S.frags) {
      g.globalAlpha = clamp(f.life / f.max, 0, 1);
      g.fillStyle = f.color;
      g.beginPath();
      g.arc(f.x, f.y, f.r, 0, 6.283);
      g.fill();
    }
    g.globalAlpha = 1;

    // 飘字只在战斗阶段画。结算面板有自己的大字，
    // 两者叠在一起会糊成一团（"空地清干净了"压在"满载而归"上）。
    g.textAlign = "center";
    g.textBaseline = "middle";
    for (const t of (S.phase === "play" ? S.texts : [])) {
      const k = clamp(t.life / t.max, 0, 1);
      g.globalAlpha = k < 0.3 ? k / 0.3 : 1;
      g.font = "bold " + t.size + "px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
      g.lineWidth = 4;
      g.strokeStyle = "rgba(18,26,20,.82)";
      g.strokeText(t.txt, t.x, t.y);
      g.fillStyle = t.color;
      g.fillText(t.txt, t.x, t.y);
    }
    g.globalAlpha = 1;

    // HUD 只在战斗阶段画。结算时压暗层会把它压成两块灰面板，
    // 和中间那张亮白卡片并排，读起来像"两个坏掉的控件"。
    if (S.phase === "play") drawHUD(g);

    // 受伤闪红
    if (S.flash > 0) {
      g.fillStyle = "rgba(255,80,70," + (S.flash * 0.5).toFixed(3) + ")";
      g.fillRect(0, 0, W, H);
    }

    // 结算
    if (S.phase === "clear" || S.phase === "fail") {
      const ok = S.phase === "clear";
      const cx = W / 2;
      const st = curStage();

      // 先整体压暗，再盖一张实心卡片。
      // 只压暗不盖卡片的话，平台木条和敌人会直接穿过结算文字 ——
      // 截图里"造球 4 · 崩开 0"那行正好压在木条上，读不出来。
      //
      // 奶油面板自带奶白底 + 棕描边 + 投影，压暗不用那么重：
      // 压到 0.9 的话，后面那片森林全黑，一张奶白卡片浮在纯黑上，
      // 和主界面那套奶油风断成两个游戏。压到 0.62 还看得见"我在哪一关"。
      const K = hudSkin();
      /* 压暗必须是**两段**：先纯黑压明度，再冷调压色相。
       *
       * 单段半透明色压不掉色相 —— 这是这一版踩到的坑：`rgba(9,12,11,.52)`
       * 单看是中性的，压在第四关的橙黄天空上算出来是 (86,76,61)，一片暖棕，
       * 奶油卡（奶白）浮在上面，整块读成"棕色相框"，和主界面断成两个游戏。
       *
       * 顺序也不能倒：先冷调后黑，橙色被黑白 .35 一提亮，再叠冷色只会更灰；
       * 先黑后冷，黑先把橙压到 (130,97,71)，冷调 .45 一盖，三通道收敛到 ≈(80,71,66)，
       * 才是真的"中性暗"。 */
      g.fillStyle = ok ? "rgba(0,0,0,.35)" : "rgba(14,0,0,.37)";
      g.fillRect(0, 0, W, H);
      g.fillStyle = ok ? "rgba(20,40,60,.45)" : "rgba(60,20,34,.45)";
      g.fillRect(0, 0, W, H);

      const cardY = CARD_Y, cardH = CARD_H;
      creamCard(g, cx - 310, cardY, 620, cardH, 26);

      g.textAlign = "center";
      g.textBaseline = "middle";

      /* 行距是量出来的，不是拍的。
         卡面现在是代码画的 26px 圆角（见 creamCard 的注释：ui-res 那张图
         圆角 150px，铺上来会变成蛋形），内容从 +36 起就完全在圆角内侧；
         最后一行离卡底留 32（按钮底 528 / 卡底 560），不会压描边。 */
      g.fillStyle = K.ink3;
      g.font = "13px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
      g.fillText("第 " + (S.stage + 1) + " / " + LEVELS.length + " 关   ·   " + st.sub, cx, cardY + 36);

      g.fillStyle = K.ink;
      g.font = "bold 25px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
      g.fillText(st.name + "   ·   " + curGoal().name, cx, cardY + 66);

      g.fillStyle = ok ? K.good : K.bad;
      g.font = "bold 16px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
      g.fillText(ok ? "过关" : "没做到", cx, cardY + 96);

      // 评价：只在达标时给。失败了不给评级 —— 评级是奖励，不是羞辱
      if (ok) {
        const rk = rate();
        const rcol = K.cream
          ? (rk === "S" ? "#C0871A" : rk === "A" ? "#3F7D24" : "#7A6A55")
          : (rk === "S" ? "#FFE58A" : rk === "A" ? "#B9F06A" : "#9FC8B4");
        // 星：S 给三颗，A 两颗，B 一颗。**星是"你做到了多少"的读数**，
        // 比一个字母更直觉 —— 字母要靠记住 S/A/B 的顺序。
        const starArt = artOf("ui-star");
        const nStar = rk === "S" ? 3 : rk === "A" ? 2 : 1;
        if (starArt) {
          // 三星整体压在中心偏左，字母接在右边当"读数"。
          // 星和字母都居中排的话，三星 + S 会读成"三颗星 和一个字"两坨东西。
          const mid = cx - 22;
          for (let i = 0; i < 3; i++) {
            const sx = mid + (i - 1) * 34;
            g.globalAlpha = i < nStar ? 1 : 0.20;
            g.drawImage(starArt, sx - 16, cardY + 122, 32, 32);
          }
          g.globalAlpha = 1;
          g.fillStyle = rcol;
          g.font = "bold 22px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
          g.fillText(rk, cx + 52, cardY + 142);
        } else {
          g.fillStyle = rcol;
          g.font = "bold 52px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
          g.fillText(rk, cx, cardY + 142);
        }
      } else {
        g.fillStyle = K.cream ? "#A2492F" : "#FFD3C8";
        g.font = "15px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
        g.fillText(S.failWhy || "饿晕了…", cx, cardY + 134);
      }

      // 数据：两行，第一行是"送走多少"，第二行是"目标那条线打没打到"
      g.fillStyle = K.ink;
      g.font = "bold 15px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
      g.fillText("送走 " + S.killed + " / " + S.total + " 只   ·   用时 " + S.playT.toFixed(1) + "s",
                 cx, cardY + 198);

      let goalLine = "";
      if (st.goal === "limit") goalLine = "用球 " + S.stat.made + " / " + st.ballLimit + " 颗";
      else if (st.goal === "chain") goalLine = "最大一球 x" + S.stat.maxHolds + "（要 " + st.chain + "）";
      else if (st.goal === "bank") goalLine = "从营地走 " + S.stat.bankHolds + " 只（要 " + st.bank + "）";
      else if (st.goal === "collect") goalLine = "收成 " + S.food + " / " + st.collect + "（火坑 ×2）";
      else if (st.goal === "intact") goalLine = "崩开 " + S.stat.burst + " 次（要 0）";
      else if (st.goal === "nohit") goalLine = "挨打 " + S.stat.hits + " 次（要 0）";
      if (goalLine) {
        g.fillStyle = K.ink2;
        g.font = "13px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
        g.fillText(goalLine, cx, cardY + 222);
      }


      // 分隔线
      g.strokeStyle = K.cream ? "rgba(120,92,64,.26)" : "rgba(255,255,255,.10)";
      g.lineWidth = 1;
      g.beginPath();
      g.moveTo(cx - 250, cardY + 172);
      g.lineTo(cx + 250, cardY + 172);
      g.stroke();

      /* ---- 它说 ---- 
         性格不能只活在门口那 1.6 秒。这里是玩家**一定会看**的地方，
         所以那句"邀功 / 求饶"放在这儿，比在战斗中冒泡更有用。 */
      const said = finishSay(ok);
      g.fillStyle = K.cream ? "#8A5716" : "rgba(255,233,176,.92)";
      g.font = "bold 15px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
      g.fillText(HEROES[S.heroIdx].name + "：「" + said + "」", cx, cardY + 280);

      /* ---- 这一趟的账 ---- 
         倍率只有收工才结算，所以这里必须把"现在走能拿多少"写清楚 ——
         不写的话，"累计倍率"就是一个玩家看不见的数字，等于没做。 */
      const gain = Math.round(S.trip.loot * S.trip.multi);
      const nextMulti = Math.min(2, 1 + 0.15 * (S.trip.stages + 1));
      g.fillStyle = K.ink2;
      g.font = "13px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
      g.fillText("这一趟走了 " + S.trip.stages + " 关   ·   攒下 " + S.trip.loot + " 果   ×   " +
                S.trip.multi.toFixed(2) + "   =   " + gain, cx, cardY + 306);

      // 肚子：一条会缩的条 + 一个口语化的档位词。
      // **不给数字** —— 玩家要判断的是"还撑不撑得住"，不是精确到 84 还是 68。
      // 标签放在条的上方左对齐（放左边会孤零零挂在条外面，像没摆好的图片）
      {
        const bw = 220, bx = cx - bw / 2, by = cardY + 336;
        g.fillStyle = K.ink3;
        g.font = "11px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
        g.textAlign = "left";
        g.fillText("肚子   ·   " + ["全饿 —— 冲刺没有了", "半饿", "满饱"][bellyTier()],
                   bx, by);
        g.textAlign = "center";
        const bellyArt = artOf("ui-belly");
        // 高度必须给够。96×52 的胶囊压到 16px 时，整图拉伸会把那圈棕描边
        // 糊成一条实心橙色椭圆 —— 截图里看起来像个"橙色豆子"，不是血条。
        // 20px + 九宫格（按缩放比折角）才能读出"一条胶囊"。
        const barY = by + 8, barH = 20;
        if (bellyArt) {
          drawNine(g, bellyArt, bx, barY, bw, barH, 18);
        } else {
          g.fillStyle = "rgba(255,255,255,.10)";
          rr(g, bx, barY + 7, bw, 6, 3); g.fill();
        }
        const bk = clamp(S.belly / 100, 0, 1);
        g.fillStyle = bellyTier() === 0 ? (K.cream ? "#C0553E" : "#FF9E8E")
                     : bellyTier() === 1 ? (K.cream ? "#D08A22" : "#FFD86B")
                                         : (K.cream ? "#5FA53A" : "#B9F06A");
        rr(g, bx + 7, barY + 5, Math.max(3, (bw - 14) * bk), 10, 5); g.fill();
      }

      // ---- 下一关预告：这是"推关"的关键。人得知道后面还有东西 ----
      // 只留关卡名 + 一句说明。"再往里一关"那行小标题删了 ——
      // 它占掉 22px，而这句话本身没有信息（人当然知道后面还有一关）。
      const last = S.stage + 1 >= LEVELS.length;
      const B = settleBtns();
      if (ok && !last) {
        const nx = LEVELS[S.stage + 1];
        g.fillStyle = K.ink;
        g.font = "bold 18px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
        g.fillText((S.stage + 2) + ". " + nx.name + "   ·   " + nx.sub, cx, cardY + 394);
      } else if (ok && last) {
        g.fillStyle = K.cream ? "#C0871A" : "#FFE58A";
        g.font = "bold 19px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
        g.fillText("八个场地全清干净了", cx, cardY + 394);
        g.fillStyle = K.ink2;
        g.font = "12px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
        g.fillText("这一趟走到底了 —— 收工之后可以换一只再来", cx, cardY + 416);
      } else {
        g.fillStyle = K.cream ? "#A2492F" : "#FFD3C8";
        g.font = "13px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
        g.fillText("换个思路，先卷一个再推   ·   或者今天就到这儿", cx, cardY + 416);
      }

      /* ---- 两个按钮：继续（贪） / 收工（稳） ----
         默认高亮"继续"，因为默认应该是贪 —— 玩家没选的时候，让游戏推着他往前走。
         但两个都得看得见、都得好按，不然"贪"就不是选择，是唯一路径。 */
      const hov = S.hoverBtn === undefined ? -1 : S.hoverBtn;
      /* 按钮用**代码画**，不贴 ui-btn。
       *
       * ui-btn 的源图（btn-go.png 615×96）是一张"出门"专用稿：
       * 右端带 ▶ 箭头、左段有一条竖分隔线。缩到 210×44 之后箭头被压成
       * 一个小三角、分隔线变成一道划痕 —— 看着像图片没切好。
       * 通用按钮要的是"形状 + 描边"，装饰只会添乱。
       *
       * 主次不靠"压暗到看不见"来区分（上一版次按钮 alpha 0.55 + 文字 .40，
       * 在奶白卡上基本读不出"收工回家"四个字）。改成**底色不同**：
       * 主按钮暖黄实心，次按钮奶白空心，两个都清楚，选择才成立。 */
      const drawBtn = (r, hi, main, sub, solid) => {
        const rad = r.h / 2;
        // 贴纸三件套：投影 → 底 → 深棕描边（和面板同一套语言）
        g.fillStyle = "rgba(92,58,28,.22)";
        rr(g, r.x, r.y + 3, r.w, r.h, rad);
        g.fill();

        g.fillStyle = solid ? (hi ? "#F0BC4E" : "#E5C98C") : (hi ? "#FFFBF0" : "#F2E9D6");
        rr(g, r.x, r.y, r.w, r.h, rad);
        g.fill();

        // 上半部一条浅色高光，把"凸起"这件事说清楚
        g.fillStyle = solid ? "rgba(255,236,168,.55)" : "rgba(255,255,255,.75)";
        rr(g, r.x + 5, r.y + 3, r.w - 10, r.h * 0.38, rad * 0.7);
        g.fill();

        g.strokeStyle = hi ? "#6B4A24" : "rgba(107,74,36,.62)";
        g.lineWidth = hi ? 2.6 : 2;
        rr(g, r.x, r.y, r.w, r.h, rad);
        g.stroke();

        g.textAlign = "center";
        g.fillStyle = hi ? "#4A2F10" : "rgba(74,47,16,.78)";
        g.font = "bold 16px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
        g.fillText(main, r.x + r.w / 2, r.y + 17);
        g.fillStyle = hi ? "rgba(74,47,16,.72)" : "rgba(74,47,16,.52)";
        g.font = "10px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
        g.fillText(sub, r.x + r.w / 2, r.y + 33);
      };
      // 默认高亮"继续"：玩家没选的时候，让游戏推着他往里走。但"收工"必须同样好按，
      // 不然"贪"就不是一个选择，而是唯一路径 —— 那样这条机制等于不存在。
      const hiCont = hov === 0 || (hov !== 1);

      if (ok && !last) {
        drawBtn(B.cont, hiCont, "继续深入",
                "倍率变 " + nextMulti.toFixed(2) + (bellyTier() === 0 ? "  ·  它又饿了" : ""), true);
      } else if (ok && last) {
        drawBtn(B.cont, hiCont, "全部通关", "点这里收工", true);
      } else {
        drawBtn(B.cont, hiCont, "重打本关", "R 也行", true);
      }
      drawBtn(B.home, hov === 1, "收工回家", "+ " + gain + " 果  ·  吃饱", false);

      // 提示行
      // 它是"整个画面"的热键，不是卡片内容 —— 放卡片下面。
      // 塞在卡里会骑在下边框的圆角上，读起来像"卡片裂了一条缝"。
      // 颜色也不能沿用卡片内的深棕：现在是压在压暗层上，深棕等于没写。
      // textAlign 必须显式设回 center：上面肚子标签那段把它改成了 left，
      // 之后一直没还原 —— 提示行用 cx 定位就会从中间往右写出去。
      g.textAlign = "center";
      g.fillStyle = "rgba(255,248,232,.66)";
      g.font = "bold 12px 'Microsoft YaHei','PingFang SC','Hiragino Sans GB',system-ui,sans-serif";
      g.fillText(ok && !last ? "回车 / 点击  继续   ·   E  收工回家   ·   ESC 回选人"
                             : "回车 / 点击  重打   ·   E  收工回家   ·   ESC 回选人",
                 cx, cardY + cardH + 24);
    }
  } else {
    drawSelect(g);
  }

  if (S.vignette !== false) {
    // 压暗四边，把视线收回中心
    const vg = g.createRadialGradient(W / 2, H / 2, H * 0.42, W / 2, H / 2, H * 0.95);
    vg.addColorStop(0, "rgba(0,0,0,0)");
    vg.addColorStop(1, "rgba(6,14,10,.42)");
    g.fillStyle = vg;
    g.fillRect(0, 0, W, H);
  }

  g.restore();
}

/* ---------- 鼠标悬停 / 点击 ---------- */
function hitSelect(mx, my) {
  // 判定和绘制共用 DOOR_SLOTS。上一版卡片布局是两边各算一套坐标，
  // 改布局时一定会错开 —— 这次只留一个来源。
  let best = -1, bestD = 1e9;
  for (let i = 0; i < HEROES.length; i++) {
    const sl = DOOR_SLOTS[i];
    const hw = 48, top = sl.y - 104;
    if (mx >= sl.x - hw && mx <= sl.x + hw && my >= top && my <= sl.y + 12) {
      const dd = Math.abs(mx - sl.x);
      if (dd < bestD) { bestD = dd; best = i; }
    }
  }
  return best;
}

/* 选中一只 → 进入出门演出（不是立刻 beginRun）。
 *
 * **为什么要插这 1.6 秒。** 这段的全部内容是"其余五只的反应"，
 * 也是六只第一次显露出性格的地方。一按就进关，这段就白做了，
 * 玩家永远只知道"我选了猫"，不知道"狗想跟来、兔子耳朵垂下去了"。
 *
 * 1.6 秒是一次性的成本，换来的是一个能被截图、被发群的瞬间 ——
 * 这正是 CR-028 §7.3 里"我们一个都没有"的那个东西。
 */
function pickHero(i) {
  if (S.door.pick >= 0) return;      // 演出中，不重入
  if (i < 0 || i >= HEROES.length) return;
  S.door.pick = i;
  S.door.leaveT = 0;
}

function toLocal(ev) {
  const r = cv.getBoundingClientRect();
  return {
    x: (ev.clientX - r.left) * (W / r.width),
    y: (ev.clientY - r.top) * (H / r.height),
  };
}

function onCanvasMove(loc: any): void {
  if (S.phase === "select") S.hover = hitSelect(loc.x, loc.y);
  // 结算面板：指着按钮时不推进倒计时 —— 他正在读，别替他做决定
  if (S.phase === "clear" || S.phase === "fail") {
    const B = settleBtns();
    S.hoverBtn = inRect(loc, B.home) ? 1 : inRect(loc, B.cont) ? 0 : -1;
  }
}

function onCanvasDown(loc: any): void {
  if (S.phase === "select") {
    const i = hitSelect(loc.x, loc.y);
    if (i >= 0) pickHero(i);
    return;
  }
  // 结算界面：只有真的点在按钮上才算数。
  // 上一版是"命中 home 就收工，否则一律 nextLevel" —— 点在卡片外的草地上
  // 也会直接进下一关，玩家会以为"这面板自己跳走了"。
  if (S.phase === "clear" || S.phase === "fail") {
    const B = settleBtns();
    if (inRect(loc, B.home)) { goHome(false); return; }
    if (inRect(loc, B.cont)) { nextLevel(); return; }
  }
}

/* ---------- 启动 ---------- */


/* ============================================================================
   主界面接入（game.html → grove.html）
   ----------------------------------------------------------------------------
   主界面取代了「门口选人」这一站：从家园点「出门」直接带着人开打，
   打完回主界面播「新伙伴加入」。所以这里只需要三条小钩子：

     ① ?from=home&hero=N&stage=K  → 跳过 select，直接 beginRun(K)
     ② 通关时把关卡索引记到 'pawpack.save'.cleared（去重，主界面按它解锁）
     ③ ESC / 收工 / 全清 → 跳回 game.html

   不带 ?from=home 时行为完全不变，旧的门口流程照旧可用。
   ========================================================================== */
/* 无头沙箱里既没有 location 也没有 URLSearchParams —— 降级成"没有参数"，
   那样 from=home 恒为 false，行为跟改造前一模一样。 */
const URLP = (() => {
  try {
    const q = (typeof location !== "undefined" && location.search) ? location.search : "";
    return new URLSearchParams(q);
  } catch (e) {
    return { get() { return null; } };
  }
})();
const FROM_HOME = URLP.get("from") === "home";

/* "收工回主界面"这件事在浏览器和 Cocos 里落点不同：
   浏览器跳 game.html，Cocos 切 Home 场景。所以只留一个钩子。 */
let exitHook: ((kind: string) => void) | null = null;
export function groveSetExitHook(fn: ((kind: string) => void) | null): void {
  exitHook = fn;
}
function groveExit(kind: string): boolean {
  if (exitHook) { exitHook(kind); return true; }
  if (FROM_HOME) { location.href = "game.html"; return true; }
  return false;
}

/* 解锁表：通关数 ≥ at 时，这只到家。必须和 game.html 的 PETS[].at 一致 */
const UNLOCK_AT = { cat: 0, dog: 1, ham: 3, rab: 5, ox: 7, fox: 8 };
const HERO_CN = { cat: "砂糖", dog: "年糕", ham: "团子", rab: "雪团", ox: "豆奶", fox: "星屑" };
const HOME_SAVE_KEY = "pawpack.save";

function readHomeSave() {
  try { return JSON.parse(localStorage.getItem(HOME_SAVE_KEY) || "{}") || {}; }
  catch (e) { return {}; }
}

/** 通关记账 + 顺手报一句"谁到家了" */
function recordClear(idx) {
  const s = readHomeSave();
  const before = new Set(Array.isArray(s.cleared) ? s.cleared : []).size;
  const c = Array.isArray(s.cleared) ? s.cleared.filter(Number.isInteger) : [];
  if (!c.includes(idx)) c.push(idx);
  const after = new Set(c).size;
  s.cleared = c; s.v = 1;
  try { localStorage.setItem(HOME_SAVE_KEY, JSON.stringify(s)); } catch (e) {}

  // 只在"这一关刚好跨过阈值"时报，重打老关卡不会重复弹
  const fresh = Object.keys(UNLOCK_AT)
    .filter(id => UNLOCK_AT[id] > before && UNLOCK_AT[id] <= after);
  if (fresh.length && FROM_HOME) {
    showUnlockTip(fresh.map(id => HERO_CN[id]));
  }
  return fresh;   // 返回这次刚好跨过阈值的那几只（测试与外部复查用）
}

let unlockTipTimer = 0;
function showUnlockTip(names) {
  const el = document.getElementById("unlockTip");
  if (!el) return;
  el.innerHTML = "<b>✦ 新伙伴到家： " + names.join(" · ") + "</b>" +
                 "<span>回主界面见它</span>";
  el.classList.add("on");
  clearTimeout(unlockTipTimer);
  unlockTipTimer = setTimeout(() => el.classList.remove("on"), 3600);
}

if (FROM_HOME) {
  const btn = document.getElementById("toHome");
  if (btn) btn.style.display = "block";
}

/* ---------- Cocos 侧入口 ----------
   原型靠 URL 参数（?from=home&hero=N&stage=K）从 game.html 进来；
   Cocos 里没有 URL，改成显式传参。不传就按存档推。 */
export function groveBoot(hero?: number, stage?: number): void {
  loadProgress();
  resetRun();

  if (typeof hero === "number" && hero >= 0 && hero < HEROES.length) S.heroIdx = hero;

  // 起始关跟着主界面的"第一个没通的关"走 —— 两边用同一份 cleared，不会打架
  const s: any = readHomeSave();
  const done = new Set(Array.isArray(s.cleared) ? s.cleared : []);
  let st = 0;
  for (let i = 0; i < LEVELS.length; i++) { if (!done.has(i)) { st = i; break; } }
  if (typeof stage === "number" && stage >= 0 && stage < LEVELS.length) st = stage;
  S.progress = st;
  beginRun(st);
}

/* ---------- 调试导出 ---------- */
export const GROVE: any = {
  S, HEROES, FOES, GOALS, LEVELS, THEMES,
  resetRun, beginRun, tick, render,
  setupLevel, updatePlayer, updateFoe, updateShots, updateBalls,
  coatFoe, makeBallFrom, burstBall, spawnShot,
  spawnWave, foeFromSpec, updateShocks, hurtPlayer,
  dropChest, dropFrom, DROP_KINDS,
  predictBall, aimFor, ballBudget, checkGoal, rate, goalProgress,
  curStage, curGoal, loadLevel, rampAt, nextLevel, saveProgress,
  hitSelect, pickHero, MOODS, DOOR_SLOTS, VOICE,
  goHome, bellyTier, sayLine, finishSay, settleBtns, inRect,
  recordClear, readHomeSave, FROM_HOME,
  // 注入美术图。**只在调试/截图里用**：正片由 GroveBattle 走 resources.load
  // 拿 ImageAsset 再注进来。导出它，截图脚本才能拍出"有 UI 图"的样子 ——
  // 不导出的话 file:// 打开的 grove.html 永远是代码回退图形，截图和真机对不上。
  setArt: groveSetArt,
  // 模拟按键：既要置"按住"状态，也要置"本帧按下"的边沿。
  // 只置 keys 的话，atk / dash / jump 这三个读边沿的动作全部不触发 ——
  // 表现是"按了没反应"，但按住方向走是正常的，很容易误判成动作逻辑坏了。
  _press(k, v) {
    if (v === false) { S.keys[k] = false; return; }
    if (!S.keys[k]) S.press[k] = true;
    S.keys[k] = true;
  },
  /** _start(角色, 关卡) —— 省略关卡就用当前这一关 */
  _start(hero, stage) {
    S.heroIdx = hero === undefined ? 0 : hero;
    beginRun(stage === undefined ? S.stage : stage);
  },
};

// PLATS / PITS / STUMPS / CAMP 是 let（换屏会整个替换），
// 导出时必须用 getter，否则外面拿到的是第一屏的旧数组 —— 测试会假通过。
Object.defineProperty(GROVE, "PLATS", { get: () => PLATS });
Object.defineProperty(GROVE, "PITS",  { get: () => PITS });
Object.defineProperty(GROVE, "STUMPS", { get: () => STUMPS });
Object.defineProperty(GROVE, "CAMP",  { get: () => CAMP });
Object.defineProperty(GROVE, "WAVES", { get: () => WAVES });
Object.defineProperty(GROVE, "PLAYER_SPAWN", { get: () => PLAYER_SPAWN });
Object.defineProperty(GROVE, "RAMPS", { get: () => RAMPS });
Object.defineProperty(GROVE, "BOUNCERS", { get: () => BOUNCERS });
Object.defineProperty(GROVE, "PORTALS", { get: () => PORTALS });
// 结算卡的几何：按钮/文字都按它排，冒烟断言要拿它判"按钮有没有掉出卡片"，
// 写死 544 那种事干过一次 —— 卡片一加高，断言就变成在验一个不存在的尺寸。
GROVE.CARD = { y: CARD_Y, h: CARD_H, btnY: BTN_Y, btnH: BTN_H };
GROVE.GROUND_Y = GROUND_Y;
GROVE.WALL_L = WALL_L;
GROVE.WALL_R = WALL_R;

/* ---------- Cocos 侧 API ----------
   原型里"取 canvas"和"起 requestAnimationFrame"是启动段的活；
   进了 Cocos 这两件事由 GroveBattle 组件接管，所以在这里开两个小口子。 */
export function groveAttachCanvas(c: any): void {
  cv = c;
  ctx = c.getContext("2d");
}
export function groveTick(dt: number): void { tick(dt); }
export function groveRender(): any { return render(); }

/* 美术图注入。原型要能双击打开、零依赖，所以 grove.html 里一张图都不引；
   进了 Cocos 由 GroveBattle 用 resources.load 拿到图，再从这个口子喂进来。
   有图贴图、没图回退代码图形 —— 两边都不会坏。
   键名：pet-<heroId> / head-<heroId> / ui-<name> */
export { groveSetArt };

/* 原型里鼠标事件直接挂在 canvas 上；进 Cocos 后画布是离屏的、不接 DOM 事件，
   事件源换成 GroveBattle 转发过来的指针坐标（已经是 960x600 画布坐标系）。 */
export function grovePointer(kind: "move" | "down", x: number, y: number): void {
  if (kind === "move") onCanvasMove({ x, y });
  else onCanvasDown({ x, y });
}
